-- Re-seeds occupations with the same data as 20260720000001, but with every
-- em dash removed from the prose fields (description, how_to_break_in,
-- typical_progression, common_misconceptions, interview_focus, bls_match_note)
-- per a hard no-em-dash rule for all site content. No field names, IDs, or
-- numeric values changed. See scripts/occupations-data.mjs.
delete from occupations;

insert into occupations (
  title, description, median_salary, growth_pct, education_level, top_skills, trait_profile, data_as_of,
  soc_code, bls_change_pct_2024_34, bls_median_wage_2024, bls_annual_openings_thousands, bls_match_confidence, bls_match_note,
  how_to_break_in, typical_progression, skills_to_build_first, common_misconceptions, interview_focus
)
values
  ('Investment Banking Analyst', 'Builds financial models and pitch materials for M&A deals and capital raises under intense deadline pressure.', 125000, 8, 'Bachelor''s degree', ARRAY['Financial modeling', 'Valuation', 'Excel/PowerPoint', 'Deal execution']::text[], '{"quadrant_a":0.93,"quadrant_b":0.5,"quadrant_c":0.2,"quadrant_d":0.15,"pace_preference":0.9,"risk_tolerance":0.5}'::jsonb, '2025-09-01'::date, '13-2051', 5.7, 101350, 25.1, 'close', 'BLS has no dedicated investment-banking-analyst code; mapped to Financial and Investment Analysts (13-2051), the broad category BLS/O*NET use for this kind of deal-analysis work.', 'Recruiting runs almost entirely through structured summer-analyst internships at target schools that convert to full-time offers. The internship functions as a months-long interview. Cold outreach and informational-interview networking matter a lot for non-target students trying to get first-round looks, but rarely replace the internship pipeline at bulge brackets and elite boutiques. The standard first title is ''Analyst'' in a 2-year program, often preceded by a sophomore-year ''summer analyst'' stint.', 'Analyst (2-3 yrs) leads to Associate (post-MBA or direct promote), then Vice President around year 6-8, then Director/SVP, then Managing Director around year 12-15, but most analysts exit after 2-3 years into private equity, hedge funds, or corporate roles rather than climbing the full ladder in-house.', ARRAY['Excel financial modeling (3-statement models)', 'Accounting fundamentals', 'Valuation methods (DCF, comps, precedents)', 'PowerPoint/pitch deck construction', 'Cold-outreach networking for interviews']::text[], 'People picture glamorous dealmaking; the first two years are mostly 80-100 hour weeks of formatting slides and rebuilding models for senior bankers, with minimal client-facing exposure. Most treat it explicitly as a 2-year credentialing program rather than a career destination.', 'Technical rounds test cold recall of accounting and valuation (walk through a DCF, trace a change in depreciation through all three statements) alongside ''why banking, why us'' fit questions. Behavioral rounds are really gauging stamina and attention to detail: whether you''ll survive the hours, not just whether you''re sharp.'),
  ('Private Equity Associate', 'Evaluates and executes buyout investments, working closely with portfolio companies to drive returns.', 175000, 9, 'Bachelor''s degree (often + IB experience)', ARRAY['LBO modeling', 'Due diligence', 'Deal sourcing', 'Portfolio strategy']::text[], '{"quadrant_a":0.9,"quadrant_b":0.3,"quadrant_c":0.25,"quadrant_d":0.45,"pace_preference":0.7,"risk_tolerance":0.6}'::jsonb, '2025-09-01'::date, '13-2051', 5.7, 101350, 25.1, 'approximate', 'No BLS code for private equity specifically; Financial and Investment Analysts (13-2051) is the closest general category, though PE deal sourcing/portfolio work is narrower than what BLS describes.', 'Overwhelmingly recruited from investment-banking analyst programs 2-3 years in, through a compressed, headhunter-run ''on-cycle'' process that happens 6-18 months before the job actually starts. Direct entry without a banking background is rare outside a handful of undergrad-targeted programs at growth-equity or lower-middle-market shops.', 'Associate for 2-3 years (often pre-MBA), then Senior Associate/VP after an MBA or internal promote, then Principal, then Partner/Managing Director, with carried interest (equity in fund profits) becoming the dominant compensation driver from Principal onward.', ARRAY['LBO modeling', 'Accounting and credit analysis', 'Company/industry diligence research', 'Investment memo writing', 'Core IB technical skills (the real prerequisite)']::text[], 'Outsiders picture glamorous boardroom strategy conversations; junior life is heavy modeling and diligence work, arguably more concentrated than banking since deal teams are smaller. People also underestimate how much of the job is passing on the vast majority of deals sourced.', 'The signature test is a timed LBO modeling exercise plus a ''paper LBO'' done by mental math. Interviewers also probe investment judgment directly: pitch a company and defend the thesis under real pushback, to see if you can form and hold a view, not just operate a model.'),
  ('Hedge Fund Analyst', 'Researches investment theses and market inefficiencies to inform active trading strategies.', 140000, 7, 'Bachelor''s degree', ARRAY['Fundamental research', 'Financial modeling', 'Market analysis', 'Risk/reward assessment']::text[], '{"quadrant_a":0.93,"quadrant_b":0.25,"quadrant_c":0.15,"quadrant_d":0.5,"pace_preference":0.75,"risk_tolerance":0.7}'::jsonb, '2025-09-01'::date, '13-2051', 5.7, 101350, 25.1, 'approximate', 'No BLS code for hedge fund analysts specifically; mapped to the broad Financial and Investment Analysts category (13-2051) as the closest available proxy.', 'Paths vary more than in banking: some funds recruit from IB/PE analyst programs, others (especially quant-oriented funds) hire straight from undergrad, and cold-emailing a well-researched stock pitch directly to a portfolio manager is a legitimate, sometimes celebrated way in at smaller funds. There''s no single standard pipeline, which makes this one of the more merit-pitch-driven corners of finance.', 'Junior/Research Analyst, then Senior Analyst covering a sector with real input into the book, then Portfolio Manager running a capital sleeve, sometimes eventually spinning out to launch an independent fund. Progression tracks P&L performance far more than tenure.', ARRAY['Building and defending investment theses (practice stock pitches)', 'Financial modeling', 'Reading 10-Ks/10-Qs closely', 'Forming and tracking daily market opinions', 'Statistics/programming if targeting quant-oriented funds']::text[], 'People picture Wall Street glamour; the daily reality is obsessive research and being wrong often: a good hit rate is barely above half. It''s also far less stable than banking since a purely performance-based culture means underperformers get cut regardless of effort.', 'The core test is a stock pitch: bring a specific idea, defend the valuation and thesis, and hold up under aggressive questioning of your assumptions. Interviewers care less about polish and more about independent thinking and how gracefully you handle being wrong.'),
  ('Equity Research Analyst', 'Publishes in-depth analysis and price targets on public companies for institutional investors.', 105000, 6, 'Bachelor''s degree (CFA common)', ARRAY['Financial modeling', 'Industry analysis', 'Report writing', 'Valuation']::text[], '{"quadrant_a":0.93,"quadrant_b":0.5,"quadrant_c":0.2,"quadrant_d":0.2,"pace_preference":0.55,"risk_tolerance":0.4}'::jsonb, '2025-09-01'::date, '13-2051', 5.7, 101350, 25.1, 'close', 'Equity research is a core example role within BLS''s Financial and Investment Analysts category (13-2051).', 'Entry is usually as a research associate supporting a senior sector analyst, hired from undergrad at target schools or after 1-2 years in banking; the CFA charter (or visible progress toward it) is a genuinely expected credential here in a way it isn''t in most other finance roles. Directly demonstrating sector knowledge and networking with sell-side analysts both carry real weight.', 'Associate, then Senior Associate, then Analyst covering your own sector and publishing under your own name, then Senior/Lead Analyst, with some analysts eventually moving to the buy side (asset management, hedge funds) where compensation ceilings are higher.', ARRAY['Financial modeling and forecasting', 'Sector/industry research', 'Clear, persuasive research-note writing', 'CFA coursework/exams', 'Public speaking for earnings and client calls']::text[], 'People assume it''s freely picking favorite stocks; sell-side analysts actually spend huge amounts of time on modeling minutiae, compliance, and maintaining relationships with company management and institutional clients, less pure ''investing'' than the buy-side version.', 'Expect a stock pitch plus deep sector-specific questions to test whether you already think like an analyst in that industry. Interviewers also assess writing (can you produce a sharp, clear note) and tolerance for detail-heavy, deadline-driven modeling.'),
  ('Quantitative Analyst', 'Builds mathematical models to price securities, manage risk, or drive systematic trading strategies.', 150000, 10, 'Master''s/Ph.D. (math, stats, or CS)', ARRAY['Stochastic calculus', 'Programming (Python/C++)', 'Statistical modeling', 'Algorithm design']::text[], '{"quadrant_a":0.97,"quadrant_b":0.25,"quadrant_c":0.05,"quadrant_d":0.4,"pace_preference":0.5,"risk_tolerance":0.45}'::jsonb, '2025-09-01'::date, '13-2051', 5.7, 101350, 25.1, 'close', 'BLS/O*NET classify quantitative analysts ("quants") under Financial and Investment Analysts (13-2051); no separate quant-specific code exists.', 'Almost universally requires a graduate degree (MS/PhD in math, stats, physics, CS, or financial engineering); competitive internships at quant funds or banks during grad school are the main pipeline, and results in Kaggle competitions or competitive math/programming (Putnam, ICPC) genuinely help. Cold outreach rarely works since recruiting centers on campus pipelines at a small set of target programs.', 'Quant Researcher/Analyst, then Senior Quant, then Team Lead/Strategist owning a book or model suite, then Head of Quant Research or a portfolio-manager role for quant-driven strategies, branching toward deeper research specialization or people management.', ARRAY['Advanced math/stats (stochastic calculus, linear algebra, probability)', 'Programming (Python, C++)', 'Machine learning fundamentals', 'Competitive math/programming credentials', 'Reading and reproducing research papers']::text[], 'Outsiders imagine constant novel model invention; a large share of the real job is data cleaning, backtest infrastructure, and defending a model against overfitting, far more engineering-heavy and collaborative than the lone-genius stereotype.', 'Interviews are famously rigorous: brainteasers, probability puzzles, mental math, and live coding/statistics problems across multiple rounds. Firms are testing raw quantitative horsepower and composure under pressure, not just credentials on paper.'),
  ('Sales & Trading Associate', 'Executes trades and manages institutional client relationships in fast-moving public markets.', 130000, 5, 'Bachelor''s degree', ARRAY['Market execution', 'Client relationship management', 'Risk assessment', 'Composure under pressure']::text[], '{"quadrant_a":0.3,"quadrant_b":0.25,"quadrant_c":0.85,"quadrant_d":0.5,"pace_preference":0.95,"risk_tolerance":0.75}'::jsonb, '2025-09-01'::date, '41-3031', 3.3, 78140, 38.1, 'close', 'Mapped to Securities, Commodities, and Financial Services Sales Agents (41-3031), which covers trade execution and institutional client work.', 'Recruiting mirrors banking''s structured campus pipeline and internship-to-offer track, but interviews weight composure and personality more heavily than modeling ability. Series 7/63 licensing is required once hired, not before; being fast with numbers and comfortable with confrontation matters more than a flawless GPA.', 'Associate/Analyst, then Trader or Salesperson running your own book or client list, then Senior Trader/Salesperson, then Desk Head, compensation shifts increasingly to being tied directly to P&L or client revenue rather than seniority alone.', ARRAY['Mental math speed', 'Market/macro literacy and having daily opinions', 'Composure and fast decision-making under pressure', 'Client relationship-building', 'Basic derivatives/product knowledge']::text[], 'People conflate this with research or banking; it''s a much faster, more verbal, less spreadsheet-heavy job, closer to live performance than analysis, with rapid real-time calls replacing careful modeling.', 'Interviews test composure under stress (rapid mental math, market questions with no time to prepare) and market awareness (pitch a trade idea, discuss current events with a view). Fit matters heavily since desks are small, high-pressure teams where personality clashes are costly.'),
  ('Wealth Manager / Financial Advisor', 'Builds long-term investment and financial plans for individual clients based on their goals and risk tolerance.', 99000, 13, 'Bachelor''s degree + CFP', ARRAY['Financial planning', 'Relationship building', 'Investment strategy', 'Client communication']::text[], '{"quadrant_a":0.45,"quadrant_b":0.3,"quadrant_c":0.88,"quadrant_d":0.2,"pace_preference":0.4,"risk_tolerance":0.35}'::jsonb, '2025-09-01'::date, '13-2052', 9.6, 102140, 24.1, 'exact', 'Direct match to BLS Personal Financial Advisors (13-2052).', 'Entry is often through a wirehouse or bank training program (Merrill, Morgan Stanley, etc.) that pairs you with a senior advisor''s book while you build your own clients, or independently through an RIA after earning the CFP. Early years are genuinely sales-heavy: cold calling, seminars, and mining your personal network for first clients is standard and expected, not optional.', 'Associate/Junior Advisor, then Advisor with a growing personal book, then Senior/Lead Advisor, then Partner or team lead managing junior advisors: success is measured almost entirely by assets under management gathered over time.', ARRAY['CFP coursework', 'Sales/prospecting skills (genuinely non-negotiable early on)', 'Core financial planning and investment concepts', 'Relationship-building and active listening', 'Series 7/66 licensing prep']::text[], 'People think it''s mostly picking investments; it''s overwhelmingly a sales and relationship business: portfolios are often built from templated model allocations while winning and retaining clients is the real daily work. The first 3-5 years are notoriously lean financially while building a book.', 'Interviews assess sales aptitude and resilience: can you handle repeated rejection, do you have a real network to draw on, more than technical finance knowledge. Firms often ask candidates to map their existing personal and professional network as a proxy for early client-acquisition potential.'),
  ('Corporate Finance Analyst (FP&A)', 'Builds budgets and forecasts, analyzing company performance to guide internal business decisions.', 87000, 7, 'Bachelor''s degree', ARRAY['Financial forecasting', 'Variance analysis', 'Excel modeling', 'Business partnering']::text[], '{"quadrant_a":0.88,"quadrant_b":0.5,"quadrant_c":0.3,"quadrant_d":0.15,"pace_preference":0.45,"risk_tolerance":0.25}'::jsonb, '2025-09-01'::date, '13-2051', 5.7, 101350, 25.1, 'close', 'FP&A work (forecasting, budgeting, variance analysis) falls under BLS''s broad Financial and Investment Analysts category (13-2051); no dedicated FP&A code exists.', 'Entry-level FP&A roles are commonly filled straight from undergrad finance/accounting majors or via rotational leadership-development programs at large corporations; unlike IB, this field is genuinely open to non-target schools and direct applications work reasonably well. Some enter after 2-3 years in public accounting or audit.', 'FP&A Analyst, then Senior Analyst, then FP&A Manager owning a business unit''s forecast, then Director of FP&A, then VP Finance/CFO track, the ladder often leads toward business-partnering leadership or eventually a CFO seat.', ARRAY['Excel modeling and forecasting', 'Accounting fundamentals', 'Business partnering/communication with non-finance stakeholders', 'PowerPoint and data storytelling', 'ERP/reporting tools (SAP, Oracle, Adaptive)']::text[], 'People assume it''s just building spreadsheets; a large part of the real job is influencing decisions by translating numbers into a story executives will actually act on: the partnering half matters as much as the modeling half.', 'Interviews test practical Excel/modeling ability (build a quick forecast, walk through a variance analysis) and business judgment (how would you investigate a budget miss). Communication is scrutinized closely since the role requires explaining numbers to non-finance leaders.'),
  ('Risk Analyst (Financial)', 'Identifies and models exposure to market, credit, and operational risk for a bank or asset manager.', 95000, 6, 'Bachelor''s degree', ARRAY['Risk modeling', 'Statistics', 'Regulatory knowledge', 'Scenario analysis']::text[], '{"quadrant_a":0.92,"quadrant_b":0.55,"quadrant_c":0.15,"quadrant_d":0.15,"pace_preference":0.4,"risk_tolerance":0.15}'::jsonb, '2025-09-01'::date, '13-2054', 6.5, 106000, 4.8, 'close', 'Matches BLS Financial Risk Specialists (13-2054), the 2018-SOC-revision category covering market/credit/operational risk analysis.', 'Entry is typically through bank or asset-manager analyst programs or direct hire from undergrad with a quantitative major (finance, math, stats, econ); the FRM (Financial Risk Manager) certification signals seriousness and is commonly pursued in the first few years on the job.', 'Risk Analyst, then Senior Risk Analyst, then Risk Manager owning a risk category or portfolio, then Director of Risk, then Chief Risk Officer, specialization typically deepens into market, credit, or operational risk along the way.', ARRAY['Statistics and probability', 'Financial modeling', 'Regulatory frameworks (Basel, Dodd-Frank basics)', 'SQL/Python for data analysis', 'FRM exam coursework']::text[], 'People think risk is a quiet back-office function; at serious institutions risk analysts have real veto power over trades and deals, and the job requires defending unpopular conclusions to senior, aggressive risk-takers: that friction is underestimated from outside.', 'Interviews test statistical and quantitative reasoning (VaR concepts, scenario analysis) and regulatory literacy, plus scenarios on how you''d flag and escalate a risk that a profitable desk doesn''t want to hear about.'),
  ('Credit Analyst', 'Assesses the creditworthiness of borrowers to guide lending decisions for a bank or credit fund.', 82000, 5, 'Bachelor''s degree', ARRAY['Financial statement analysis', 'Credit risk modeling', 'Industry research', 'Report writing']::text[], '{"quadrant_a":0.9,"quadrant_b":0.55,"quadrant_c":0.2,"quadrant_d":0.1,"pace_preference":0.35,"risk_tolerance":0.15}'::jsonb, '2025-09-01'::date, '13-2041', -4.4, 80970, 3.7, 'exact', 'Direct match to BLS Credit Analysts (13-2041).', 'Entry-level roles are commonly filled from undergrad finance/accounting majors via bank credit training programs, or by people moving over from accounting/audit. It''s one of the more accessible entry points into finance from non-target schools since the core skill, careful financial-statement analysis, is teachable and demonstrable through coursework.', 'Credit Analyst, then Senior Credit Analyst, then Credit Officer/Underwriter with signing authority, then Portfolio or Relationship Manager, then Director of Credit, often eventually managing a loan book or moving into commercial-banking relationship management.', ARRAY['Financial statement analysis (reading a 10-K or private company financials)', 'Credit ratio analysis', 'Industry research', 'Written memo/report writing', 'Core accounting']::text[], 'People think it''s just running a credit score; real commercial credit analysis is closer to mini equity research: assessing an entire business and its cash flows, then defending a lending recommendation in committee.', 'Interviews test financial-statement analysis directly (spread these financials, assess creditworthiness) and judgment under uncertainty: can you make a defensible recommendation with incomplete information.'),
  ('Portfolio Manager', 'Makes final buy/sell decisions across a fund''s holdings, balancing return targets against risk limits.', 165000, 6, 'Bachelor''s degree (CFA common)', ARRAY['Investment strategy', 'Risk management', 'Decision-making under uncertainty', 'Market judgment']::text[], '{"quadrant_a":0.88,"quadrant_b":0.3,"quadrant_c":0.25,"quadrant_d":0.5,"pace_preference":0.65,"risk_tolerance":0.65}'::jsonb, '2025-09-01'::date, '13-2051', 5.7, 101350, 25.1, 'close', 'O*NET nests "Portfolio Manager" as a sample job title under Financial and Investment Analysts (13-2051); no standalone portfolio-manager code exists.', 'This is not a first job. It''s earned after years as an analyst (equity research, hedge fund, or similar) proving a real investment track record; there''s no direct entry path. The realistic route is analyst, then senior analyst, then being handed a small capital sleeve to manage, then full PM.', 'Analyst, then Senior Analyst, then PM managing a small book or sleeve, then PM managing a full fund or strategy, then CIO or founding an independent fund, track record is the only real currency for promotion.', ARRAY['Deep investment research and modeling (built first as an analyst)', 'Risk management/position sizing', 'Decision-making under uncertainty', 'Building a demonstrable track record, even via a paper portfolio', 'Market pattern recognition']::text[], 'People think PMs just pick stocks all day; a huge part of the real job is risk management and portfolio construction: sizing positions, managing drawdowns, and saying no to good ideas that don''t fit the portfolio, not only sourcing new ideas.', 'For PM-track hires, interviews focus on your realized investment track record and thesis defense under hostile questioning: how you sized a position, what you got wrong, and how you managed risk, not just what you got right.'),
  ('M&A Analyst', 'Supports mergers and acquisitions from valuation through deal close, coordinating across legal, finance, and strategy.', 115000, 8, 'Bachelor''s degree', ARRAY['Valuation', 'Deal structuring', 'Due diligence', 'Cross-functional coordination']::text[], '{"quadrant_a":0.88,"quadrant_b":0.55,"quadrant_c":0.3,"quadrant_d":0.25,"pace_preference":0.75,"risk_tolerance":0.5}'::jsonb, '2025-09-01'::date, '13-2051', 5.7, 101350, 25.1, 'approximate', 'No dedicated M&A-analyst code; mapped to the broad Financial and Investment Analysts category (13-2051) as the closest deal-analysis proxy.', 'Recruiting mirrors investment banking, structured campus pipelines and summer internships at banks or corporate-development teams, with Excel and accounting fundamentals tested in first-round technicals. In-house corporate development roles sometimes hire directly from consulting or banking after 2-3 years rather than from undergrad.', 'Analyst, then Associate, then VP of Corporate Development or M&A, then Director, then Head of Corporate Development, many analysts exit after 2-3 years into strategy or operating roles at companies they used to advise.', ARRAY['Valuation and financial modeling', 'Due diligence process knowledge', 'Cross-functional project coordination', 'Excel/PowerPoint', 'Deal-process literacy (LOIs, purchase agreement basics)']::text[], 'People imagine dramatic negotiation scenes; daily reality is coordinating dozens of workstreams: legal, tax, HR, IT, and chasing data-room documents. For junior staff, deal execution is more project management than dealmaking.', 'Technical rounds test valuation and modeling like banking; behavioral rounds emphasize coordinating projects under deadline pressure and staying organized across many stakeholders with incomplete information.'),
  ('Chief Financial Officer', 'Owns a company''s financial strategy, reporting, and capital decisions at the executive level.', 245000, 6, 'Bachelor''s/MBA + extensive experience', ARRAY['Financial strategy', 'Executive leadership', 'Capital allocation', 'Board communication']::text[], '{"quadrant_a":0.85,"quadrant_b":0.3,"quadrant_c":0.5,"quadrant_d":0.25,"pace_preference":0.5,"risk_tolerance":0.4}'::jsonb, '2025-09-01'::date, '11-3031', 14.8, 161700, 74.6, 'close', 'CFO is an explicit example job title under BLS Financial Managers (11-3031).', 'There''s no entry-level path: this is a 15-20 year capstone role reached via accounting/audit, FP&A, investment banking, or controller tracks, typically requiring a CPA and/or MBA plus proven experience owning a P&L or major finance function. Internal promotion from VP Finance/Controller is the most common route; external hires usually already have prior CFO or deputy-CFO experience.', 'Staff Accountant/Analyst, then Controller or FP&A Director, then VP Finance, then CFO, lateral moves through treasury, investor relations, or business-unit finance are often used to broaden the profile needed for the top job.', ARRAY['Accounting/CPA fundamentals', 'Financial strategy and capital allocation', 'Board and investor communication', 'Cross-functional leadership', 'Fundraising or capital markets experience']::text[], 'People think the CFO just ''does the numbers''; in practice the job is largely narrative and trust: communicating company health to the board, investors, and Wall Street, and making high-stakes capital allocation calls with real strategic consequences.', 'For CFO-level searches, boards test strategic judgment (capital allocation scenarios), crisis-management stories, and communication polish, can this person credibly represent the company to investors, far more than technical accounting detail.'),
  ('Real Estate Investment Analyst', 'Evaluates commercial property acquisitions and development deals through financial modeling.', 98000, 7, 'Bachelor''s degree', ARRAY['Real estate modeling', 'Market analysis', 'Deal underwriting', 'Excel']::text[], '{"quadrant_a":0.88,"quadrant_b":0.5,"quadrant_c":0.2,"quadrant_d":0.3,"pace_preference":0.5,"risk_tolerance":0.5}'::jsonb, '2025-09-01'::date, '13-2051', 5.7, 101350, 25.1, 'approximate', 'No real-estate-specific investment analyst code; mapped to the broad Financial and Investment Analysts category (13-2051).', 'Entry is typically through undergrad real estate/finance programs feeding into REITs, real estate PE shops, or brokerage investment-sales teams; unlike corporate IB, cold outreach to boutique real estate shops works reasonably well because the industry is smaller and more relationship-driven. Argus Enterprise (the industry-standard modeling software) proficiency is a genuinely valued, learnable credential.', 'Analyst, then Senior Analyst/Associate, then Acquisitions or Asset Management VP, then Director, then Principal/Partner, often eventually specializing by property type (multifamily, industrial, office) or moving into development.', ARRAY['Real estate financial modeling (Argus, Excel)', 'Market and submarket research', 'Deal underwriting fundamentals', 'Real estate terminology (cap rates, NOI, IRR)', 'Networking within local real estate circles']::text[], 'People think it''s property management; investment analysis is a finance-heavy underwriting job closer to private equity than to leasing or managing buildings day-to-day.', 'Interviews test underwriting ability directly (build a quick pro forma, calculate a cap rate or IRR) and market knowledge of a specific property type or region: genuine local market fluency stands out.'),
  ('Actuary', 'Uses statistics and financial theory to assess risk for insurance, pensions, and investment decisions.', 120000, 22, 'Bachelor''s degree + actuarial exams', ARRAY['Statistics', 'Risk modeling', 'Probability', 'Programming']::text[], '{"quadrant_a":0.97,"quadrant_b":0.5,"quadrant_c":0.1,"quadrant_d":0.15,"pace_preference":0.3,"risk_tolerance":0.15}'::jsonb, '2025-09-01'::date, '15-2011', 21.8, 125770, 2.4, 'exact', 'Direct match to BLS Actuaries (15-2011).', 'This field has an unusually objective entry path: passing 2-3 actuarial exams (through the SOA or CAS) before graduating dramatically improves hiring odds, and internships at insurers during college are the standard pipeline. It''s one of the few finance-adjacent fields where credentialing, not networking, is the primary gatekeeper.', 'Actuarial Analyst studying for exams, then Associate Actuary (ASA/ACAS, roughly 2-4 exams in), then Fellow Actuary (FSA/FCAS, all exams passed, around year 7-10), then Actuarial Manager/Director, then Chief Actuary: pay jumps meaningfully at each credential milestone.', ARRAY['Passing actuarial exams (start with Probability and Financial Math)', 'Statistics and probability theory', 'Excel/programming (SQL, R, Python)', 'Business communication', 'Time management for exam study alongside full-time work']::text[], 'People assume it''s just math; the job increasingly blends technical modeling with business communication, and the real lifestyle surprise is that studying 200+ hours per exam continues for 7-10 years after you''re hired, not just in school.', 'Entry-level interviews weight exam progress heavily (how many have you passed) alongside basic behavioral fit; technical case questions are rare early on since the exams already prove quantitative competence.'),
  ('Public Accountant / Auditor', 'Prepares and examines financial records at a public accounting firm, ensuring accuracy and regulatory compliance.', 82000, 4, 'Bachelor''s degree + CPA', ARRAY['GAAP', 'Attention to detail', 'Excel', 'Regulatory compliance']::text[], '{"quadrant_a":0.5,"quadrant_b":0.92,"quadrant_c":0.15,"quadrant_d":0.05,"pace_preference":0.35,"risk_tolerance":0.1}'::jsonb, '2025-09-01'::date, '13-2011', 4.6, 81680, 124.2, 'close', 'Matches BLS Accountants and Auditors (13-2011), which combines public, private, and government accountants into one category.', 'The standard path is campus recruiting into a Big 4 or regional accounting firm straight from an accounting degree, with the CPA exam (150 credit hours required) as the core credential; recruiting is unusually structured and predictable compared to most fields, with clear deadlines and case-free interviews.', 'Staff Auditor, then Senior Auditor around year 2-3, then Manager around year 5-6, then Senior Manager, then Partner around year 12-15, though most leave public accounting for industry roles after 2-5 years, a well-known pipeline sometimes called ''Big 4 to industry.''', ARRAY['CPA exam coursework', 'GAAP/accounting fundamentals', 'Excel', 'Attention to detail and documentation discipline', 'Basic client communication']::text[], 'People think auditing is boring bean-counting with no growth; it''s actually one of the most reliable credentialing paths into senior corporate finance roles, and busy-season reality (Jan-Apr, 60+ hour weeks) surprises people expecting a standard 9-5.', 'Interviews are fit-heavy and fairly standardized: behavioral questions about teamwork, deadlines, and ethics, since technical accounting knowledge is assumed from the degree; firms mainly screen for reliability and client-facing fit.'),
  ('Economist', 'Studies production and distribution of resources, forecasts trends, and advises on policy or business strategy.', 115730, 5, 'Master''s degree', ARRAY['Econometrics', 'Statistical modeling', 'Research', 'Writing']::text[], '{"quadrant_a":0.9,"quadrant_b":0.3,"quadrant_c":0.25,"quadrant_d":0.4,"pace_preference":0.3,"risk_tolerance":0.2}'::jsonb, '2025-09-01'::date, '19-3011', 1.2, 115440, 0.9, 'exact', 'Direct match to BLS Economists (19-3011).', 'Most substantive economist roles (government, think tank, corporate) require a Master''s or PhD; a Bachelor''s alone typically leads to research-assistant roles that serve as a stepping stone to grad school. Pre-doctoral RA positions at the Fed, World Bank, or academic labs are a well-known, competitive on-ramp for those aiming at a PhD.', 'Research Assistant, then Economist/Associate Economist with a Master''s, then Senior Economist, then Chief or Principal Economist, PhD holders often enter at a higher band, and academia offers a parallel professor track.', ARRAY['Econometrics/statistics', 'Programming (R, Stata, Python)', 'Academic/technical writing', 'Economic theory fundamentals', 'Research design']::text[], 'People imagine economists predicting the stock market; most working economists build empirical models to answer narrow policy or business questions, and forecasting the macroeconomy is a small, humbling slice of the actual field.', 'Interviews for research-heavy roles test econometrics and study design (how would you isolate this effect from confounders) and often include a writing sample or research presentation to assess communicating technical findings to non-economists.'),
  ('Compliance Officer', 'Ensures organizational adherence to financial and legal regulations through structured audits and policy enforcement.', 88000, 5, 'Bachelor''s degree', ARRAY['Regulatory knowledge', 'Audit procedure', 'Policy writing', 'Attention to detail']::text[], '{"quadrant_a":0.5,"quadrant_b":0.92,"quadrant_c":0.3,"quadrant_d":0.05,"pace_preference":0.35,"risk_tolerance":0.1}'::jsonb, '2025-09-01'::date, '13-1041', 3, 78420, 33.3, 'exact', 'Direct match to BLS Compliance Officers (13-1041).', 'Entry is common via internal transfer from operations, legal, or audit roles at a bank or financial firm, or direct hire into compliance-analyst seats from a business or legal background; a paralegal or legal-adjacent background is a legitimate on-ramp, and certifications like the CRCM or CAMS build credibility without requiring a J.D.', 'Compliance Analyst, then Compliance Officer, then Senior Compliance Manager, then Chief Compliance Officer, having been through actual SEC/FINRA regulatory exams becomes increasingly valuable currency for promotion.', ARRAY['Regulatory literacy (SEC, FINRA, or relevant regulator rules)', 'Policy writing', 'Audit/documentation discipline', 'Basic legal reasoning', 'CAMS/CRCM certification coursework']::text[], 'People assume it''s a low-stakes checkbox job; compliance officers are often the last line of defense against fines or scandal and must be willing to say no to profitable business lines, which creates real organizational friction.', 'Interviews test regulatory knowledge specific to the business (broker-dealer rules, AML/KYC, etc.) and judgment scenarios: how would you handle a manager pressuring you to overlook a violation, to gauge integrity under pressure.'),
  ('Treasury Analyst', 'Manages a company''s cash, liquidity, and financial risk to keep operations funded and protected.', 84000, 6, 'Bachelor''s degree', ARRAY['Cash management', 'Financial risk analysis', 'Forecasting', 'Banking relationships']::text[], '{"quadrant_a":0.85,"quadrant_b":0.5,"quadrant_c":0.3,"quadrant_d":0.15,"pace_preference":0.45,"risk_tolerance":0.2}'::jsonb, '2025-09-01'::date, '13-2099', 3.1, 80190, 10.3, 'approximate', 'No dedicated treasury-analyst code; mapped to the catch-all Financial Specialists, All Other (13-2099) since cash/liquidity management doesn''t cleanly fit Financial and Investment Analysts.', 'Entry-level treasury roles are typically filled from finance/accounting undergrads via corporate rotational programs or directly into a treasury-analyst seat; some enter after a stint in corporate/commercial banking on the lender side, bringing cash-management expertise with them.', 'Treasury Analyst, then Senior Treasury Analyst, then Treasury Manager, then Assistant Treasurer, then Treasurer/VP Treasury, often reporting toward the CFO and sometimes serving as a stepping stone to broader corporate finance leadership.', ARRAY['Cash flow forecasting', 'Banking relationship basics', 'Financial risk concepts (FX, interest-rate hedging)', 'Excel modeling', 'ERP/treasury management systems']::text[], 'People think treasury is just ''managing the bank account''; it actually involves real risk management, hedging currency and interest-rate exposure, and can carry significant responsibility for keeping a company solvent during a liquidity crunch.', 'Interviews test cash forecasting and basic hedging concepts, plus scenario questions about managing liquidity risk: what would you do if a major customer payment is delayed and payroll is due.'),
  ('Software Engineer', 'Designs, builds, and debugs software systems, balancing structured logic with creative problem-solving.', 130160, 17, 'Bachelor''s degree', ARRAY['Programming', 'Systems thinking', 'Debugging', 'Algorithm design']::text[], '{"quadrant_a":0.88,"quadrant_b":0.3,"quadrant_c":0.15,"quadrant_d":0.45,"pace_preference":0.45,"risk_tolerance":0.35}'::jsonb, '2025-09-01'::date, '15-1252', 15.8, 133080, 115.2, 'exact', 'Direct match to BLS Software Developers (15-1252).', 'Internships (especially at well-known companies) are the strongest signal, followed by a portfolio of real personal projects or open-source contributions and demonstrated algorithm proficiency for technical screens. A CS degree is common but increasingly non-required if you can pass the same technical bar: bootcamp grads and self-taught developers get in via strong GitHub portfolios and referrals, though the market has tightened noticeably for junior roles recently.', 'Junior/SWE I, then SWE II/Mid-level around year 2-3, then Senior Engineer around year 5, then Staff/Principal Engineer or Engineering Manager around year 8-10, from Senior onward the ladder forks between a technical individual-contributor track (Staff/Principal/Distinguished) and a people-management track (EM/Director/VP).', ARRAY['Data structures & algorithms for interviews', 'One core language mastered deeply, not many shallowly', 'Building and shipping real projects end-to-end', 'Git/version control workflows', 'Reading and debugging other people''s code']::text[], 'People imagine constant novel invention; most day-to-day work is reading existing code, fixing bugs, writing tests, and navigating legacy systems. Genuine green-field building is rare outside the earliest-stage startups. The solitary-genius stereotype also undersells how collaborative and meeting-heavy the job becomes with seniority.', 'Interviews center on live coding/algorithm problems and complexity analysis, plus system design rounds at mid-to-senior levels (design a scalable service). Behavioral rounds probe collaboration and handling disagreement or ambiguous requirements, since technical skill alone isn''t sufficient at strong companies.'),
  ('Machine Learning Engineer', 'Builds and deploys models that let software learn from data, from research prototypes to production systems.', 155000, 26, 'Bachelor''s/Master''s degree', ARRAY['Machine learning', 'Python', 'Model deployment', 'Statistics']::text[], '{"quadrant_a":0.92,"quadrant_b":0.3,"quadrant_c":0.1,"quadrant_d":0.5,"pace_preference":0.5,"risk_tolerance":0.45}'::jsonb, '2025-09-01'::date, '15-1252', 15.8, 133080, 115.2, 'approximate', 'BLS has no dedicated ML-engineer code; mapped to Software Developers (15-1252) since ML engineering is fundamentally applied software engineering, though it also overlaps with Data Scientists (15-2051).', 'Typically requires demonstrable ML project work: Kaggle competitions, a deployed side project, or research publications, layered on top of solid software engineering fundamentals; many enter via a general SWE role first and transition internally, since ML engineering is as much engineering as modeling. A Master''s is common though not universally required if the portfolio is strong.', 'ML Engineer, then Senior ML Engineer, then Staff ML Engineer or ML Lead, then Principal ML Engineer or Head of ML, the fork between deep technical IC work and managing an ML team happens around the senior/staff transition, similar to general software engineering.', ARRAY['Python and core ML frameworks (PyTorch/TensorFlow)', 'Software engineering fundamentals beyond modeling notebooks', 'Statistics and applied ML theory', 'Model deployment/MLOps basics', 'A portfolio of end-to-end deployed projects']::text[], 'People think it''s mostly training exciting new models; the actual job is dominated by data cleaning, pipeline engineering, and the unglamorous work of getting a model reliably into production and monitored: training itself is a small fraction of total time.', 'Interviews mix general software engineering coding rounds with ML-specific questions (explain overfitting, the bias-variance tradeoff, how you''d evaluate a model) and often a take-home or case study building and deploying a small model.'),
  ('AI Research Scientist', 'Pushes the boundary of what machine learning can do, publishing and prototyping novel model architectures.', 175000, 23, 'Ph.D. (or exceptional Master''s)', ARRAY['Deep learning theory', 'Research methodology', 'Programming', 'Mathematical reasoning']::text[], '{"quadrant_a":0.95,"quadrant_b":0.25,"quadrant_c":0.1,"quadrant_d":0.55,"pace_preference":0.35,"risk_tolerance":0.55}'::jsonb, '2025-09-01'::date, '15-1221', 19.7, 140910, 3.2, 'exact', 'Direct match to BLS Computer and Information Research Scientists (15-1221), which explicitly covers frontier ML/AI research.', 'Almost always requires a PhD (or, rarely, an exceptional Master''s with strong publications) from a program with a serious ML/AI research group; publishing at top venues (NeurIPS, ICML, ICLR) during the PhD is the real credential that opens doors. Research internships at major AI labs during the PhD are the standard pipeline into full-time offers.', 'PhD/postdoc, then Research Scientist, then Senior Research Scientist, then Staff/Principal Research Scientist or Research Lead managing a small team, the ceiling is often set by publication impact and idea originality, not tenure alone.', ARRAY['Deep learning theory and mathematics', 'Reading and reproducing papers from scratch', 'Original research idea generation', 'Programming for research (PyTorch/JAX)', 'Academic writing and publishing']::text[], 'People imagine free-ranging exploration of big ideas; the reality involves enormous amounts of failed experiments, infrastructure wrangling, and competitive pressure to publish before others: most experiments don''t work, and resilience to repeated failure matters as much as raw brilliance.', 'Interviews include deep technical discussion of your published research, math/ML theory questions, and sometimes a research-style open problem to reason through live: evaluators are gauging original thinking, not just implementation skill.'),
  ('Data Engineer', 'Builds the pipelines and infrastructure that move and clean data so analysts and models can use it reliably.', 128000, 21, 'Bachelor''s degree', ARRAY['Data pipelines', 'SQL', 'Distributed systems', 'Cloud infrastructure']::text[], '{"quadrant_a":0.85,"quadrant_b":0.5,"quadrant_c":0.1,"quadrant_d":0.25,"pace_preference":0.45,"risk_tolerance":0.25}'::jsonb, '2025-09-01'::date, '15-1243', 8.7, 135980, 4, 'approximate', 'No dedicated data-engineer code; mapped to Database Architects (15-1243) as the closest available category, though data engineering (pipelines/ETL) is broader than database architecture as BLS defines it.', 'Common entry paths are a CS/related degree into a data or software engineering role, or transitioning from a data analyst/BI role by building strong SQL and pipeline skills; unlike data science, this field is less credentialed by advanced degrees and more by demonstrated ability to build reliable, scalable pipelines.', 'Data Engineer, then Senior Data Engineer, then Staff Data Engineer or Data Engineering Lead, then Principal Engineer or Head of Data Platform, the ladder often forks into deep infrastructure specialization versus managing a data platform team.', ARRAY['SQL mastered deeply, not just basics', 'A pipeline programming language (Python/Scala)', 'Distributed systems concepts (Spark, Kafka)', 'Cloud data warehousing (Snowflake, BigQuery, Redshift)', 'Data modeling fundamentals']::text[], 'People confuse this with data science; data engineers rarely build models: they build and maintain the invisible infrastructure that makes everyone else''s analysis possible, and success is measured by pipeline reliability and uptime, not insights delivered.', 'Interviews test SQL depth, system design for data pipelines (design a system to ingest and process X events per day), and sometimes a Python/Scala coding round: practical engineering judgment matters more than theoretical algorithms.'),
  ('DevOps / Site Reliability Engineer', 'Keeps production systems running, automating deployment and responding to outages under pressure.', 132000, 15, 'Bachelor''s degree', ARRAY['Cloud infrastructure', 'Automation', 'Incident response', 'Systems monitoring']::text[], '{"quadrant_a":0.55,"quadrant_b":0.9,"quadrant_c":0.15,"quadrant_d":0.2,"pace_preference":0.8,"risk_tolerance":0.3}'::jsonb, '2025-09-01'::date, '15-1244', -4.2, 96800, 14.3, 'approximate', 'No dedicated DevOps/SRE code; mapped to Network and Computer Systems Administrators (15-1244), though modern DevOps/SRE work (cloud automation, incident response for software) extends well beyond the LAN/WAN administration BLS describes.', 'Common entry paths are transitioning from software engineering or sysadmin/IT into DevOps, or entering directly via cloud certifications (AWS/Azure/GCP) that substitute for a traditional CS pipeline; on-call experience and demonstrated incident-response instincts, even from a help-desk background, carry real weight.', 'DevOps/SRE Engineer, then Senior SRE, then Staff SRE or SRE Team Lead, then Principal Engineer or Head of Infrastructure/Platform, the ladder can also lead toward engineering management overseeing platform reliability for an entire org.', ARRAY['Linux/systems fundamentals', 'Cloud platforms (AWS/Azure/GCP) and certifications', 'Infrastructure as code (Terraform, Ansible)', 'Scripting (Python/Bash)', 'CI/CD pipeline design']::text[], 'People think it''s just ''keeping servers running'' passively; the real job includes being paged at 3am for outages, and a large part of seniority is designing systems so that failures are boring rather than catastrophic: prevention, not just firefighting.', 'Interviews test troubleshooting under simulated pressure (here''s a broken system, diagnose it live) and infrastructure design (design a highly-available deployment pipeline), plus behavioral questions about real incidents and postmortems.'),
  ('Cloud Solutions Architect', 'Designs large-scale cloud infrastructure that balances cost, reliability, and performance for a business.', 145000, 15, 'Bachelor''s degree', ARRAY['Cloud platforms (AWS/Azure/GCP)', 'Systems architecture', 'Cost optimization', 'Technical communication']::text[], '{"quadrant_a":0.85,"quadrant_b":0.5,"quadrant_c":0.3,"quadrant_d":0.3,"pace_preference":0.45,"risk_tolerance":0.3}'::jsonb, '2025-09-01'::date, '15-1241', 11.9, 130390, 11.2, 'approximate', 'No dedicated cloud-architect code; mapped to Computer Network Architects (15-1241), though cloud solutions architecture covers more than network design (also compute, storage, cost).', 'Typically requires several years as a software or infrastructure engineer first, then cloud certifications (AWS Solutions Architect, Azure Architect) that formally validate the jump to architecture; consulting firms and cloud vendors themselves (AWS, Microsoft, Google) are common employers hiring architects with client-facing engineering backgrounds.', 'Cloud Engineer, then Senior Cloud Engineer, then Solutions Architect, then Principal/Chief Architect, then Head of Cloud/Infrastructure Strategy, many architects also move into pre-sales engineering roles at cloud vendors, blending technical depth with client persuasion.', ARRAY['Deep expertise in one cloud platform before generalizing', 'Cloud certifications (AWS/Azure/GCP)', 'Systems architecture design patterns', 'Cost optimization analysis', 'Technical communication to non-technical stakeholders']::text[], 'People think it''s a pure technical design role; a large part of the actual job is translating business constraints, such as budget, timeline, and compliance, into architecture decisions and defending those tradeoffs to executives, not just picking the ''best'' technology.', 'Interviews test system design under real-world constraints (design this for cost, this for compliance, this for scale) and communication: can you explain a complex tradeoff clearly to a non-technical stakeholder, alongside platform certification knowledge.'),
  ('Computer Vision Engineer', 'Builds systems that let machines interpret images and video, from research to real-world deployment.', 148000, 20, 'Bachelor''s/Master''s degree', ARRAY['Computer vision', 'Deep learning', 'Python/C++', 'Mathematical modeling']::text[], '{"quadrant_a":0.92,"quadrant_b":0.3,"quadrant_c":0.1,"quadrant_d":0.5,"pace_preference":0.45,"risk_tolerance":0.4}'::jsonb, '2025-09-01'::date, '15-1252', 15.8, 133080, 115.2, 'approximate', 'No dedicated computer-vision-engineer code; mapped to Software Developers (15-1252) as the closest general engineering category.', 'Usually requires a Bachelor''s/Master''s with strong coursework in CV/deep learning plus a demonstrable project portfolio: a working object-detection or segmentation project counts for a lot; research internships or CV-focused Kaggle competitions are a strong differentiator, and some enter via general ML engineering roles that pivot into CV.', 'CV Engineer, then Senior CV Engineer, then Staff/Lead CV Engineer, then Principal Engineer or CV Research Lead, progression often ties to moving from applying existing architectures to developing novel ones for a specific domain (autonomous vehicles, medical imaging, robotics).', ARRAY['Deep learning fundamentals (CNNs, transformers for vision)', 'Python and CV libraries (OpenCV, PyTorch)', 'Linear algebra and image processing math', 'Building end-to-end deployed CV projects', 'Reading recent CV papers']::text[], 'People imagine mostly training exciting models on clean datasets; real CV work involves painstaking data labeling/curation and handling messy real-world image conditions, such as lighting, occlusion, and sensor noise, that make deployed accuracy far harder than benchmark accuracy.', 'Interviews combine general ML/coding rounds with CV-specific depth (explain how a CNN or attention mechanism works, debug why a model fails on edge cases) and often a take-home project applying a vision model to a real dataset.'),
  ('Robotics Engineer', 'Designs and programs robotic systems that sense, decide, and act in the physical world.', 108000, 12, 'Bachelor''s/Master''s degree', ARRAY['Controls engineering', 'Programming', 'Mechanical design', 'Systems integration']::text[], '{"quadrant_a":0.88,"quadrant_b":0.25,"quadrant_c":0.1,"quadrant_d":0.45,"pace_preference":0.4,"risk_tolerance":0.35}'::jsonb, '2025-09-01'::date, '17-2199', 2.1, 117750, 9.3, 'close', 'O*NET nests Robotics Engineers under BLS''s Engineers, All Other (17-2199), the catch-all for engineering specialties without their own SOC code.', 'Typically requires a Bachelor''s/Master''s in mechanical, electrical, or robotics-specific engineering with hands-on project experience: university robotics teams and competition experience (FIRST Robotics alumni) are a genuinely strong signal recruiters look for. Internships at robotics/automation companies are the standard pipeline; the field rewards demonstrated hands-on building over pure coursework.', 'Robotics Engineer, then Senior Robotics Engineer, then Staff Engineer or Robotics Team Lead, then Principal Engineer or Head of Robotics, the ladder can specialize into controls, perception, or mechanical design tracks, or move toward managing cross-disciplinary robotics teams.', ARRAY['Controls engineering fundamentals', 'Programming (C++/Python, ROS)', 'Mechanical/electrical design basics', 'Hands-on prototyping and building', 'Systems integration across hardware and software']::text[], 'People imagine building dramatic humanoid robots; most real robotics work is narrow and industrial: a specific arm doing a specific repeatable task reliably, and a huge share of time goes to hardware debugging and integration issues that have nothing to do with algorithms.', 'Interviews test both software (coding, algorithms relevant to controls/perception) and hands-on engineering judgment (walk through a project you built, debug a described system failure), often including a portfolio review of past robots or projects.'),
  ('Blockchain Developer', 'Builds decentralized applications and smart contracts on emerging, fast-changing infrastructure.', 135000, 12, 'Bachelor''s degree', ARRAY['Smart contracts', 'Cryptography basics', 'Programming', 'Distributed systems']::text[], '{"quadrant_a":0.5,"quadrant_b":0.2,"quadrant_c":0.15,"quadrant_d":0.88,"pace_preference":0.5,"risk_tolerance":0.7}'::jsonb, '2025-09-01'::date, '15-1252', 15.8, 133080, 115.2, 'approximate', 'No dedicated blockchain-developer code; mapped to Software Developers (15-1252) as the closest general category.', 'Largely self-taught and portfolio-driven: there''s no established academic pipeline, so shipping real smart contracts (even on testnets), contributing to open-source protocols, and being active in developer communities genuinely substitutes for credentials. Hackathon wins are a well-known, legitimate way to get noticed by protocol teams and Web3 startups.', 'Junior/Solidity Developer, then Smart Contract Engineer, then Senior/Lead Protocol Engineer, then Core Contributor or CTO of a protocol/startup, paths are unusually fluid and often involve moving between protocols or launching your own, with community reputation mattering more than formal titles.', ARRAY['Solidity or the relevant chain''s smart contract language', 'Cryptography basics', 'General software engineering fundamentals', 'Security-mindedness (smart contract exploits are common and costly)', 'Shipping and open-sourcing real projects']::text[], 'People think it''s speculative and easy money; the technical bar for writing secure smart contracts is actually very high: a single bug can drain millions of dollars irreversibly, and the field''s hiring demand has also been notoriously volatile, tracking crypto market cycles closely.', 'Interviews test Solidity/smart contract security knowledge specifically (common exploits like reentrancy or integer overflow) alongside general coding ability, and often review your actual deployed contracts or open-source contributions as the primary portfolio evidence.'),
  ('Cybersecurity Analyst', 'Monitors and defends systems against threats, following incident-response protocol under time pressure.', 124910, 33, 'Bachelor''s degree', ARRAY['Threat analysis', 'Incident response protocol', 'Systems thinking', 'Rapid triage']::text[], '{"quadrant_a":0.88,"quadrant_b":0.5,"quadrant_c":0.15,"quadrant_d":0.25,"pace_preference":0.7,"risk_tolerance":0.3}'::jsonb, '2025-09-01'::date, '15-1212', 28.5, 124910, 16, 'exact', 'Direct match to BLS Information Security Analysts (15-1212).', 'Entry often comes via IT/helpdesk roles that transition into security, or directly through certifications (Security+, then more advanced ones like CySA+ or GSEC) that substitute for a 4-year degree in many hiring pipelines; Capture-the-Flag competitions and home-lab projects are a genuine, recruiter-recognized way to demonstrate skill without formal experience.', 'SOC Analyst (Tier 1), then Tier 2/3 Analyst or Incident Responder, then Security Engineer, then Security Architect or Manager, then CISO, many specialize into penetration testing, threat intelligence, or forensics rather than staying generalist.', ARRAY['Security fundamentals (Security+ certification)', 'Networking fundamentals: how systems actually communicate', 'Log analysis and SIEM tools', 'Home-lab/CTF practice', 'Scripting (Python/Bash) for automation']::text[], 'People picture dramatic hacker-movie scenarios; the daily reality at Tier 1 is mostly triaging alerts, many of them false positives, in a SOC, repetitive work before you advance to more investigative, high-judgment responsibilities.', 'Interviews test practical incident-response scenarios (here''s a suspicious log, what do you do) and foundational networking/security knowledge, plus increasingly hands-on technical assessments like CTF-style challenges rather than pure behavioral questions.'),
  ('Mobile App Developer', 'Builds native or cross-platform apps that millions of people might use directly on their phones.', 118000, 14, 'Bachelor''s degree', ARRAY['Mobile frameworks', 'UI implementation', 'Programming', 'Performance optimization']::text[], '{"quadrant_a":0.85,"quadrant_b":0.3,"quadrant_c":0.15,"quadrant_d":0.45,"pace_preference":0.5,"risk_tolerance":0.4}'::jsonb, '2025-09-01'::date, '15-1252', 15.8, 133080, 115.2, 'close', 'Mobile app development is folded into BLS''s broad Software Developers category (15-1252); no mobile-specific code exists.', 'A strong portfolio of shipped apps, even personal projects on the App Store or Play Store, is the single best credential, often outweighing formal degree background; bootcamps and self-teaching are common and accepted paths if the portfolio demonstrates real, working, shipped apps.', 'Junior Mobile Developer, then Mid-level, then Senior Mobile Developer, then Staff Engineer or Mobile Team Lead, then Principal Engineer or Head of Mobile, some specialize deeply in iOS or Android while others become cross-platform (React Native/Flutter) generalists.', ARRAY['A core mobile framework (Swift/iOS, Kotlin/Android, or React Native/Flutter)', 'UI implementation and platform design guidelines', 'API integration', 'Shipping at least one real app end-to-end', 'Performance/battery optimization basics']::text[], 'People think it''s a smaller, easier version of web development; mobile has its own hard constraints, such as app store review processes, offline handling, device fragmentation, and battery/performance limits, that make it a genuinely distinct discipline, not a lightweight one.', 'Interviews test platform-specific technical knowledge (memory management, lifecycle methods, UI framework specifics) plus general coding/algorithm rounds, and often ask you to walk through an app you''ve shipped end-to-end.'),
  ('IT / Technology Consultant', 'Advises companies on technology strategy and implementation, translating business needs into technical plans.', 100000, 11, 'Bachelor''s degree', ARRAY['Technical strategy', 'Client communication', 'Systems analysis', 'Project management']::text[], '{"quadrant_a":0.5,"quadrant_b":0.3,"quadrant_c":0.85,"quadrant_d":0.25,"pace_preference":0.6,"risk_tolerance":0.4}'::jsonb, '2025-09-01'::date, '15-1211', 8.7, 103790, 34.2, 'close', 'Matches BLS Computer Systems Analysts (15-1211), which covers advising organizations on technology strategy and systems implementation.', 'Common entry is through consulting firm campus recruiting (Big 4, Accenture, Deloitte) straight from undergrad, or transitioning from a corporate IT role with a few years of hands-on systems experience; client-facing communication ability is screened for as heavily as technical background.', 'Analyst/Associate Consultant, then Consultant, then Senior Consultant/Manager, then Senior Manager, then Principal/Partner, progression depends increasingly on business development, bringing in client work, rather than pure technical skill from Manager level up.', ARRAY['Broad technical literacy across systems rather than deep specialization', 'Client communication and presentation', 'Project management fundamentals', 'Business/process analysis', 'Adaptability across industries and tech stacks']::text[], 'People think it''s a technical implementation job; a huge amount of the real work is translation and stakeholder management: figuring out what a client actually needs, which they often can''t articulate clearly, rather than pure hands-on building.', 'Case interviews are common, testing structured problem-solving on ambiguous technology/business scenarios, alongside behavioral rounds assessing client-facing polish and comfort navigating organizational politics.'),
  ('Technical Program Manager', 'Coordinates complex, multi-team engineering efforts, keeping ambiguous technical projects on track.', 138000, 10, 'Bachelor''s degree', ARRAY['Cross-functional coordination', 'Technical fluency', 'Risk management', 'Prioritization']::text[], '{"quadrant_a":0.3,"quadrant_b":0.85,"quadrant_c":0.5,"quadrant_d":0.25,"pace_preference":0.6,"risk_tolerance":0.35}'::jsonb, '2025-09-01'::date, '11-3021', 15.2, 171200, 55.6, 'approximate', 'No dedicated TPM code; mapped to Computer and Information Systems Managers (11-3021) as the closest proxy, though TPMs coordinate projects rather than manage an IT function per se.', 'Almost always requires prior experience as a software engineer or engineering-adjacent project manager first: this is not typically an entry-level role; internal transfer from an engineering role at the same company is very common, since credibility with engineers depends on demonstrated technical fluency.', 'TPM, then Senior TPM, then Principal TPM or Group TPM managing a program area, then Director of Technical Programs, the ladder can also lead toward general engineering management or a Chief of Staff-style role at the VP/executive level.', ARRAY['Technical fluency: enough to read architecture docs and ask sharp questions', 'Cross-functional coordination', 'Risk identification and mitigation planning', 'Prioritization frameworks', 'Clear written and verbal status communication']::text[], 'People think it''s just scheduling meetings; the real value-add is spotting risks and dependencies across teams before they become fires, and doing enough technical due diligence to hold engineers accountable to realistic plans, not just tracking a Gantt chart.', 'Interviews test structured problem-solving on ambiguous multi-team scenarios (a project is behind schedule and two teams disagree on the cause: what do you do) plus enough technical questions to confirm you can follow real engineering conversations.'),
  ('Data Architect / DBA', 'Designs how an organization''s data is structured, stored, and secured at scale.', 133000, 9, 'Bachelor''s degree', ARRAY['Database design', 'Data modeling', 'Systems architecture', 'Security']::text[], '{"quadrant_a":0.88,"quadrant_b":0.5,"quadrant_c":0.1,"quadrant_d":0.25,"pace_preference":0.35,"risk_tolerance":0.2}'::jsonb, '2025-09-01'::date, '15-1243', 8.7, 135980, 4, 'close', 'Direct match to BLS Database Architects (15-1243).', 'Typically requires several years as a database administrator or data engineer first, building deep expertise in one or more database systems (SQL Server, Oracle, PostgreSQL) before moving into architecture; vendor certifications (Oracle DBA, Microsoft SQL Server) are genuinely valued credentials in this field.', 'Database Administrator, then Senior DBA, then Data Architect, then Principal/Enterprise Data Architect, then Head of Data Architecture or Chief Data Officer track, some specialize deeply in performance tuning while others move toward enterprise-wide data strategy.', ARRAY['Deep SQL and database internals knowledge', 'Data modeling (normalization, schema design)', 'Database platform certifications', 'Security and access-control fundamentals', 'Systems architecture principles']::text[], 'People think it''s a purely technical, back-office role; senior data architects spend significant time in governance conversations: deciding who can access what data and how it''s structured company-wide, which is as much organizational negotiation as technical design.', 'Interviews test deep database-specific technical knowledge (indexing strategy, query optimization, schema design tradeoffs) and system design for data at scale, with less emphasis on general coding than other engineering roles.'),
  ('Network Engineer', 'Designs and maintains the infrastructure that keeps an organization''s systems connected and online.', 95000, 6, 'Bachelor''s degree', ARRAY['Network architecture', 'Troubleshooting', 'Security protocols', 'Systems monitoring']::text[], '{"quadrant_a":0.5,"quadrant_b":0.88,"quadrant_c":0.15,"quadrant_d":0.15,"pace_preference":0.55,"risk_tolerance":0.2}'::jsonb, '2025-09-01'::date, '15-1241', 11.9, 130390, 11.2, 'close', 'Matches BLS Computer Network Architects (15-1241).', 'Common entry paths are IT helpdesk/support roles that build into networking, or direct entry via certifications (CompTIA Network+, then Cisco''s CCNA) that are genuinely load-bearing credentials in this field, more so than a 4-year degree for many employers. Home-lab practice, building and breaking your own network setups, is a recognized way to build real skill.', 'Network Technician/Junior Network Engineer, then Network Engineer, then Senior Network Engineer, then Network Architect, then Director of Network Infrastructure, the CCNP and CCIE certifications mark real seniority milestones along the way.', ARRAY['CCNA certification and core networking fundamentals', 'Troubleshooting methodology', 'Security protocols basics', 'Hands-on home-lab practice', 'Systems monitoring tools']::text[], 'People think networking is a legacy, fading field; in reality it remains foundational infrastructure work that cloud computing hasn''t eliminated, just relocated, and outages here have immediate, highly visible business impact, making it higher-stakes than its ''plumbing'' reputation suggests.', 'Interviews test hands-on troubleshooting (diagnose this described network issue) and protocol-level knowledge (explain how BGP or OSPF works), often via scenario-based questions rather than pure whiteboard coding.'),
  ('Data Scientist', 'Builds statistical models and machine learning systems to extract insight and drive product/business decisions.', 108020, 36, 'Bachelor''s/Master''s degree', ARRAY['Statistics', 'Python/R', 'Machine learning', 'Data visualization']::text[], '{"quadrant_a":0.9,"quadrant_b":0.3,"quadrant_c":0.2,"quadrant_d":0.5,"pace_preference":0.5,"risk_tolerance":0.4}'::jsonb, '2025-09-01'::date, '15-2051', 33.5, 112590, 23.4, 'exact', 'Direct match to BLS Data Scientists (15-2051).', 'Entry commonly requires a Bachelor''s/Master''s with strong statistics/programming coursework plus a portfolio of real analysis projects: Kaggle, personal projects using public datasets, or a research thesis; the field has grown more competitive and credentialed over recent years, with many practitioners now holding Master''s degrees even though it''s not strictly required.', 'Data Scientist, then Senior Data Scientist, then Staff Data Scientist or Data Science Lead, then Principal Data Scientist or Head of Data Science, the ladder forks between deep technical IC work and managing a data science team, and some pivot toward ML engineering or product management.', ARRAY['Statistics and probability fundamentals', 'Python/R for analysis', 'SQL', 'Machine learning basics', 'Communicating findings clearly to non-technical stakeholders']::text[], 'People imagine constant sophisticated modeling; the real job is dominated by data cleaning and wrangling, often 70-80% of time, and, crucially, communicating results in a way that actually changes a business decision: a brilliant model nobody acts on has zero impact.', 'Interviews mix statistics/ML theory questions, a SQL/coding round, and a case study (here''s a dataset or business question, walk through your analysis approach), increasingly firms also test whether you can explain findings convincingly to a non-technical stakeholder.'),
  ('Product Manager (Tech)', 'Defines product strategy and roadmap under ambiguity, synthesizing user, business, and technical constraints.', 133000, 10, 'Bachelor''s degree', ARRAY['Prioritization under ambiguity', 'Cross-functional communication', 'Strategic synthesis', 'User empathy']::text[], '{"quadrant_a":0.3,"quadrant_b":0.25,"quadrant_c":0.5,"quadrant_d":0.88,"pace_preference":0.6,"risk_tolerance":0.6}'::jsonb, '2025-09-01'::date, '11-3021', 15.2, 171200, 55.6, 'approximate', 'BLS has no dedicated product-manager occupation (a well-known gap); mapped to Computer and Information Systems Managers (11-3021) as the closest available proxy, though tech PMs typically don''t manage an IT department the way this code implies.', 'There''s no single standard pipeline: common routes are an MBA-to-PM track at a big tech company, an internal transition from engineering/design/consulting, or joining an early-stage startup where PM roles are less credentialed and more about proving impact directly. APM (Associate Product Manager) programs at large tech companies are a well-known structured entry point for new grads.', 'APM/PM, then Senior PM, then Group/Principal PM or Director of Product, then VP of Product, then CPO, progression depends heavily on demonstrated product impact, shipped features that moved real metrics, not tenure.', ARRAY['Prioritization frameworks under ambiguity', 'Cross-functional communication with eng, design, and sales', 'Basic data analysis/SQL', 'Writing clear product specs', 'User research fundamentals']::text[], 'People think PMs are the ''idea person'' who tells engineers what to build; the real job is mostly saying no to good ideas, resolving conflicting stakeholder priorities, and doing unglamorous prioritization work: PMs have influence, not authority, over most of the people whose work they depend on.', 'Interviews commonly include product-sense case questions (design a product for X, improve this existing product), analytical/metrics questions (how would you measure success), and behavioral rounds testing cross-functional conflict resolution.'),
  ('UX / Product Designer', 'Explores open-ended design problems to invent new interaction models and experiences for users.', 92150, 8, 'Bachelor''s degree', ARRAY['Creative ideation', 'User research', 'Prototyping', 'Visual design']::text[], '{"quadrant_a":0.2,"quadrant_b":0.2,"quadrant_c":0.5,"quadrant_d":0.9,"pace_preference":0.5,"risk_tolerance":0.55}'::jsonb, '2025-09-01'::date, '15-1255', 7, 98090, 9.1, 'close', 'Matches BLS Web and Digital Interface Designers (15-1255), which covers UX/UI and product design work.', 'A strong portfolio, case studies showing your process, not just final polished screens, is the dominant credential, far more than a design degree, though bootcamps (General Assembly-style) are a common structured entry point. Internships and contributing to real shipped products, even freelance or startup work, matter more than portfolio pieces that never shipped.', 'Junior/Associate Designer, then Product Designer, then Senior Designer, then Staff/Principal Designer or Design Lead, then Head of Design/VP Design, the ladder forks between deep IC craft work and managing a design team.', ARRAY['Portfolio-building with real case studies', 'Prototyping tools (Figma)', 'User research fundamentals', 'Visual design principles', 'Presenting and defending design decisions to stakeholders']::text[], 'People think it''s mostly making things look pretty; the real job is heavily about research, problem framing, and defending decisions with data and reasoning to skeptical engineers and PMs: visual polish is a small fraction of the actual skill being evaluated.', 'Interviews center on a portfolio walkthrough: explain your process and decisions, not just the output, plus a live design exercise or whiteboard challenge testing how you think through ambiguous problems under time pressure, not just final aesthetic quality.'),
  ('Game Designer', 'Invents rules, mechanics, and player experiences from scratch, iterating through open-ended prototyping.', 89410, 8, 'Bachelor''s degree', ARRAY['Systems design', 'Creative ideation', 'Prototyping', 'Playtesting iteration']::text[], '{"quadrant_a":0.45,"quadrant_b":0.25,"quadrant_c":0.25,"quadrant_d":0.92,"pace_preference":0.5,"risk_tolerance":0.55}'::jsonb, '2025-09-01'::date, '15-1255', 7, 98090, 9.1, 'close', 'O*NET nests Video Game Designers under BLS''s Web and Digital Interface Designers (15-1255); no standalone game-designer code exists.', 'A strong portfolio of playable prototypes, even small game jam projects, is the dominant credential; game jams (Ludum Dare, local jams) are a genuinely respected, low-barrier way to build a portfolio and network with the industry. QA tester roles at game studios are also a well-known, if unglamorous, foot-in-the-door path to a design role.', 'Associate/Junior Designer, then Game Designer, then Senior Designer, then Lead Designer or Creative Director, then Studio Director, the ladder often forks between systems design specialization and creative/narrative leadership.', ARRAY['Building playable prototypes, even in free tools like Unity/Godot', 'Systems design thinking', 'Playtesting and iteration discipline', 'Game jam participation for portfolio and network', 'Basic scripting']::text[], 'People think it''s about having cool ideas; the real job is mostly disciplined iteration: running playtests, watching people struggle with your design, reworking it repeatedly, and the games industry is also notorious for crunch (extended overtime before launch) and relatively modest pay versus general tech.', 'Interviews often include a design exercise (design a level or mechanic on the spot, critique an existing game) and a portfolio review focused on your design reasoning and iteration process, not just the final shipped product.'),
  ('Statistician', 'Designs studies and analyzes data to draw statistically valid conclusions across research or business contexts.', 104100, 33, 'Master''s degree', ARRAY['Statistical modeling', 'Study design', 'Programming (R/Python)', 'Data interpretation']::text[], '{"quadrant_a":0.96,"quadrant_b":0.5,"quadrant_c":0.15,"quadrant_d":0.25,"pace_preference":0.3,"risk_tolerance":0.2}'::jsonb, '2025-09-01'::date, '15-2041', 8.5, 103300, 2, 'exact', 'Direct match to BLS Statisticians (15-2041).', 'Typically requires a Master''s degree (PhD for research-heavy roles) in statistics or biostatistics; entry often comes via government agencies (Census Bureau, BLS), pharma/biotech biostatistics roles, or research institutions, with a thesis or research project serving as a portfolio credential.', 'Statistician/Associate, then Senior Statistician, then Principal Statistician or Statistical Lead, then Director of Biostatistics/Statistics, in pharma specifically, this can lead toward leading statistical strategy for entire drug development programs.', ARRAY['Statistical theory and study design', 'Programming (R/SAS/Python)', 'Experimental design principles', 'Data interpretation and reporting', 'Domain knowledge in a target industry (biostatistics, government, etc.)']::text[], 'People conflate this with data science; statisticians are typically more focused on rigorous study design and inference, proving something is true with appropriate uncertainty, than on prediction or building deployed models, and the bar for what counts as ''valid'' is much stricter.', 'Interviews test statistical theory deeply (explain this test''s assumptions, when would you use this method versus that one) and study design judgment, with SAS specifically still commonly tested in pharma/biostat-track interviews.'),
  ('Growth Product Manager', 'Runs open-ended experiments to find what actually moves a product''s growth, with no fixed playbook for what will work.', 140000, 11, 'Bachelor''s degree', ARRAY['Experimentation', 'Data-driven creativity', 'Prioritization under ambiguity', 'Cross-functional influence']::text[], '{"quadrant_a":0.5,"quadrant_b":0.2,"quadrant_c":0.3,"quadrant_d":0.9,"pace_preference":0.7,"risk_tolerance":0.65}'::jsonb, '2025-09-01'::date, '11-2021', 6.6, 161030, 34.3, 'approximate', 'No dedicated growth-PM code; mapped to Marketing Managers (11-2021) since the role''s core activity (data-driven growth experimentation) sits closer to marketing than to IT/product management, per founder-noted judgment call.', 'Usually requires prior general PM or marketing/analytics experience first: this is a specialized PM track, not typically a first job; demonstrated experimentation experience, having run and analyzed A/B tests even informally, is the strongest differentiator in interviews.', 'Growth PM, then Senior Growth PM, then Growth Lead/Director of Growth, then VP Growth or a CMO-adjacent executive role, many growth PMs eventually specialize deeply in a funnel stage (acquisition, activation, retention) or move into general product leadership.', ARRAY['A/B testing and experimentation design', 'SQL and analytics tooling', 'Funnel analysis', 'Basic statistics (statistical significance, sample size)', 'Fast, scrappy prioritization under ambiguity']::text[], 'People think growth is about marketing tricks or ''hacks''; the real discipline is rigorous, high-volume experimentation with statistical discipline: most tests fail to move the needle, and success comes from running many tests fast, not finding one clever trick.', 'Interviews test experimentation design (how would you test this hypothesis, what''s your sample size logic) and case questions on diagnosing a metric drop or designing a growth loop, with heavy emphasis on quantitative reasoning over general product sense.'),
  ('Startup CTO / Technical Co-Founder', 'Builds a company''s entire technical foundation from nothing, making irreversible architecture bets under real uncertainty.', 160000, 12, 'Bachelor''s degree (often + startup/eng experience)', ARRAY['Systems architecture', 'Technical leadership', 'Resourcefulness', 'Risk tolerance']::text[], '{"quadrant_a":0.5,"quadrant_b":0.15,"quadrant_c":0.3,"quadrant_d":0.92,"pace_preference":0.75,"risk_tolerance":0.9}'::jsonb, '2025-09-01'::date, '11-3021', 15.2, 171200, 55.6, 'approximate', 'No dedicated startup-CTO code; mapped to Computer and Information Systems Managers (11-3021) as the closest technical-leadership proxy.', 'This isn''t really a job you''re hired into from outside. It''s typically earned by being a strong senior engineer who either co-founds a company from scratch with a non-technical founder, or joins pre-seed/seed as the first serious technical hire and grows into the title. Prior startup experience, even as an early engineer rather than a founder, is the most common credential that gets someone considered for this role.', 'Senior/Staff Engineer, then early startup engineer or co-founder, then CTO of a growing company, the role itself evolves dramatically over 5-10 years from hands-on coding everything to hiring and leading an entire engineering org, a common failure point for technical founders who don''t grow into management.', ARRAY['Full-stack technical breadth: you''ll build everything early on', 'Systems architecture judgment for making irreversible early bets', 'Basic understanding of fundraising and business models', 'Hiring and early team-building', 'Resourcefulness and comfort operating with no playbook']::text[], 'People think it''s a purely technical leadership role; in practice the CTO of an early startup does sales engineering, customer support, infrastructure, hiring, and firefighting: technical depth matters less in year one than raw versatility and speed.', 'This role isn''t typically ''interviewed'' for in a standard sense: vetting happens through working together on a trial project, technical due diligence conversations with investors, and reference checks on how you handled ambiguity and pressure at previous startups.'),
  ('Emergency Medicine Physician', 'Diagnoses and treats acute illness and injury under time pressure in a hospital emergency department.', 310640, 4, 'M.D./D.O. + residency', ARRAY['Triage', 'Clinical protocol', 'Rapid decision-making', 'Procedural skill']::text[], '{"quadrant_a":0.5,"quadrant_b":0.95,"quadrant_c":0.25,"quadrant_d":0.15,"pace_preference":0.95,"risk_tolerance":0.4}'::jsonb, '2025-09-01'::date, '29-1214', 2.7, null, 1, 'exact', 'Direct match to BLS Emergency Medicine Physicians (29-1214).', 'Requires med school (M.D./D.O.) followed by a 3-4 year EM residency; the path effectively starts in college with a strong MCAT/GPA plus clinical volunteering, and EMT certification is a genuinely useful, common credential for pre-meds targeting EM specifically since it gives direct exposure to the specialty. EM residency match competitiveness has swung significantly in recent years, from very competitive to having unfilled spots, so checking current match data before committing matters.', 'Resident for 3-4 years, then attending EM physician, then optionally Medical Director of an ED or academic/administrative roles like EMS Medical Director or ED Chair, many physicians also pick up EMS medical direction, urgent care work, or travel/locum shifts for flexibility.', ARRAY['Strong MCAT score and pre-med GPA', 'Clinical volunteering/EMT certification for direct exposure', 'Shadowing an EM physician specifically', 'Composure and rapid decision-making practice', 'Research experience for residency applications']::text[], 'TV shows portray constant dramatic trauma; the actual daily mix is dominated by lower-acuity complaints, such as abdominal pain, minor injuries, and medication refills, with true life-threatening trauma a minority of shifts. Burnout and shift-work sleep disruption are also underestimated realities of the specialty.', 'Residency interviews assess composure under simulated pressure, teamwork in chaotic scenarios, and genuine commitment to the specialty''s demands like shift work and high patient volume. Multiple mini interview (MMI) formats with ethical scenarios are increasingly common.'),
  ('Surgeon', 'Performs operative procedures following strict clinical protocol, often under significant time pressure.', 297800, 4, 'M.D. + surgical residency', ARRAY['Procedural precision', 'Protocol adherence', 'Composure under pressure', 'Manual dexterity']::text[], '{"quadrant_a":0.5,"quadrant_b":0.95,"quadrant_c":0.2,"quadrant_d":0.1,"pace_preference":0.75,"risk_tolerance":0.3}'::jsonb, '2025-09-01'::date, '29-1249', 3.9, null, 0.6, 'close', 'Mapped to the aggregate Surgeons, All Other (29-1249) since BLS breaks out only Ophthalmologists, Orthopedic Surgeons, and Pediatric Surgeons individually; general surgeons fall in this catch-all.', 'Requires med school followed by a surgical residency (5+ years for general surgery, longer for subspecialties), among the most competitive and demanding matches in medicine; strong performance on surgery rotations and demonstrated manual dexterity/stamina during third-year clerkships heavily influence match success.', 'Resident for 5-7 years depending on subspecialty, then an optional fellowship (1-3 yrs) for subspecialization, then attending Surgeon, then potentially Chief of Surgery or department chair in academic settings, private practice surgeons instead build a referral base and can eventually own or partner in a surgical practice.', ARRAY['Strong pre-med academics and MCAT', 'Surgical rotation performance and letters of recommendation', 'Manual dexterity practice (suturing, knot-tying)', 'Physical stamina for long standing procedures', 'Research experience for competitive residency matches']::text[], 'People imagine dramatic, high-stakes decision-making constantly; a huge amount of surgical training is repetitive skill-building on routine cases before you''re trusted with complexity, and the residency lifestyle, where 80-hour weeks are the legal limit and often approached, is brutal in ways outsiders underestimate.', 'Residency interviews assess stamina signals, technical aptitude backed by rotation evaluations, and composure under the stress of long, high-stakes procedures. Programs also weight heavily how you handled a surgical complication or difficult attending during rotations.'),
  ('Cardiologist', 'Diagnoses and treats heart conditions, combining deep diagnostic reasoning with long-term patient relationships.', 353970, 4, 'M.D./D.O. + cardiology fellowship', ARRAY['Diagnostic reasoning', 'Clinical protocol', 'Patient communication', 'Procedural skill']::text[], '{"quadrant_a":0.85,"quadrant_b":0.3,"quadrant_c":0.5,"quadrant_d":0.15,"pace_preference":0.55,"risk_tolerance":0.25}'::jsonb, '2025-09-01'::date, '29-1212', 4.1, null, 0.6, 'exact', 'Direct match to BLS Cardiologists (29-1212).', 'Requires med school, an internal medicine residency (3 yrs), then a competitive cardiology fellowship (3 yrs, plus additional years for interventional/electrophysiology subspecialization); cardiology fellowship match is one of the more competitive IM subspecialty matches, so strong IM residency performance and research output matter significantly.', 'IM Resident, then Cardiology Fellow (general), then optional interventional/EP/heart failure sub-fellowship, then attending Cardiologist, then potentially Director of a cardiac program or academic division chief; many build a long-term outpatient practice managing chronic patients over decades.', ARRAY['Strong IM residency performance', 'Research publications in cardiology', 'Diagnostic reasoning practice', 'Procedural skill-building if targeting interventional cardiology', 'Long-term patient relationship skills']::text[], 'People picture constant emergency interventions; most cardiologists spend the majority of their time on outpatient chronic disease management, such as hypertension and heart failure follow-ups, rather than dramatic catheterization lab saves, which are a smaller, though real, part of the job.', 'Fellowship interviews assess IM foundational knowledge, research productivity, and genuine interest in the subspecialty''s demands; case-based discussion of diagnostic reasoning on cardiac presentations is common.'),
  ('Anesthesiologist', 'Manages patient sedation and vital functions during surgery, requiring constant vigilance and split-second judgment.', 331190, 3, 'M.D./D.O. + residency', ARRAY['Pharmacology', 'Real-time monitoring', 'Composure under pressure', 'Procedural precision']::text[], '{"quadrant_a":0.5,"quadrant_b":0.92,"quadrant_c":0.2,"quadrant_d":0.1,"pace_preference":0.8,"risk_tolerance":0.25}'::jsonb, '2025-09-01'::date, '29-1211', 3.2, null, 1.3, 'exact', 'Direct match to BLS Anesthesiologists (29-1211).', 'Requires med school followed by a 4-year anesthesiology residency including a preliminary/transitional intern year; this specialty has grown considerably more competitive in the match in recent years, so strong Step exam scores and away rotations at target programs matter.', 'Resident for 4 years, then an optional fellowship (pain management, cardiac, pediatric anesthesia, etc.), then attending Anesthesiologist, then potentially Chief of Anesthesiology or a pain-management practice, many also move into more autonomous outpatient surgical center settings later in their careers for better lifestyle.', ARRAY['Strong Step 1/2 exam scores', 'Pharmacology depth', 'Composure under high-stakes, time-pressured monitoring', 'Manual/procedural skill-building', 'Away rotations at target residency programs']::text[], 'People think it''s just ''putting people to sleep''; the real job is continuous, vigilant real-time physiological monitoring and rapid crisis response throughout a procedure: anesthesiologists manage life-critical functions the entire time, not administer a drug and step away.', 'Residency interviews assess composure under simulated crisis scenarios and pharmacology knowledge; programs specifically probe how candidates handle sustained vigilance and split-second decisions since a lapse in this specialty has immediate consequences.'),
  ('Radiologist', 'Interprets medical imaging to diagnose disease, working through large volumes of complex visual data.', 349000, 4, 'M.D./D.O. + residency', ARRAY['Image interpretation', 'Diagnostic reasoning', 'Attention to detail', 'Pattern recognition']::text[], '{"quadrant_a":0.9,"quadrant_b":0.5,"quadrant_c":0.1,"quadrant_d":0.15,"pace_preference":0.55,"risk_tolerance":0.2}'::jsonb, '2025-09-01'::date, '29-1224', 2.7, null, 0.8, 'exact', 'Direct match to BLS Radiologists (29-1224).', 'Requires med school followed by a 4-year diagnostic radiology residency, increasingly preceded by a preliminary intern year, and often a 1-year fellowship in a subspecialty (neuro, MSK, body imaging, interventional); radiology has become one of the most competitive specialties in the match in recent years, requiring strong Step scores and research.', 'Resident for 4 years plus fellowship (1-2 yrs), then attending Radiologist reading independently, then potentially Division Chief or Chair in academic settings, many also join or build large private practice groups reading for multiple hospital systems, including via teleradiology.', ARRAY['Strong Step 1/2 exam scores', 'Pattern recognition practice (image review)', 'Anatomy depth', 'Attention to detail under high case volume', 'Research experience for competitive matching']::text[], 'People imagine solitary, quiet work reading images all day with no patient contact, largely true for volume, but the job also requires constant real-time consultation with referring physicians and, increasingly, direct patient interaction for interventional procedures, making it less isolated than the stereotype suggests.', 'Residency interviews assess visual pattern recognition ability, sometimes tested directly, anatomy knowledge, and stamina for sustained, detail-heavy focus across large case volumes.'),
  ('Dermatologist', 'Diagnoses and treats skin conditions, blending clinical precision with a steady, appointment-driven pace.', 341000, 4, 'M.D./D.O. + residency', ARRAY['Diagnostic reasoning', 'Procedural skill', 'Patient communication', 'Attention to detail']::text[], '{"quadrant_a":0.3,"quadrant_b":0.85,"quadrant_c":0.5,"quadrant_d":0.15,"pace_preference":0.45,"risk_tolerance":0.2}'::jsonb, '2025-09-01'::date, '29-1213', 6.4, null, 0.4, 'exact', 'Direct match to BLS Dermatologists (29-1213).', 'Requires med school followed by dermatology residency (3 yrs after a preliminary intern year): consistently one of the most competitive residency matches in medicine, requiring near-top Step scores, research output, and often multiple away rotations at target programs to be competitive.', 'Resident for 3-4 years total, then attending Dermatologist, optionally a fellowship in Mohs surgery or dermatopathology, then building or joining a practice, some eventually open cosmetic-focused practices given strong demand for elective cosmetic procedures.', ARRAY['Very strong Step 1/2 exam scores: this specialty is unusually score-sensitive', 'Research publications, ideally in dermatology specifically', 'Pattern recognition for skin findings', 'Procedural skill-building (biopsies, excisions)', 'Away rotations at target programs']::text[], 'People assume it''s an ''easy'' or low-stakes specialty because it''s outpatient and rarely emergent; matching into it is actually among the hardest in all of medicine, and missing serious diagnoses like melanoma or systemic disease presenting on skin carries real stakes despite the calmer daily pace.', 'Residency interviews weight Step scores and research heavily as objective filters before interviews are even granted; interview-day conversations then assess genuine interest in the specialty and interpersonal fit given the field''s small, close-knit programs.'),
  ('Oncologist', 'Diagnoses and manages cancer treatment, combining rigorous protocol with deeply personal patient relationships.', 330000, 5, 'M.D./D.O. + oncology fellowship', ARRAY['Clinical protocol', 'Treatment planning', 'Patient communication', 'Emotional resilience']::text[], '{"quadrant_a":0.3,"quadrant_b":0.85,"quadrant_c":0.5,"quadrant_d":0.15,"pace_preference":0.5,"risk_tolerance":0.25}'::jsonb, '2025-09-01'::date, '29-1229', 2.5, null, 9.6, 'approximate', 'BLS does not break out oncology as its own code; mapped to the aggregate Physicians, All Other (29-1229).', 'Requires med school, an internal medicine residency (3 yrs), then a hematology/oncology fellowship (3 yrs); the fellowship match is competitive, and research productivity during IM residency significantly strengthens applications.', 'IM Resident, then Heme/Onc Fellow, then attending Oncologist, often subspecializing further by cancer type at academic centers, then potentially Director of an oncology program or clinical trials lead, many build long-term relationships with patients across years of treatment and survivorship.', ARRAY['Strong IM residency performance', 'Research experience in oncology (publications matter a lot here)', 'Emotional resilience training/exposure', 'Treatment protocol literacy', 'Communication skills for delivering difficult news']::text[], 'People assume it''s constantly devastating; while emotionally heavy, much of modern oncology also involves genuine long-term remission and survivorship care, and a lot of the job is protocol-driven treatment planning and clinical trial coordination rather than only end-of-life conversations.', 'Fellowship interviews assess research productivity, clinical reasoning on complex cases, and, increasingly emphasized, communication style and emotional resilience, often probed through scenario questions about delivering a difficult diagnosis.'),
  ('Pediatrician', 'Provides primary care for children, balancing clinical protocol with patient and family relationships.', 198420, 4, 'M.D./D.O. + residency', ARRAY['Clinical diagnosis', 'Patient/family communication', 'Protocol adherence', 'Patience']::text[], '{"quadrant_a":0.25,"quadrant_b":0.5,"quadrant_c":0.85,"quadrant_d":0.1,"pace_preference":0.5,"risk_tolerance":0.2}'::jsonb, '2025-09-01'::date, '29-1221', 0.8, 210130, 1.2, 'exact', 'Direct match to BLS Pediatricians, General (29-1221).', 'Requires med school followed by a 3-year pediatrics residency; pediatrics is one of the less competitive residency matches relative to specialties like dermatology or surgery, making it more accessible, though strong clinical rotation performance and genuine demonstrated interest in working with children (volunteering, shadowing) still matter.', 'Resident for 3 years, then attending Pediatrician in primary care, optionally a fellowship (2-3 yrs) for subspecialties like pediatric cardiology or neonatology, then potentially practice partner/owner or Medical Director of a pediatric practice.', ARRAY['Broad clinical knowledge across systems', 'Communication skills for both children and anxious parents', 'Patience and adaptability', 'Pre-med clinical experience with children specifically (camps, tutoring, volunteering)', 'Strong residency rotation performance']::text[], 'People think it''s just treating minor colds and giving vaccines; a large part of the real job is behavioral/developmental assessment and navigating difficult parent dynamics, such as vaccine hesitancy and custody disputes affecting care decisions, that require as much interpersonal skill as clinical knowledge.', 'Residency interviews assess genuine warmth and comfort with children plus family communication skills, often through scenario questions about handling a difficult parent conversation or child behavioral concern.'),
  ('Psychiatrist', 'Diagnoses and treats mental health conditions through a mix of clinical protocol, medication, and therapy.', 245000, 8, 'M.D./D.O. + psychiatry residency', ARRAY['Clinical assessment', 'Active listening', 'Treatment planning', 'Pharmacology']::text[], '{"quadrant_a":0.25,"quadrant_b":0.5,"quadrant_c":0.9,"quadrant_d":0.15,"pace_preference":0.35,"risk_tolerance":0.2}'::jsonb, '2025-09-01'::date, '29-1223', 6.1, null, 0.9, 'exact', 'Direct match to BLS Psychiatrists (29-1223).', 'Requires med school followed by a 4-year psychiatry residency; psychiatry has become notably more competitive in the match over the past decade as interest and demand have grown, though it remains less score-sensitive than specialties like dermatology or radiology.', 'Resident for 4 years, then attending Psychiatrist, optionally a fellowship (child/adolescent, forensic, addiction psychiatry), then private practice, academic, or hospital-employed roles, many build a long-term outpatient practice with significant autonomy and more flexible scheduling relative to other specialties.', ARRAY['Active listening and rapport-building', 'Psychopharmacology depth', 'Comfort with diagnostic ambiguity (psychiatric conditions are less clear-cut than lab-based diagnoses)', 'Boundary-setting and emotional resilience', 'Clinical rotation performance in psychiatry specifically']::text[], 'People assume it''s mostly talk therapy like a psychologist; modern psychiatry is heavily medication-management focused, with many psychiatrists doing 15-30 minute medication check visits rather than long therapy sessions, which surprises people expecting a Freudian-couch stereotype.', 'Residency interviews assess interpersonal warmth, self-awareness, and comfort discussing difficult topics like suicide risk and trauma calmly; programs also probe genuine motivation for the field given its emotional demands.'),
  ('Orthopedic Surgeon', 'Repairs bones, joints, and muscles through surgery, requiring precision under significant physical demand.', 375000, 4, 'M.D./D.O. + surgical residency', ARRAY['Surgical precision', 'Protocol adherence', 'Physical stamina', 'Diagnostic reasoning']::text[], '{"quadrant_a":0.5,"quadrant_b":0.92,"quadrant_c":0.25,"quadrant_d":0.1,"pace_preference":0.65,"risk_tolerance":0.3}'::jsonb, '2025-09-01'::date, '29-1242', 4.1, null, 0.4, 'exact', 'Direct match to BLS Orthopedic Surgeons, Except Pediatric (29-1242).', 'Requires med school followed by orthopedic surgery residency (5 yrs), one of the most competitive surgical matches in medicine; strong Step scores, research output, and demonstrated physical/manual aptitude heavily influence match success, and many applicants have athletic or hands-on backgrounds.', 'Resident for 5 years, then an optional fellowship (sports medicine, spine, joint replacement, etc., 1 yr), then attending Orthopedic Surgeon, often building a practice around a subspecialty and referral network, with some transitioning to team physician roles for sports organizations.', ARRAY['Very strong Step 1/2 exam scores', 'Research publications', 'Physical stamina and manual dexterity', 'Away rotations at target programs', 'Anatomy/biomechanics depth']::text[], 'People assume it''s purely physical/mechanical work; the specialty actually requires significant diagnostic reasoning to correctly identify the source of musculoskeletal pain, which is often not where it seems, and the surgeries themselves require far more finesse and judgment than ''fixing bones'' implies.', 'Residency interviews weight objective stats like Step scores and class rank heavily as a first filter; interview days then assess stamina signals, teamwork under the pressure of long operations, and genuine passion for the field''s physically demanding lifestyle.'),
  ('Neurologist', 'Diagnoses and treats disorders of the brain and nervous system through careful, methodical reasoning.', 280000, 5, 'M.D./D.O. + neurology residency', ARRAY['Diagnostic reasoning', 'Neuroanatomy', 'Patient communication', 'Pattern recognition']::text[], '{"quadrant_a":0.88,"quadrant_b":0.5,"quadrant_c":0.3,"quadrant_d":0.15,"pace_preference":0.4,"risk_tolerance":0.2}'::jsonb, '2025-09-01'::date, '29-1217', 5.4, null, 0.3, 'exact', 'Direct match to BLS Neurologists (29-1217).', 'Requires med school followed by a neurology residency (4 yrs including intern year); a moderately competitive match, with strong performance on neurology rotations and demonstrated comfort with complex, ambiguous diagnostic reasoning being key differentiators.', 'Resident for 4 years, then an optional fellowship (stroke, epilepsy, movement disorders, neuromuscular, etc., 1-2 yrs), then attending Neurologist, then potentially Director of a neurology program or stroke center, many build long-term relationships managing chronic conditions like epilepsy or Parkinson''s over years.', ARRAY['Neuroanatomy depth', 'Methodical diagnostic reasoning practice', 'Comfort with diagnostic uncertainty (neurology is famous for ambiguous presentations)', 'Patient communication for chronic, sometimes progressive conditions', 'Strong clinical rotation performance']::text[], 'People assume neurologists mostly treat headaches; the field spans a huge range from acute stroke care to chronic neurodegenerative disease management, and much of the specialty involves painstaking localization of a problem within the nervous system before treatment can even begin: diagnosis itself is often the hardest part.', 'Residency interviews assess methodical clinical reasoning through case discussions and comfort managing diagnostic uncertainty, since neurological presentations are often subtle and require systematic localization skills programs specifically probe for.'),
  ('Physician Assistant', 'Diagnoses and treats patients under physician supervision, often serving as a patient''s primary point of contact.', 130020, 27, 'Master''s degree (PA program)', ARRAY['Clinical assessment', 'Protocol adherence', 'Patient communication', 'Multitasking']::text[], '{"quadrant_a":0.3,"quadrant_b":0.85,"quadrant_c":0.5,"quadrant_d":0.1,"pace_preference":0.65,"risk_tolerance":0.25}'::jsonb, '2025-09-01'::date, '29-1071', 20.4, 133260, 12, 'exact', 'Direct match to BLS Physician Assistants (29-1071).', 'Requires a Bachelor''s degree plus prerequisite science courses and a meaningful amount of direct patient care experience, often 1000+ hours as an EMT, CNA, or medical scribe, before applying to a competitive PA program (2-3 yrs); PA programs weight hands-on clinical hours very heavily, more than many other health professional programs, making this experience genuinely load-bearing rather than a formality.', 'New graduate PA, often starting in a specific specialty or primary care, then experienced PA with growing autonomy, then Lead PA or PA supervising other PAs, then potentially a PA program faculty or clinical director role, PAs can also switch specialties more fluidly than physicians since training is generalist.', ARRAY['Direct patient care experience (CNA, EMT, scribe) before applying', 'Strong science GPA and GRE/PA-CAT prep', 'Clinical rotation performance across specialties', 'Communication skills for functioning as a patient''s primary contact', 'Comfort exercising independent judgment under physician supervision']::text[], 'People think PAs are ''junior doctors'' with less responsibility; in many settings PAs function with substantial day-to-day autonomy and full patient panels, and the appeal for many is the shorter training path, 2-3 years versus 7+, to a similar scope of clinical practice, not a lesser role.', 'PA program interviews, the real gatekeeper, assess genuine clinical exposure and motivation through detailed questions about your direct patient care experience, plus scenario-based ethical/clinical judgment questions similar to medical school MMIs.'),
  ('Nurse Practitioner', 'Provides advanced primary and specialty care, often with the autonomy to diagnose and prescribe independently.', 129480, 40, 'Master''s/Doctorate (DNP)', ARRAY['Clinical diagnosis', 'Patient communication', 'Protocol adherence', 'Independent judgment']::text[], '{"quadrant_a":0.3,"quadrant_b":0.85,"quadrant_c":0.5,"quadrant_d":0.15,"pace_preference":0.6,"risk_tolerance":0.25}'::jsonb, '2025-09-01'::date, '29-1171', 40.1, 129210, 29.5, 'exact', 'Direct match to BLS Nurse Practitioners (29-1171).', 'Requires becoming a Registered Nurse first, typically with 1-2+ years of bedside experience that most programs expect even if not formally required, then completing a Master''s or Doctorate (DNP) NP program; the RN experience beforehand is treated as essential real-world preparation by employers and often by admissions committees, not a bureaucratic formality.', 'RN, then NP student, then new graduate NP, often in the specialty matching your RN background, e.g. ICU nurses often go acute care NP, then experienced NP with a full independent panel, then potentially Lead NP or clinical director; scope of independent practice varies significantly by state.', ARRAY['RN bedside experience (genuinely valuable, not a checkbox)', 'Clinical diagnostic reasoning coursework', 'Pharmacology depth', 'Comfort with independent decision-making', 'Networking within your RN specialty toward your target NP specialty']::text[], 'People think it''s a shortcut to being ''like a doctor'' with less work; NP training is genuinely different in depth and approach from medical school, more nursing-model and less basic-science depth, and scope of practice varies dramatically by state: some grant full independence, others require physician oversight.', 'NP program admissions weight RN clinical experience heavily; job interviews for NP roles assess independent clinical judgment and comfort with autonomy, often through case-based scenario questions specific to the practice setting.'),
  ('Registered Nurse', 'Provides direct patient care, administers treatment, and coordinates with physicians under clinical protocol.', 86070, 6, 'Bachelor''s/Associate degree + license', ARRAY['Clinical care', 'Protocol adherence', 'Patient communication', 'Multitasking']::text[], '{"quadrant_a":0.2,"quadrant_b":0.5,"quadrant_c":0.85,"quadrant_d":0.1,"pace_preference":0.75,"risk_tolerance":0.2}'::jsonb, '2025-09-01'::date, '29-1141', 4.9, 93600, 189.1, 'exact', 'Direct match to BLS Registered Nurses (29-1141).', 'Requires an Associate''s (ADN) or Bachelor''s (BSN) nursing degree plus passing the NCLEX licensing exam; many hospitals now strongly prefer or require a BSN specifically, and clinical rotation performance plus demonstrated composure during nursing school clinicals matters for landing a first hospital job, especially in competitive units like the ICU or ER.', 'New graduate RN, often in a residency/transition program, then experienced staff RN, then Charge Nurse, then Nurse Manager or Clinical Educator, then Director of Nursing or Chief Nursing Officer, many RNs specialize by unit (ICU, ER, OR, oncology) and can move into travel nursing for flexibility and higher pay.', ARRAY['NCLEX exam preparation', 'Clinical rotation performance in nursing school', 'Time management/multitasking under real patient loads', 'Basic life support and specialty certifications (ACLS, PALS)', 'Composure and communication under pressure']::text[], 'People underestimate how physically and emotionally demanding bedside nursing is: 12-hour shifts on your feet, high patient-to-nurse ratios, being the frontline for both clinical crises and family emotional distress, and the role is far more autonomous and clinically complex than a purely ''assisting the doctor'' stereotype suggests.', 'New graduate interviews assess clinical judgment through scenario questions (a patient''s vitals are dropping, what do you do) and composure/teamwork under pressure, since units want confidence you can handle a real crisis with limited experience.'),
  ('Dentist', 'Diagnoses and treats oral health conditions in a structured, appointment-driven clinical practice.', 174420, 5, 'D.D.S./D.M.D.', ARRAY['Procedural precision', 'Diagnostic reasoning', 'Patient communication', 'Manual dexterity']::text[], '{"quadrant_a":0.3,"quadrant_b":0.88,"quadrant_c":0.5,"quadrant_d":0.1,"pace_preference":0.5,"risk_tolerance":0.2}'::jsonb, '2025-09-01'::date, '29-1021', 4.1, 172790, 3.9, 'exact', 'Direct match to BLS Dentists, General (29-1021).', 'Requires a Bachelor''s degree with strong science prerequisites and a competitive DAT (Dental Admission Test) score, then 4 years of dental school (D.D.S./D.M.D.); extensive shadowing of a practicing dentist and demonstrated manual dexterity strengthen applications, and some programs value hobbies like art or instruments as informal signals.', 'Dental school graduate, then associate dentist at an existing practice, a common first job for building speed and patient base, then practice owner/partner often within 5-10 years, many eventually own multiple practice locations or specialize further via residency (orthodontics, oral surgery, etc.).', ARRAY['Strong science GPA and DAT score', 'Manual dexterity practice', 'Shadowing experience with a practicing dentist', 'Business basics (most dentists eventually own a practice)', 'Patient communication for anxious patients']::text[], 'People think it''s a purely clinical role; the majority of dentists become small business owners within a decade, so practice management, staffing, and marketing skills end up mattering as much as clinical skill for long-term career satisfaction and income.', 'Dental school interviews, the real gatekeeper, assess manual dexterity claims, genuine motivation, and interpersonal comfort with patients, often through MMI-style scenario stations similar to medical school admissions.'),
  ('Orthodontist', 'Corrects teeth and jaw alignment through long-term, carefully sequenced treatment plans.', 251000, 5, 'D.D.S./D.M.D. + orthodontic residency', ARRAY['Treatment planning', 'Procedural precision', 'Patient communication', 'Long-term case management']::text[], '{"quadrant_a":0.3,"quadrant_b":0.9,"quadrant_c":0.45,"quadrant_d":0.1,"pace_preference":0.4,"risk_tolerance":0.15}'::jsonb, '2025-09-01'::date, '29-1023', 4.4, null, 0.2, 'exact', 'Direct match to BLS Orthodontists (29-1023).', 'Requires dental school (D.D.S./D.M.D.) followed by a highly competitive orthodontic residency (2-3 yrs), one of the most competitive dental specialties to match into, requiring a top dental school class rank and strong board scores.', 'Dental school graduate, then Orthodontic Resident, then associate orthodontist at an existing practice, then practice owner, the specialty has an unusually long total training runway, 4 years of dental school plus 2-3 years of residency, before independent practice, but strong earning potential once established.', ARRAY['Top dental school class rank/board scores', 'Manual dexterity and precision', 'Spatial/3D visualization skills', 'Long-term case-planning discipline', 'Business fundamentals for eventual practice ownership']::text[], 'People think it''s just ''putting on braces''; treatment planning actually requires sophisticated understanding of facial growth, bite mechanics, and multi-year case sequencing, and much of the skill is diagnosing and planning a case correctly upfront, not the mechanical adjustment visits themselves.', 'Orthodontic residency interviews weight dental school performance and board scores heavily as an initial filter, then assess spatial reasoning and case-planning thinking through practical exercises during interview days.'),
  ('Pharmacist', 'Dispenses medication, verifies dosage safety, and advises patients following strict regulatory protocol.', 136030, 3, 'Pharm.D. degree', ARRAY['Pharmacology', 'Protocol verification', 'Attention to detail', 'Patient counseling']::text[], '{"quadrant_a":0.45,"quadrant_b":0.92,"quadrant_c":0.3,"quadrant_d":0.05,"pace_preference":0.5,"risk_tolerance":0.1}'::jsonb, '2025-09-01'::date, '29-1051', 4.6, 137480, 14.2, 'exact', 'Direct match to BLS Pharmacists (29-1051).', 'Requires a Pharm.D. degree, typically 4 years after 2+ years of prerequisites, plus passing the NAPLEX licensing exam; retail/hospital internship hours during the program are standard and important for building the hands-on dispensing experience employers expect at graduation.', 'Staff Pharmacist (retail or hospital), then Pharmacist-in-Charge or clinical specialist pharmacist, then Pharmacy Manager, then Director of Pharmacy, hospital-track pharmacists can also pursue residencies (PGY1/PGY2) to specialize into clinical roles like oncology or critical care pharmacy.', ARRAY['Pharmacology depth', 'Attention to detail (dosage/interaction verification is high-stakes)', 'Patient counseling communication', 'Regulatory/protocol literacy', 'Internship hours during pharmacy school']::text[], 'People picture pharmacists mostly counting pills; the real daily work is dominated by verifying prescriptions for dangerous interactions and dosing errors, insurance/prior-authorization bureaucracy, and increasingly direct clinical consultation, and the retail pharmacist job market has tightened significantly in recent years, surprising people expecting guaranteed high demand.', 'Interviews test pharmacology knowledge and attention-to-detail scenarios (spot the error in this prescription) plus patient counseling role-play, since clear communication under time pressure is central to the retail/hospital job.'),
  ('Physical Therapist', 'Designs and delivers rehabilitation plans following clinical protocol, adjusting to each patient''s progress.', 99710, 14, 'Doctorate (DPT)', ARRAY['Clinical assessment', 'Treatment planning', 'Patient communication', 'Anatomy knowledge']::text[], '{"quadrant_a":0.25,"quadrant_b":0.5,"quadrant_c":0.85,"quadrant_d":0.15,"pace_preference":0.45,"risk_tolerance":0.2}'::jsonb, '2025-09-01'::date, '29-1123', 10.9, 101020, 13.2, 'exact', 'Direct match to BLS Physical Therapists (29-1123).', 'Requires a Doctorate of Physical Therapy (DPT, typically 3 years post-Bachelor''s) plus passing the NPTE licensing exam; observation hours with a practicing PT, often 50-100+ hours, are a hard requirement for most DPT program applications, making shadowing genuinely load-bearing rather than optional.', 'New graduate PT, often in an outpatient clinic or hospital setting, then experienced PT building a specialty (sports, orthopedic, neuro, pediatric), then Lead PT or Clinic Director, then Practice Owner or Regional Director, board certification in a specialty (OCS, SCS) marks real expertise milestones.', ARRAY['Observation/shadowing hours with a practicing PT', 'Anatomy and kinesiology depth', 'Strong science GPA for DPT admission', 'Patient motivation/communication skills', 'Manual assessment technique practice']::text[], 'People think it''s mostly showing patients exercises; a large part of the real skill is diagnostic assessment: figuring out the actual biomechanical cause of pain, which is often not where it hurts, and behavioral coaching to keep patients doing home exercises they don''t want to do.', 'DPT program interviews assess genuine clinical exposure through your shadowing experience and communication style; job interviews for PT roles focus on caseload management and patient motivation skills given productivity-based expectations at many clinics.'),
  ('Occupational Therapist', 'Helps patients regain daily living skills through individualized, protocol-guided therapeutic plans.', 96370, 11, 'Master''s/Doctorate degree', ARRAY['Patient assessment', 'Treatment planning', 'Empathy', 'Adaptive problem-solving']::text[], '{"quadrant_a":0.2,"quadrant_b":0.5,"quadrant_c":0.85,"quadrant_d":0.15,"pace_preference":0.4,"risk_tolerance":0.15}'::jsonb, '2025-09-01'::date, '29-1122', 13.8, 98340, 10.2, 'exact', 'Direct match to BLS Occupational Therapists (29-1122).', 'Requires a Master''s or Doctorate in Occupational Therapy plus passing the NBCOT certification exam; observation hours across varied settings, such as pediatric, hand therapy, mental health, and geriatric, during program applications help clarify which specialty you''re suited for, since OT spans an unusually wide range of practice areas.', 'New graduate OT, often rotating through settings before specializing, then experienced OT with a chosen specialty, then Lead OT or Clinical Supervisor, then Director of Rehabilitation Services, many also move into home health or private practice for more autonomy.', ARRAY['Observation hours across multiple OT settings', 'Anatomy and activity-analysis coursework', 'Empathy and adaptive problem-solving', 'Patient/family communication', 'Creativity in adapting tasks to individual patient needs']::text[], 'People often confuse OT with PT or think it''s just ''helping people do crafts''; OT is actually about restoring functional independence in daily life activities: dressing, cooking, working, and spans a surprisingly wide range of settings from NICU to mental health to hand surgery rehab.', 'OT program admissions assess breadth of shadowing experience and genuine understanding of what the field covers, since many applicants apply with a narrow or inaccurate picture of the profession; job interviews focus on adaptability across the specific patient population served.'),
  ('Genetic Counselor', 'Interprets genetic testing and helps patients understand hereditary health risks and options.', 95000, 16, 'Master''s degree', ARRAY['Genetics knowledge', 'Patient counseling', 'Risk communication', 'Empathy']::text[], '{"quadrant_a":0.45,"quadrant_b":0.3,"quadrant_c":0.85,"quadrant_d":0.15,"pace_preference":0.35,"risk_tolerance":0.15}'::jsonb, '2025-09-01'::date, '29-9092', 9.3, 98910, 0.3, 'exact', 'Direct match to BLS Genetic Counselors (29-9092).', 'Requires a Master''s degree in genetic counseling from an accredited program, competitive admission requiring genetics/biology coursework and often direct exposure via shadowing a genetic counselor or working as a genetics research assistant; this is a small field with limited program seats, making early exposure and strong letters genuinely important for admission.', 'New graduate Genetic Counselor, often in prenatal, cancer, or pediatric genetics, then experienced counselor building a specialty caseload, then Lead/Senior Genetic Counselor, then Program Director, some move into industry roles at genetic testing companies or biotech as clinical liaisons.', ARRAY['Genetics/biology coursework depth', 'Shadowing a practicing genetic counselor', 'Risk communication skills', 'Empathy and comfort delivering difficult news', 'Research or lab experience relevant to program applications']::text[], 'People assume it''s a lab-based science job; it''s actually a heavily interpersonal counseling role: the science of interpreting genetic risk is almost the easy part compared to communicating complex probabilistic risk to frightened patients and helping them make deeply personal decisions.', 'Program admissions interviews assess emotional intelligence and communication skills as much as science background, often through role-play scenarios delivering difficult genetic risk information, since this predicts success in the actual job.'),
  ('Epidemiologist / Public Health Analyst', 'Studies disease patterns and public health data to inform policy and prevention strategy.', 82000, 27, 'Master''s degree (MPH)', ARRAY['Statistical analysis', 'Study design', 'Public health policy', 'Data interpretation']::text[], '{"quadrant_a":0.9,"quadrant_b":0.5,"quadrant_c":0.15,"quadrant_d":0.3,"pace_preference":0.35,"risk_tolerance":0.25}'::jsonb, '2025-09-01'::date, '19-1041', 16.2, 83980, 0.8, 'close', 'Matches BLS Epidemiologists (19-1041); the "public health analyst" half of the title is broader but the core disease-pattern/data work aligns well.', 'Requires a Master''s in Public Health (MPH) at minimum, often with a concentration in epidemiology or biostatistics; internships with health departments or the CDC, including the competitive Epidemic Intelligence Service for PhD/MD-level candidates, are a well-known pipeline, and government/public health work often has more accessible, application-based hiring than private-sector research roles.', 'Epidemiologist I/Research Analyst, then Senior Epidemiologist, then Epidemiology Program Manager, then Director of Epidemiology or State Epidemiologist, a PhD opens doors to more senior research-leadership and academic-adjacent roles, while an MPH alone can still lead to solid program management careers.', ARRAY['Statistical analysis and study design', 'Programming (R, SAS, Python)', 'Public health policy literacy', 'Scientific/technical writing', 'Internship experience with a health department or public health organization']::text[], 'People picture dramatic outbreak investigation, contact tracing in hazmat suits; most epidemiologists spend their time on unglamorous data analysis of chronic disease patterns, and government public health salaries are notably lower than private-sector data roles requiring similar statistical skill.', 'Interviews test statistical/study design reasoning (how would you investigate this disease cluster) and public health policy knowledge, with government roles often using structured, criteria-based interview formats rather than open-ended conversations.'),
  ('Healthcare Consultant', 'Advises hospitals and health systems on strategy, operations, and efficiency improvements.', 108000, 10, 'Bachelor''s/MBA', ARRAY['Healthcare operations', 'Strategic analysis', 'Client communication', 'Data-driven problem-solving']::text[], '{"quadrant_a":0.3,"quadrant_b":0.2,"quadrant_c":0.5,"quadrant_d":0.85,"pace_preference":0.6,"risk_tolerance":0.4}'::jsonb, '2025-09-01'::date, '13-1111', 8.8, 101190, 98.1, 'approximate', 'No healthcare-specific consultant code; mapped to the general Management Analysts category (13-1111).', 'Common entry paths are consulting firm campus recruiting (specialized healthcare practices at McKinsey, Deloitte, or boutique healthcare-only firms) straight from undergrad/MBA, or transitioning from a clinical or hospital operations background with an MBA; case interview preparation is essential regardless of background.', 'Analyst/Associate Consultant, then Consultant, then Engagement Manager/Senior Consultant, then Principal, then Partner, progression depends increasingly on business development and client relationships from Manager level up, same as general management consulting.', ARRAY['Case interview preparation and structured problem-solving', 'Healthcare industry/operations literacy', 'Data analysis (Excel, sometimes SQL)', 'Client communication and presentation', 'PowerPoint/deck-building']::text[], 'People think clinical background is required; many successful healthcare consultants come from generalist consulting or finance backgrounds and learn the healthcare specifics on the job: business and analytical skill matters more than prior clinical experience for most roles.', 'Case interviews are the central gate, testing structured problem-solving on healthcare-specific business scenarios (a hospital''s margins are declining, why, and what would you do), alongside standard consulting fit interviews assessing communication and composure.'),
  ('Hospital Administrator', 'Manages the operations, budget, and staff of a hospital or healthcare system.', 118000, 28, 'Master''s degree (MHA/MBA)', ARRAY['Operations management', 'Budgeting', 'Team leadership', 'Regulatory knowledge']::text[], '{"quadrant_a":0.3,"quadrant_b":0.85,"quadrant_c":0.5,"quadrant_d":0.2,"pace_preference":0.55,"risk_tolerance":0.3}'::jsonb, '2025-09-01'::date, '11-9111', 23.2, 117960, 62.1, 'close', 'Matches BLS Medical and Health Services Managers (11-9111).', 'Requires a Master''s in Health Administration (MHA) or MBA with a healthcare focus, typically paired with a required administrative residency/fellowship, a structured, competitive placement similar to a medical residency for admin-track graduates, at a hospital system during or after the program.', 'Administrative Fellow/Resident, then Department/Unit Manager, then Assistant/Associate Administrator, then Vice President of Operations, then Hospital CEO/President, progression typically involves rotating through different operational areas (finance, clinical operations, quality) to build breadth.', ARRAY['MHA/MBA coursework in healthcare finance and operations', 'Administrative fellowship/internship experience', 'Budgeting and operations management', 'Regulatory knowledge (CMS, Joint Commission)', 'Team leadership across clinical and non-clinical staff']::text[], 'People think it''s a desk job disconnected from patient care; hospital administrators make decisions with direct clinical consequences, such as staffing ratios, service line investments, and resource allocation during crises, and increasingly need genuine clinical operations fluency, not just generic business management skill.', 'Interviews for fellowship/residency programs, the key entry gate, assess leadership potential through behavioral questions and case scenarios about resource allocation tradeoffs, testing judgment on genuinely difficult operational decisions with competing stakeholder interests.'),
  ('Concierge Medicine Physician', 'Provides highly personalized, relationship-first primary care to a small panel of patients who pay directly for access.', 260000, 8, 'M.D./D.O. + residency', ARRAY['Patient relationship-building', 'Clinical judgment', 'Communication', 'Personalized care planning']::text[], '{"quadrant_a":0.45,"quadrant_b":0.3,"quadrant_c":0.92,"quadrant_d":0.15,"pace_preference":0.35,"risk_tolerance":0.3}'::jsonb, '2025-09-01'::date, '29-1215', 2.7, 238380, 3.3, 'approximate', 'No dedicated concierge-medicine code; mapped to Family Medicine Physicians (29-1215) since it''s fundamentally a primary-care specialty delivered under a different business model.', 'Requires full physician training (M.D./D.O. plus residency, typically in primary care/internal medicine or family medicine) followed by several years of traditional practice to build clinical reputation and a referral network before transitioning to or founding a concierge practice; this is a practice model, not a specialty, so the real credential is an established, trusted local reputation and often business/marketing savvy to build a paying patient panel.', 'Primary care residency, then traditional practice physician for 5-10 years building reputation and patient relationships, then transition to concierge model: joining an existing concierge practice or converting/launching your own panel, with growth measured by retained membership patients rather than traditional patient volume.', ARRAY['Primary care clinical training (IM or FM residency)', 'Relationship-building and long-term trust with patients', 'Business/practice management basics', 'Personalized care planning', 'Communication and availability (concierge patients expect direct access)']::text[], 'People think it''s just ''medicine for rich people with less work''; the real appeal for physicians is smaller patient panels enabling genuinely thorough care, but building the initial paying membership base is a real business risk and requires marketing/networking skills medical training doesn''t teach.', 'This is less a traditional interview process and more a practice-transition/business decision; when concierge groups do hire physicians, they assess bedside manner, communication style, and whether a physician can build genuine rapport quickly, since retention depends entirely on patient relationship quality.'),
  ('Major Gifts / Philanthropy Officer', 'Builds relationships with high-net-worth donors to fund a university, hospital, or nonprofit''s biggest initiatives.', 105000, 9, 'Bachelor''s degree', ARRAY['Relationship building', 'Persuasive storytelling', 'Networking', 'Long-term trust-building']::text[], '{"quadrant_a":0.15,"quadrant_b":0.25,"quadrant_c":0.92,"quadrant_d":0.45,"pace_preference":0.4,"risk_tolerance":0.4}'::jsonb, '2025-09-01'::date, '13-1131', 4.3, 66490, 10.2, 'close', 'Matches BLS Fundraisers (13-1131), which covers donor solicitation and relationship-based fundraising.', 'Entry is often through smaller development/annual-fund roles at a nonprofit, university, or hospital foundation, building up to major gifts work after demonstrating relationship-building results; a sales or client-facing background even outside nonprofits transfers surprisingly well, and warm personal networks in a wealthy community genuinely help.', 'Development Associate/Annual Fund Officer, then Major Gifts Officer managing a portfolio of donors, then Senior/Principal Gifts Officer handling the largest relationships, then Director of Development or Chief Development Officer, success is measured by dollars raised and donor retention, similar to a sales quota.', ARRAY['Relationship-building and active listening', 'Persuasive storytelling about mission/impact', 'Networking within a target donor community', 'Long-term trust-building (major gifts cycles can take years)', 'Basic understanding of estate/planned giving']::text[], 'People think it''s just asking rich people for money; the actual skill is patient, multi-year relationship cultivation: understanding a donor''s values and finding genuine alignment with the mission, and asking for the gift is often the final, smallest step after years of relationship work.', 'Interviews assess relationship-building track record (walk me through how you cultivated and closed a major gift or comparable sales relationship) and comfort with rejection/persistence, since the job involves many more no''s than yeses.'),
  ('Client Success Director (SaaS/Tech)', 'Owns the relationship with a tech company''s biggest customers, making sure they get value and stay.', 135000, 12, 'Bachelor''s degree', ARRAY['Relationship management', 'Problem-solving', 'Cross-functional advocacy', 'Communication']::text[], '{"quadrant_a":0.45,"quadrant_b":0.3,"quadrant_c":0.88,"quadrant_d":0.2,"pace_preference":0.55,"risk_tolerance":0.35}'::jsonb, '2025-09-01'::date, '11-2022', 4.7, 138060, 49, 'approximate', 'No dedicated customer/client-success code (a relatively new job family); mapped to Sales Managers (11-2022) as the closest revenue-function proxy.', 'Common entry paths are starting in a Customer Success Manager or Account Manager role at a SaaS company, often hired from sales, support, or consulting backgrounds, and being promoted up as your book of managed accounts grows in size and strategic importance; a technical/product background helps but relationship management skill is the primary hiring filter.', 'Customer Success Manager, then Senior CSM handling larger accounts, then Client Success Director/Manager leading a team of CSMs, then VP of Customer Success, progression ties to demonstrated impact on retention/expansion revenue more than tenure.', ARRAY['Relationship management and account planning', 'Problem-solving/troubleshooting product issues', 'Cross-functional advocacy (translating client needs to product/eng teams)', 'Data-driven account health tracking', 'Negotiation for renewals and upsells']::text[], 'People think it''s just being ''nice to customers''; the real job increasingly resembles a quota-carrying sales role tied to renewal and expansion revenue, and a big part of the work is internal: advocating for client needs against competing product priorities inside your own company.', 'Interviews test how you''ve handled a churning or at-risk account in the past (walk through a save) and cross-functional influence scenarios, since the role requires getting engineering/product teams to prioritize a client''s needs without formal authority over them.'),
  ('Behavioral / Clinical Psychologist', 'Assesses and treats mental health conditions through structured therapeutic frameworks and deep interpersonal work.', 92740, 7, 'Doctorate (Ph.D./Psy.D.)', ARRAY['Clinical assessment', 'Active listening', 'Treatment planning', 'Empathy']::text[], '{"quadrant_a":0.25,"quadrant_b":0.5,"quadrant_c":0.92,"quadrant_d":0.15,"pace_preference":0.3,"risk_tolerance":0.15}'::jsonb, '2025-09-01'::date, '19-3033', 11.2, 95830, 4.8, 'exact', 'Direct match to BLS Clinical and Counseling Psychologists (19-3033).', 'Requires a doctorate (Ph.D. or Psy.D.) in clinical or counseling psychology, including a year-long predoctoral internship, APA-accredited internships are competitive and essential for licensure, plus post-doctoral supervised hours before full licensure; Ph.D. programs are research-heavy and highly competitive, while Psy.D. programs are more clinically focused and sometimes less research-intensive to enter.', 'Doctoral student, then predoctoral intern, then postdoctoral fellow accumulating licensure hours, then licensed Psychologist, then Senior/Supervising Psychologist or private practice owner, many eventually build a private practice for greater autonomy and often higher income than institutional employment.', ARRAY['Research experience during undergrad (for Ph.D. program competitiveness)', 'Clinical volunteer/shadowing experience', 'Active listening and rapport-building', 'Coursework in assessment and treatment modalities', 'Emotional resilience and self-care practices']::text[], 'People think it''s mostly listening and nodding; the field requires rigorous training in specific evidence-based treatment protocols and diagnostic assessment, and the total training timeline, 4-7 year doctorate plus supervised hours, is much longer than people expect before you can practice independently.', 'Doctoral program admissions and internship interviews assess clinical judgment through case discussions and self-awareness/reflective capacity: can you discuss your own biases and limitations, since this predicts effectiveness and ethical practice as a therapist.'),
  ('Family Medicine Physician', 'Provides ongoing primary care across a patient''s life, building long-term relationships more than any single specialty.', 245000, 4, 'M.D./D.O. + residency', ARRAY['Patient relationship-building', 'Broad clinical knowledge', 'Communication', 'Continuity of care']::text[], '{"quadrant_a":0.25,"quadrant_b":0.5,"quadrant_c":0.88,"quadrant_d":0.15,"pace_preference":0.45,"risk_tolerance":0.2}'::jsonb, '2025-09-01'::date, '29-1215', 2.7, 238380, 3.3, 'exact', 'Direct match to BLS Family Medicine Physicians (29-1215).', 'Requires med school followed by a 3-year family medicine residency; this is one of the less competitive residency matches and has been actively recruiting more students in recent years given primary care shortages, making it comparatively more accessible while still requiring the full MD/DO pathway.', 'Resident for 3 years, then attending Family Medicine physician in a clinic or hospital-affiliated practice, then potentially practice partner/owner, Medical Director of a clinic, or academic/residency faculty role, many build decades-long relationships with patients and multiple generations of the same family.', ARRAY['Broad clinical knowledge across all ages and systems', 'Long-term relationship-building', 'Continuity-of-care mindset (following a patient over years)', 'Efficient time management for high patient volume', 'Comfort managing a wide range of conditions without subspecialist backup']::text[], 'People think family medicine is ''less rigorous'' than specialties; it actually requires the broadest clinical knowledge base of any specialty since you''re the first line for every age group and organ system, and knowing when to refer out is itself a sophisticated skill many people underestimate.', 'Residency interviews assess breadth of clinical interest and genuine commitment to long-term, continuity-based primary care rather than using FM as a fallback, often probed through questions about why you didn''t choose a narrower specialty.'),
  ('Litigation Attorney', 'Builds and argues legal cases, combining rigorous procedural preparation with adversarial persuasion.', 145760, 5, 'J.D. + bar admission', ARRAY['Legal research', 'Argumentation', 'Procedural discipline', 'Persuasive writing']::text[], '{"quadrant_a":0.3,"quadrant_b":0.85,"quadrant_c":0.5,"quadrant_d":0.15,"pace_preference":0.6,"risk_tolerance":0.4}'::jsonb, '2025-09-01'::date, '23-1011', 4.1, 151160, 31.5, 'close', 'Matches BLS Lawyers (23-1011); BLS does not split litigation vs. transactional practice.', 'Requires a J.D. (top grades and law review matter significantly for prestigious litigation firms) and passing the bar; the standard path is a summer associate internship after 2L year converting to a full-time offer, with judicial clerkships, especially federal, being a genuinely prestige-boosting credential many top litigators complete before joining a firm.', 'Summer Associate, then Associate for 6-8 years (often with a clerkship first), then Senior Associate/Counsel, then Partner around year 8-10, many litigators also move in-house or to government (US Attorney''s office, DOJ) at various career stages for different practice experience.', ARRAY['Legal research and writing (moot court/law review experience)', 'Persuasive oral advocacy (mock trial)', 'Case law analysis', 'Procedural rules mastery', 'Stamina for long hours during active litigation/trial prep']::text[], 'People imagine dramatic courtroom trials constantly; the vast majority of cases settle before trial, and most litigator time is spent on discovery (document review), motion drafting, and depositions rather than dramatic cross-examinations.', 'Law firm interviews (on-campus interviewing, callbacks) weight grades/class rank heavily as a first filter, then assess fit and communication polish; case competitions and mock trial experience signal genuine advocacy skill for litigation-specific roles.'),
  ('Corporate Lawyer (Transactional)', 'Structures deals and contracts, balancing precise procedural drafting with client relationship management.', 145760, 5, 'J.D. + bar admission', ARRAY['Contract drafting', 'Negotiation', 'Regulatory knowledge', 'Client management']::text[], '{"quadrant_a":0.3,"quadrant_b":0.88,"quadrant_c":0.5,"quadrant_d":0.1,"pace_preference":0.45,"risk_tolerance":0.25}'::jsonb, '2025-09-01'::date, '23-1011', 4.1, 151160, 31.5, 'close', 'Matches BLS Lawyers (23-1011); BLS does not split practice areas.', 'Requires a J.D. from a well-ranked school (grades matter for firm prestige) and bar passage, with the standard path being a 2L summer associate position converting to a full-time offer; unlike litigation, clerkships are less commonly pursued since transactional practice rewards deal experience more directly.', 'Summer Associate, then Associate for 6-8 years, then Senior Associate/Counsel, then Partner around year 8-10, many transactional lawyers eventually move in-house to a company''s legal department for better work-life balance after making partner-track progress at a firm.', ARRAY['Contract drafting and review', 'Corporate law fundamentals (M&A, securities basics)', 'Negotiation', 'Attention to detail under deal deadlines', 'Client relationship management']::text[], 'People think it''s less demanding than litigation since there''s no courtroom drama; deal closings involve their own version of extreme, unpredictable hours (all-nighters before signing), and the work is detail-obsessive in a way that surprises people expecting big-picture strategy conversations.', 'Firm interviews weight law school grades/prestige heavily as an initial filter, then assess communication and composure; transactional practice groups specifically probe for genuine interest in business/deal work versus courtroom advocacy.'),
  ('Intellectual Property / Patent Attorney', 'Protects inventions and creative work through patent filings and IP litigation, often requiring a technical background.', 165000, 6, 'J.D. + technical Bachelor''s degree', ARRAY['Patent law', 'Technical analysis', 'Legal writing', 'Attention to detail']::text[], '{"quadrant_a":0.85,"quadrant_b":0.5,"quadrant_c":0.25,"quadrant_d":0.2,"pace_preference":0.45,"risk_tolerance":0.25}'::jsonb, '2025-09-01'::date, '23-1011', 4.1, 151160, 31.5, 'close', 'Matches BLS Lawyers (23-1011); no IP/patent-specific legal code exists.', 'Requires a technical Bachelor''s degree (engineering, CS, biology, chemistry) as a prerequisite to sit for the patent bar, plus a J.D.; this technical-degree requirement makes the field unusually accessible to STEM majors who might not have considered law, and many enter via a patent agent role, requiring only the technical degree and patent bar, not a J.D., before or during law school.', 'Patent Agent or Associate, then Senior Associate, then Counsel/Partner at an IP firm, or in-house Patent Counsel, many specialize by technical field (biotech, software, semiconductor patents) based on their underlying technical background.', ARRAY['A strong technical Bachelor''s degree (the real prerequisite)', 'Patent bar exam preparation', 'Technical writing and analysis', 'Legal writing fundamentals', 'Attention to detail in patent claim language']::text[], 'People think you need to already be a lawyer to work in patents; the technical degree is actually the harder-to-get prerequisite, and many technical professionals are surprised to learn patent law is a viable, well-paying path that leverages their STEM background directly.', 'Firm interviews assess your specific technical background depth: do you understand the technology deeply enough to draft and defend patents in that field, alongside standard law firm grade/writing sample review; technical credibility matters as much as legal writing polish here.'),
  ('Tax Attorney', 'Advises individuals and companies on complex tax law and represents them in disputes with tax authorities.', 155000, 5, 'J.D. + often LL.M. in Taxation', ARRAY['Tax law', 'Legal research', 'Analytical reasoning', 'Client advising']::text[], '{"quadrant_a":0.88,"quadrant_b":0.5,"quadrant_c":0.25,"quadrant_d":0.1,"pace_preference":0.4,"risk_tolerance":0.15}'::jsonb, '2025-09-01'::date, '23-1011', 4.1, 151160, 31.5, 'close', 'Matches BLS Lawyers (23-1011); no tax-specific legal code exists.', 'Requires a J.D. and often an LL.M. in Taxation, a widely valued additional credential in this specific niche unlike most other legal specialties; entry is via law firm tax practice groups, Big 4 accounting firm legal/tax departments, or government (IRS, Treasury) roles, with strong grades in tax coursework mattering more than typical law school prestige signals.', 'Associate in a firm''s tax group, then Senior Associate, then Counsel/Partner, or a parallel track at a Big 4 firm moving toward Tax Director/Principal, some transition between private practice and government roles (IRS, Treasury) throughout a career for varied experience.', ARRAY['Tax law coursework depth (consider an LL.M. in Taxation)', 'Legal research on complex, technical statutes', 'Analytical/quantitative reasoning', 'Client advising on ambiguous, high-stakes situations', 'Attention to detail in regulatory interpretation']::text[], 'People think tax law is dry paperwork; in reality it''s one of the most intellectually demanding legal specialties, involving genuinely complex statutory interpretation and creative structuring, with high stakes for clients in both litigation and planning contexts.', 'Interviews assess technical tax knowledge depth (walk through a complex tax structuring scenario) more than general legal writing, and firms specifically value LL.M. coursework and grades in tax-specific classes as signals of genuine specialization.'),
  ('Mergers & Acquisitions Lawyer', 'Structures and negotiates the legal terms of company acquisitions and mergers under significant deal pressure.', 195000, 6, 'J.D. + bar admission', ARRAY['Deal structuring', 'Negotiation', 'Contract law', 'Due diligence']::text[], '{"quadrant_a":0.3,"quadrant_b":0.85,"quadrant_c":0.5,"quadrant_d":0.2,"pace_preference":0.75,"risk_tolerance":0.4}'::jsonb, '2025-09-01'::date, '23-1011', 4.1, 151160, 31.5, 'close', 'Matches BLS Lawyers (23-1011); no M&A-specific legal code exists.', 'Requires a J.D. from a well-ranked school with strong grades, entering via the standard 2L summer associate pipeline into a firm''s M&A/corporate practice group; this is one of the more prestigious and competitive practice groups to land within a firm, so top-tier grades and demonstrated interest in deal work (business law journal, corporate law coursework) help.', 'Summer Associate, then M&A Associate through 6-8 years of intense deal work, then Senior Associate/Counsel, then Partner, hours and deal intensity in this practice group are among the highest in law, and many transition in-house to a company''s M&A/corporate development legal team after several years.', ARRAY['Contract/deal structuring fundamentals', 'Negotiation skills', 'Corporate law and securities basics', 'Due diligence process literacy', 'Stamina for unpredictable, deadline-driven deal timelines']::text[], 'People imagine glamorous high-level dealmaking; junior M&A associates spend enormous time on due diligence document review and drafting/redlining ancillary agreements, with the actual negotiation typically handled by partners while associates support execution.', 'Interviews weight law school prestige and grades heavily as the initial filter for landing in this competitive practice group; conversations then assess genuine interest in transactional/business work and composure under the group''s notoriously demanding hours.'),
  ('In-House Corporate Counsel', 'Serves as a company''s internal legal advisor, balancing legal risk against business goals day to day.', 155000, 6, 'J.D. + bar admission', ARRAY['Legal risk assessment', 'Contract review', 'Business partnering', 'Pragmatic judgment']::text[], '{"quadrant_a":0.3,"quadrant_b":0.85,"quadrant_c":0.5,"quadrant_d":0.2,"pace_preference":0.5,"risk_tolerance":0.3}'::jsonb, '2025-09-01'::date, '23-1011', 4.1, 151160, 31.5, 'close', 'Matches BLS Lawyers (23-1011); BLS does not distinguish in-house from firm practice.', 'This is rarely an entry-level role: the standard path is several years, often 4-8+, at a law firm building substantive expertise (litigation, corporate, or a specialty relevant to the target company) before moving in-house; companies want lawyers already trained and tested at a firm, so those firm years function as the real credentialing period.', 'Law firm Associate for several years, then in-house Corporate Counsel or Senior Counsel, then Assistant/Deputy General Counsel, then General Counsel, the GC seat is often a capstone role requiring both legal expertise and genuine business/executive judgment.', ARRAY['Substantive legal expertise built at a law firm first', 'Legal risk assessment and pragmatic judgment, not just theoretical correctness', 'Contract review efficiency', 'Business partnering and communication with non-lawyers', 'Comfort making calls with incomplete information under time pressure']::text[], 'People think in-house is an ''easier'' or lower-stakes version of firm practice; while hours are often genuinely better, in-house counsel carry broader, more generalist responsibility with fewer specialist colleagues to lean on, and must translate legal risk into business terms constantly, a skill firm practice doesn''t always teach.', 'In-house interviews assess pragmatic business judgment (how would you advise on this ambiguous risk) more than pure legal technical depth, since companies want counsel who can say ''here''s the risk and here''s what I''d do'' rather than a purely academic legal analysis.'),
  ('Regulatory / Compliance Attorney', 'Ensures a company''s practices meet complex, evolving legal and regulatory requirements.', 148000, 6, 'J.D. + bar admission', ARRAY['Regulatory analysis', 'Policy interpretation', 'Risk assessment', 'Legal writing']::text[], '{"quadrant_a":0.5,"quadrant_b":0.92,"quadrant_c":0.2,"quadrant_d":0.05,"pace_preference":0.4,"risk_tolerance":0.15}'::jsonb, '2025-09-01'::date, '23-1011', 4.1, 151160, 31.5, 'close', 'Matches BLS Lawyers (23-1011); the compliance specialization isn''t broken out separately for attorneys.', 'Requires a J.D. and bar admission, with entry typically via a law firm''s regulatory practice group, a government regulatory agency (SEC, FDA, FTC depending on industry), or directly into a corporate compliance department; government agency experience is a particularly valued credential since it provides direct insight into how regulators actually think and enforce.', 'Associate in a regulatory practice group or government attorney, then Senior Associate/Counsel, then Partner or transition in-house to Compliance Counsel, then Chief Compliance Officer or General Counsel, moving between government and private practice, a ''revolving door,'' is common and valued in this specialty.', ARRAY['Deep regulatory framework knowledge in a target industry', 'Policy interpretation and analysis', 'Legal writing for regulatory filings/responses', 'Risk assessment', 'Comfort with ambiguous, evolving rules']::text[], 'People think regulatory law is a narrow, dry specialty; it''s actually central to how entire industries operate day-to-day, and regulatory attorneys often have outsized influence on business strategy since a single interpretation can determine whether a whole product or business line is viable.', 'Interviews test deep knowledge of the specific regulatory regime relevant to the practice (securities, healthcare, environmental, etc.) and often include scenario-based questions on how you''d advise a client navigating an ambiguous or newly-changed regulation.'),
  ('Mechanical Engineer', 'Designs and tests mechanical systems and products following engineering standards and iterative prototyping.', 99510, 7, 'Bachelor''s degree', ARRAY['CAD', 'Thermodynamics', 'Prototyping', 'Problem-solving']::text[], '{"quadrant_a":0.88,"quadrant_b":0.28,"quadrant_c":0.12,"quadrant_d":0.45,"pace_preference":0.35,"risk_tolerance":0.3}'::jsonb, '2025-09-01'::date, '17-2141', 9.1, 102320, 18.1, 'exact', 'Direct match to BLS Mechanical Engineers (17-2141).', 'Requires a Bachelor''s in Mechanical Engineering (ABET-accredited programs matter for employer recognition and PE licensure eligibility); internships/co-ops during school are the dominant hiring pipeline, and hands-on project experience, such as Formula SAE, robotics club, or personal builds, differentiates candidates as much as GPA.', 'Design/Junior Engineer, then Engineer II, then Senior Engineer, then Lead Engineer or Engineering Manager, then Principal Engineer or Director of Engineering, the ladder forks between deep technical IC specialization and people management, and PE licensure (via FE then PE exams) matters more in some industries (infrastructure, safety-critical) than others (consumer products).', ARRAY['CAD proficiency (SolidWorks, AutoCAD)', 'Core engineering coursework (thermodynamics, statics, materials)', 'Hands-on prototyping/building experience', 'Internship/co-op experience', 'FE exam preparation if targeting the PE licensure track']::text[], 'People imagine constant creative invention; much of the real job is iterative refinement, tolerance analysis, and manufacturing-constraint problem-solving on existing designs rather than inventing something from a blank page.', 'Interviews test fundamentals (statics, thermo, materials problems) and ask you to walk through past projects in technical depth, probing whether you actually understood the engineering behind what you built, not just that you built it.'),
  ('Electrical Engineer', 'Designs electrical systems and components, from circuits to power infrastructure, following technical standards.', 109010, 5, 'Bachelor''s degree', ARRAY['Circuit design', 'Signal analysis', 'Technical documentation', 'Testing']::text[], '{"quadrant_a":0.88,"quadrant_b":0.48,"quadrant_c":0.12,"quadrant_d":0.25,"pace_preference":0.35,"risk_tolerance":0.25}'::jsonb, '2025-09-01'::date, '17-2071', 7.2, 111910, 11.7, 'exact', 'Direct match to BLS Electrical Engineers (17-2071).', 'Requires a Bachelor''s in Electrical Engineering (ABET-accredited); internships/co-ops are the dominant pipeline into full-time roles, and hands-on project experience, such as personal circuit builds, robotics, ham radio, or FPGA projects, signals genuine competence beyond coursework.', 'Junior EE, then Engineer II, then Senior Engineer, then Lead/Principal Engineer or Engineering Manager, then Director of Engineering, specialization typically deepens into a sub-domain (power systems, signal processing, RF, embedded systems) fairly early.', ARRAY['Circuit design and analysis fundamentals', 'Programming for embedded systems (C/C++)', 'Signal analysis coursework', 'Hands-on lab/project experience', 'Internship/co-op experience']::text[], 'People conflate EE with software engineering or think it''s purely theoretical; real EE work involves significant hands-on debugging of physical hardware: a circuit that doesn''t behave like the simulation said it would, which requires patience with physical, not just logical, troubleshooting.', 'Interviews test circuit analysis fundamentals and ask candidates to debug a described circuit problem, alongside project walkthroughs assessing genuine hands-on competence versus textbook-only knowledge.'),
  ('Civil Engineer', 'Designs and oversees infrastructure projects following building codes, safety standards, and structured project phases.', 95890, 5, 'Bachelor''s degree + P.E. license', ARRAY['Structural analysis', 'CAD', 'Code compliance', 'Project sequencing']::text[], '{"quadrant_a":0.5,"quadrant_b":0.85,"quadrant_c":0.25,"quadrant_d":0.15,"pace_preference":0.35,"risk_tolerance":0.15}'::jsonb, '2025-09-01'::date, '17-2051', 5, 99590, 23.6, 'exact', 'Direct match to BLS Civil Engineers (17-2051).', 'Requires a Bachelor''s in Civil Engineering (ABET-accredited) plus, critically, passing the FE exam during or right after school and working toward PE licensure, required for signing off on public infrastructure work, over the following roughly 4 years; internships with civil/structural firms or municipal engineering departments are the standard pipeline.', 'EIT (Engineer in Training, pre-PE), then Staff Engineer, then Project Engineer, then Project Manager/PE-licensed Senior Engineer, then Principal Engineer or Firm Partner, PE licensure around year 4 is a genuine career gate, unlocking the ability to stamp and take legal responsibility for designs.', ARRAY['FE exam preparation (start in school)', 'CAD/civil design software (Civil 3D, AutoCAD)', 'Structural analysis fundamentals', 'Code compliance knowledge', 'Internship experience with a civil/structural firm']::text[], 'People think it''s just building roads and bridges in the field; a large share of the job is desk-based design, code compliance review, and regulatory coordination, and the PE licensure requirement, not needed in most other engineering fields, is an underappreciated multi-year commitment.', 'Interviews test fundamentals (structural analysis, code knowledge) and FE/PE exam progress, plus project walkthroughs assessing your role and technical contribution on real design work, since firms want to see you can eventually be trusted with licensed sign-off responsibility.'),
  ('Chemical Engineer', 'Designs industrial chemical processes, scaling reactions safely from lab to full production.', 112100, 6, 'Bachelor''s degree', ARRAY['Process design', 'Thermodynamics', 'Safety engineering', 'Process optimization']::text[], '{"quadrant_a":0.88,"quadrant_b":0.5,"quadrant_c":0.12,"quadrant_d":0.25,"pace_preference":0.35,"risk_tolerance":0.2}'::jsonb, '2025-09-01'::date, '17-2041', 2.6, 121860, 1.1, 'exact', 'Direct match to BLS Chemical Engineers (17-2041).', 'Requires a Bachelor''s in Chemical Engineering (ABET-accredited, among the more rigorous engineering curricula); internships/co-ops at chemical, oil & gas, or pharma manufacturing companies are the dominant pipeline, and plant/process experience during school, even a summer plant tour program, helps candidates stand out.', 'Process Engineer, then Senior Process Engineer, then Lead Engineer or Process Engineering Manager, then Plant/Technical Director, the ladder can also lead toward process safety, R&D, or plant operations management tracks depending on interest.', ARRAY['Process design and simulation software (Aspen)', 'Thermodynamics and mass/energy balance fundamentals', 'Safety engineering principles', 'Internship/co-op experience at a plant or process facility', 'Process optimization coursework']::text[], 'People confuse it with lab chemistry; chemical engineers rarely work in a traditional wet lab day-to-day: the job is about scaling chemical processes safely to industrial volumes, which is fundamentally an engineering and safety problem, not a chemistry research problem.', 'Interviews test process design fundamentals (mass/energy balances, unit operations) and safety-mindedness through scenario questions, since a design error in this field can have serious safety consequences at industrial scale.'),
  ('Aerospace Engineer', 'Designs aircraft and spacecraft systems, working at the edge of what''s physically possible.', 130720, 6, 'Bachelor''s/Master''s degree', ARRAY['Aerodynamics', 'CAD/simulation', 'Systems engineering', 'Testing']::text[], '{"quadrant_a":0.92,"quadrant_b":0.3,"quadrant_c":0.1,"quadrant_d":0.45,"pace_preference":0.3,"risk_tolerance":0.3}'::jsonb, '2025-09-01'::date, '17-2011', 6.1, 134830, 4.5, 'exact', 'Direct match to BLS Aerospace Engineers (17-2011).', 'Requires a Bachelor''s/Master''s in Aerospace Engineering (ABET-accredited); internships at major aerospace/defense contractors or newer space companies are highly competitive and the dominant pipeline, with hands-on project team experience (rocketry club, AIAA design competitions) being a genuinely strong differentiator. US citizenship is often required for defense-related roles due to security clearance requirements, a real constraint many students don''t anticipate.', 'Junior Aerospace Engineer, then Engineer II, then Senior Engineer, then Lead/Principal Engineer or Engineering Manager, then Chief Engineer or Program Director, specialization typically deepens into a sub-domain (propulsion, structures, avionics, aerodynamics) early in the career.', ARRAY['Aerodynamics and propulsion coursework', 'CAD/simulation software (CATIA, ANSYS)', 'Systems engineering fundamentals', 'Hands-on project team experience (rocketry, AIAA competitions)', 'Awareness of security clearance requirements if targeting defense work']::text[], 'People imagine glamorous rocket-launch moments constantly; the actual daily work is dominated by rigorous testing, documentation, and safety margin analysis, and the industry''s slow-moving, highly regulated pace, especially at legacy defense contractors, surprises people expecting a fast-moving tech-startup feel.', 'Interviews test core aerospace fundamentals (aerodynamics, structures, propulsion basics) and project walkthroughs of hands-on work, with defense-related roles also screening for clearance eligibility early in the process.'),
  ('Industrial Engineer', 'Optimizes complex systems and processes, such as factories, supply chains, and hospitals, for efficiency and quality.', 96350, 10, 'Bachelor''s degree', ARRAY['Process optimization', 'Statistics', 'Systems analysis', 'Lean methodology']::text[], '{"quadrant_a":0.5,"quadrant_b":0.85,"quadrant_c":0.25,"quadrant_d":0.2,"pace_preference":0.45,"risk_tolerance":0.25}'::jsonb, '2025-09-01'::date, '17-2112', 11, 101140, 25.2, 'exact', 'Direct match to BLS Industrial Engineers (17-2112).', 'Requires a Bachelor''s in Industrial Engineering (ABET-accredited) or a related field (operations research, systems engineering); internships in manufacturing, logistics, or operations roles are the dominant pipeline, and this degree is unusually versatile: graduates often enter consulting, supply chain, or operations roles beyond traditional ''engineering'' job titles.', 'Industrial/Process Engineer, then Senior Engineer, then Operations Manager or Continuous Improvement Lead, then Director of Operations/Plant Manager, the degree''s versatility means many industrial engineers pivot into general operations or supply chain leadership rather than staying in a narrow technical IE track.', ARRAY['Process optimization/Lean Six Sigma methodology', 'Statistics', 'Systems analysis and simulation software', 'Data analysis (Excel, SQL)', 'Internship experience in a manufacturing or operations setting']::text[], 'People aren''t sure what industrial engineers actually do since the title is vague; the real job is optimizing complex systems, such as factories, hospitals, and supply chains, for efficiency, a genuinely broad and practical skill set applicable far beyond manufacturing.', 'Interviews test process improvement case scenarios (here''s an inefficient system, how would you improve it) and statistics/Lean methodology knowledge, with a strong emphasis on structured problem-solving similar to consulting case interviews.'),
  ('Materials Science Engineer', 'Develops new materials with specific properties, from lab research through to industrial application.', 100090, 6, 'Bachelor''s/Master''s degree', ARRAY['Materials characterization', 'Research methodology', 'Chemistry/physics', 'Experimental design']::text[], '{"quadrant_a":0.93,"quadrant_b":0.3,"quadrant_c":0.1,"quadrant_d":0.45,"pace_preference":0.25,"risk_tolerance":0.3}'::jsonb, '2025-09-01'::date, '17-2131', 5.7, 108310, 1.5, 'close', 'Matches BLS Materials Engineers (17-2131); same occupation, slightly different common naming.', 'Requires a Bachelor''s/Master''s in Materials Science and Engineering; research experience during undergrad, even unpaid lab work, is a significant differentiator since much entry-level work in this field is R&D-adjacent, and many roles beyond entry-level expect a Master''s or PhD for genuine research responsibility.', 'Materials Engineer/Research Associate, then Senior Materials Engineer, then Principal Engineer or R&D Team Lead, then Director of Materials R&D, PhD holders often enter at a higher research-track level, while Bachelor''s-level engineers more commonly move toward manufacturing/quality-focused roles.', ARRAY['Materials characterization techniques (microscopy, spectroscopy)', 'Research methodology and lab technique', 'Chemistry/physics coursework depth', 'Experimental design', 'Undergraduate research lab experience']::text[], 'People think it''s a narrow academic field; materials scientists work across an enormous range of industries, such as batteries, semiconductors, aerospace, and medical devices, and much of the real value is translating fundamental materials properties into manufacturable, cost-effective products, not just discovering new materials.', 'Interviews test materials science fundamentals and often review your research experience/thesis work in depth, since demonstrated hands-on lab competence is the strongest signal of readiness for R&D-adjacent roles.'),
  ('Environmental Engineer', 'Designs systems and solutions to address pollution, water quality, and environmental regulatory compliance.', 96820, 6, 'Bachelor''s degree', ARRAY['Environmental regulation', 'Systems design', 'Data analysis', 'Technical writing']::text[], '{"quadrant_a":0.85,"quadrant_b":0.5,"quadrant_c":0.2,"quadrant_d":0.25,"pace_preference":0.35,"risk_tolerance":0.25}'::jsonb, '2025-09-01'::date, '17-2081', 3.9, 104170, 3, 'exact', 'Direct match to BLS Environmental Engineers (17-2081).', 'Requires a Bachelor''s in Environmental Engineering or Civil Engineering with an environmental focus (ABET-accredited); internships with environmental consulting firms, water utilities, or government environmental agencies (EPA, state departments) are the standard pipeline, and PE licensure matters for signing off on regulated work similar to civil engineering.', 'Staff Environmental Engineer (EIT), then Project Engineer, then Senior Engineer/PE, then Project Manager, then Principal Engineer or Practice Lead, many build careers at environmental consulting firms moving between projects (remediation, water treatment, compliance) for different clients.', ARRAY['Environmental regulation knowledge (Clean Water Act, Clean Air Act basics)', 'FE exam preparation', 'Systems design fundamentals', 'Data analysis and technical writing', 'Internship experience with an environmental consulting firm or agency']::text[], 'People imagine fieldwork and dramatic cleanup operations constantly; a large share of the real job is desk-based regulatory compliance writing and permit applications: less hands-on and more paperwork-and-analysis-driven than the ''environmental hero'' image suggests.', 'Interviews test regulatory knowledge and technical design fundamentals, plus project walkthroughs of internship/coursework experience, with consulting firms specifically assessing client communication readiness since the role involves regular client-facing reporting.'),
  ('Structural Engineer', 'Ensures buildings and infrastructure can safely bear the loads and forces they''ll face over their lifetime.', 100000, 5, 'Bachelor''s degree + P.E. license', ARRAY['Structural analysis', 'CAD', 'Code compliance', 'Risk assessment']::text[], '{"quadrant_a":0.5,"quadrant_b":0.9,"quadrant_c":0.12,"quadrant_d":0.1,"pace_preference":0.3,"risk_tolerance":0.1}'::jsonb, '2025-09-01'::date, '17-2051', 5, 99590, 23.6, 'approximate', 'BLS does not break out structural engineering as its own code; it is subsumed under Civil Engineers (17-2051).', 'Requires a Bachelor''s/Master''s in Civil or Structural Engineering (ABET-accredited) plus the FE and eventually PE exam, often the separate, harder Structural Engineering SE exam for higher-risk structures; internships at structural engineering or architecture-engineering firms are the standard pipeline, and this is one of the more exam-gated engineering disciplines.', 'EIT/Staff Structural Engineer, then Project Engineer, then Senior Engineer/PE, then Project Manager, then Principal or Associate at a structural firm, PE (and often SE) licensure is a hard gate for signing structural drawings, making it a more credential-bound path than many engineering fields.', ARRAY['Structural analysis fundamentals (statics, mechanics of materials)', 'FE and PE/SE exam preparation', 'CAD/structural analysis software (RISA, ETABS)', 'Building code knowledge', 'Internship experience at a structural engineering firm']::text[], 'People think it''s interchangeable with architecture; structural engineers focus narrowly on ensuring a building can safely bear its loads, a highly quantitative, safety-critical, and legally liable role distinct from an architect''s aesthetic and spatial design focus.', 'Interviews test structural analysis fundamentals directly (load calculations, material behavior) and code compliance knowledge, with firms weighting exam progress, FE passed, working toward PE/SE, as a genuine hiring and promotion signal.'),
  ('Petroleum Engineer', 'Designs methods for extracting oil and gas efficiently and safely from reservoirs.', 135690, 2, 'Bachelor''s degree', ARRAY['Reservoir engineering', 'Technical modeling', 'Field operations knowledge', 'Risk assessment']::text[], '{"quadrant_a":0.85,"quadrant_b":0.5,"quadrant_c":0.15,"quadrant_d":0.3,"pace_preference":0.45,"risk_tolerance":0.35}'::jsonb, '2025-09-01'::date, '17-2171', 1.3, 141280, 1.2, 'exact', 'Direct match to BLS Petroleum Engineers (17-2171).', 'Requires a Bachelor''s in Petroleum Engineering, a smaller, more specialized set of programs than other engineering disciplines; internships with major oil & gas companies or oilfield service companies (Schlumberger, Halliburton) are the dominant pipeline, and this field is notably more boom-bust in hiring demand, tracking oil prices closely, which candidates should factor into career planning.', 'Field/Junior Petroleum Engineer, then Reservoir/Drilling/Production Engineer (specializing), then Senior Engineer, then Engineering Manager or Asset Team Lead, then Technical Director, many spend early years with significant field/rig rotation before moving to more office-based technical or management roles.', ARRAY['Reservoir engineering fundamentals', 'Technical modeling software specific to the industry', 'Field operations exposure/internships', 'Risk assessment', 'Awareness of the industry''s cyclical hiring patterns']::text[], 'People assume it''s a stable, high-paying field without volatility; compensation and hiring are notably tied to oil price cycles, with real boom-and-bust hiring swings that can significantly affect early-career job security in ways more insulated engineering fields don''t experience.', 'Interviews test reservoir/drilling engineering fundamentals and often include technical case problems specific to the field, with willingness to do field/rig rotations early in career being a genuine and explicitly assessed factor.'),
  ('Nuclear Engineer', 'Designs and oversees nuclear systems used for power generation or research, under strict safety protocol.', 129210, 6, 'Bachelor''s/Master''s degree', ARRAY['Nuclear physics', 'Safety engineering', 'Systems analysis', 'Regulatory compliance']::text[], '{"quadrant_a":0.93,"quadrant_b":0.55,"quadrant_c":0.08,"quadrant_d":0.15,"pace_preference":0.3,"risk_tolerance":0.1}'::jsonb, '2025-09-01'::date, '17-2161', -1.1, 127520, 0.8, 'exact', 'Direct match to BLS Nuclear Engineers (17-2161).', 'Requires a Bachelor''s/Master''s in Nuclear Engineering, a smaller set of specialized programs; internships or co-ops at nuclear utilities, national labs, or the Navy''s nuclear program, a well-known alternative pipeline, since Naval Nuclear Propulsion Program veterans are heavily recruited into civilian nuclear roles, are the dominant pathways. Security clearance requirements and US citizenship are common constraints given the field''s national security relevance.', 'Junior Nuclear Engineer, then Reactor/Systems Engineer, then Senior Engineer, then Engineering Supervisor or Licensing Manager, then Plant Engineering Director, a genuinely distinct path exists via the Navy''s nuclear program, years of hands-on reactor operations experience that translates strongly into civilian nuclear careers.', ARRAY['Nuclear physics coursework depth', 'Safety engineering and regulatory (NRC) knowledge', 'Systems analysis', 'The Navy Nuclear program as an alternative training pipeline', 'Attention to detail and procedural discipline']::text[], 'People assume the field is shrinking given fewer new plants built in past decades; there''s actually significant institutional demand for engineers to maintain and eventually decommission the existing fleet, plus renewed interest in new reactor designs (SMRs), and procedural discipline matters as much as raw technical brilliance in this heavily safety-regulated field.', 'Interviews test nuclear physics/safety fundamentals and regulatory knowledge, with a strong emphasis on demonstrated procedural discipline and safety-mindedness: utilities specifically probe for candidates who won''t cut corners under production pressure.'),
  ('Biomedical Engineer', 'Designs medical devices and equipment, combining engineering rigor with an understanding of human biology.', 100730, 5, 'Bachelor''s/Master''s degree', ARRAY['Medical device design', 'Biology knowledge', 'CAD/prototyping', 'Regulatory standards']::text[], '{"quadrant_a":0.85,"quadrant_b":0.3,"quadrant_c":0.15,"quadrant_d":0.45,"pace_preference":0.35,"risk_tolerance":0.3}'::jsonb, '2025-09-01'::date, '17-2031', 5.2, 106950, 1.3, 'exact', 'Direct match to BLS Bioengineers and Biomedical Engineers (17-2031).', 'Requires a Bachelor''s/Master''s in Biomedical Engineering or a related engineering degree with biology coursework; internships at medical device companies are the dominant pipeline, and FDA regulatory coursework or exposure is a genuine differentiator since almost all BME work eventually intersects with regulatory approval processes.', 'R&D/Design Engineer, then Senior Engineer, then Lead Engineer or Engineering Manager, then Director of R&D or Principal Engineer, many specialize by device category (cardiovascular, orthopedic, diagnostic imaging) and the ladder can also lead toward regulatory affairs or quality roles given the field''s compliance intensity.', ARRAY['Medical device design fundamentals', 'Biology/physiology coursework depth', 'CAD/prototyping', 'FDA regulatory pathway basics (510(k), PMA)', 'Internship experience at a device company']::text[], 'People imagine inventing dramatic new medical breakthroughs constantly; a huge share of the real job is navigating rigorous, slow-moving regulatory and quality processes since medical devices are safety-critical, and iteration cycles are far longer than in consumer tech due to required testing and approval.', 'Interviews test engineering fundamentals plus regulatory/quality-process awareness: do you understand why design controls exist, and project walkthroughs assess whether you can balance genuine innovation against the field''s heavy compliance constraints.'),
  ('Biotech Research Scientist', 'Conducts lab research to develop new therapies and technologies, from early discovery through validation.', 102270, 10, 'Ph.D. (or Master''s + experience)', ARRAY['Lab protocol', 'Experimental design', 'Molecular biology', 'Scientific writing']::text[], '{"quadrant_a":0.9,"quadrant_b":0.3,"quadrant_c":0.1,"quadrant_d":0.45,"pace_preference":0.25,"risk_tolerance":0.3}'::jsonb, '2025-09-01'::date, '19-1042', 8.7, 100590, 9.6, 'close', 'Matches BLS Medical Scientists, Except Epidemiologists (19-1042), which covers PhD-level research toward new therapies.', 'Requires a Ph.D. (or a Master''s with several years of lab experience) in a relevant life science field; the dominant pipeline is a strong PhD thesis/postdoc publication record, with lab technician or research assistant roles a common on-ramp for those building toward a PhD or entering industry directly with a Bachelor''s/Master''s.', 'Research Associate/Scientist I, then Scientist II, then Senior Scientist, then Principal Scientist or Group Leader, then Director of Research, PhD holders typically enter at a higher band, and the ladder forks between deep bench-science IC work and managing a research team.', ARRAY['Lab protocol and technique mastery', 'Experimental design', 'Molecular biology fundamentals', 'Scientific writing/publication', 'Undergraduate or graduate research lab experience']::text[], 'People imagine constant breakthrough discoveries; the real daily work is dominated by failed experiments, painstaking protocol optimization, and repetition to confirm results are real: a good week might be one useful data point after many failed attempts.', 'Interviews, often a ''chalk talk'' at senior levels, require presenting and defending your research in depth, testing both technical rigor and how you handle tough scientific pushback, alongside standard behavioral fit questions.'),
  ('Bioinformatics Scientist', 'Analyzes massive biological datasets, such as genomes and proteins, using computational methods to drive discovery.', 118000, 15, 'Master''s/Ph.D.', ARRAY['Computational biology', 'Programming', 'Statistics', 'Genomics']::text[], '{"quadrant_a":0.95,"quadrant_b":0.3,"quadrant_c":0.08,"quadrant_d":0.4,"pace_preference":0.3,"risk_tolerance":0.25}'::jsonb, '2025-09-01'::date, '19-1021', 5.8, 103650, 2.9, 'approximate', 'No dedicated bioinformatics code; mapped to Biochemists and Biophysicists (19-1021), though this role equally overlaps with Computer and Information Research Scientists (15-1221) given its heavy computational focus.', 'Requires a Master''s/PhD combining biology and computational training, a genuinely interdisciplinary degree, sometimes self-assembled via a biology PhD plus self-taught programming, or a CS background plus biology coursework; demonstrated coding ability on real genomic/biological datasets (a GitHub portfolio with real analysis pipelines) is a strong differentiator alongside the degree.', 'Bioinformatics Analyst/Scientist, then Senior Bioinformatics Scientist, then Principal Scientist or Bioinformatics Team Lead, then Director of Computational Biology, the ladder forks between deep computational research and building/leading bioinformatics infrastructure for an organization.', ARRAY['Programming (Python/R) for biological data', 'Statistics', 'Genomics/molecular biology fundamentals', 'Computational pipeline building', 'A portfolio of real bioinformatics analysis projects']::text[], 'People think it''s mostly biology with a bit of coding; in well-funded biotech/pharma settings it''s often closer to genuine software/data engineering applied to biological problems, requiring real computational rigor, not just running existing bioinformatics tools without understanding them.', 'Interviews test both programming/statistics ability, often a coding exercise on genomic-style data, and biological domain knowledge, with strong candidates able to explain both the computational method and the underlying biology it''s answering a question about.'),
  ('Genetic Engineer', 'Modifies organisms at the genetic level for medical, agricultural, or industrial applications.', 108000, 9, 'Master''s/Ph.D.', ARRAY['Molecular biology', 'Gene editing techniques', 'Lab protocol', 'Experimental design']::text[], '{"quadrant_a":0.9,"quadrant_b":0.3,"quadrant_c":0.08,"quadrant_d":0.5,"pace_preference":0.3,"risk_tolerance":0.35}'::jsonb, '2025-09-01'::date, '19-1021', 5.8, 103650, 2.9, 'approximate', 'No dedicated genetic-engineering code; mapped to Biochemists and Biophysicists (19-1021) as the closest molecular/cellular research category.', 'Requires a Master''s/PhD in molecular biology, genetics, or a related field with hands-on gene editing lab experience (CRISPR, cloning techniques); PhD lab rotations and postdoc work are the dominant pipeline into research-scientist-level industry roles, with a track record of successful, reproducible experiments mattering more than the specific institution.', 'Research Associate/Scientist, then Senior Scientist, then Principal Scientist or Lab Head, then Director of Research, many eventually specialize deeply in a single application area (gene therapy, agricultural biotech, industrial enzyme engineering) as the field has diversified significantly.', ARRAY['Molecular biology fundamentals', 'Gene editing technique mastery (CRISPR, cloning)', 'Lab protocol discipline', 'Experimental design', 'PhD-level or extensive hands-on lab research experience']::text[], 'People imagine dramatic ''designer organism'' work; most real genetic engineering work is incremental and narrowly targeted: editing one gene for one specific therapeutic or agricultural purpose, and the ethical/regulatory scrutiny on the field is far more intensive than popular science coverage suggests.', 'Interviews, often a research presentation or chalk talk, test deep technical knowledge of your specific gene editing experience and require defending experimental design choices under detailed questioning from scientist panels.'),
  ('Clinical Research Associate', 'Monitors clinical trials to ensure they''re run safely, ethically, and in compliance with regulation.', 78000, 12, 'Bachelor''s degree (life sciences)', ARRAY['Clinical trial protocol', 'Regulatory compliance', 'Attention to detail', 'Site coordination']::text[], '{"quadrant_a":0.5,"quadrant_b":0.9,"quadrant_c":0.3,"quadrant_d":0.08,"pace_preference":0.45,"risk_tolerance":0.15}'::jsonb, '2025-09-01'::date, '19-1042', 8.7, 100590, 9.6, 'approximate', 'No dedicated CRA/clinical-research-coordinator code; mapped to Medical Scientists, Except Epidemiologists (19-1042) as the closest subject-matter category, though that BLS occupation is typically PhD-level while CRAs are usually bachelor''s-level, a real seniority mismatch.', 'Requires a Bachelor''s degree in a life science field; entry is often via a Clinical Trial Assistant or Coordinator role first, building toward CRA, or direct entry with strong internship/research experience: certifications like ACRP or SOCRA help but aren''t always required for the first job, and this is a genuinely accessible entry point into the broader clinical/pharma industry from a Bachelor''s alone.', 'Clinical Trial Assistant/Coordinator, then CRA, then Senior CRA, then Clinical Research Manager, then Director of Clinical Operations, significant travel to trial sites is standard in the CRA years, tapering off as you move into management.', ARRAY['Clinical trial protocol/GCP (Good Clinical Practice) knowledge', 'Regulatory compliance basics', 'Attention to detail', 'Site coordination and communication', 'Willingness and ability to travel frequently']::text[], 'People underestimate how much of the job is travel and administrative monitoring: visiting trial sites to audit documentation and ensure protocol compliance, rather than hands-on scientific research; it''s closer to quality assurance/auditing than lab science.', 'Interviews test knowledge of GCP and regulatory basics, attention-to-detail scenarios (spot the documentation error), and willingness/logistics for travel, since site monitoring is the core of the entry-level role.'),
  ('Regulatory Affairs Specialist (Biotech/Pharma)', 'Guides new drugs and devices through regulatory approval, translating science into compliance strategy.', 105000, 8, 'Bachelor''s/Master''s degree', ARRAY['Regulatory strategy', 'Scientific writing', 'Compliance', 'Cross-functional coordination']::text[], '{"quadrant_a":0.5,"quadrant_b":0.88,"quadrant_c":0.3,"quadrant_d":0.1,"pace_preference":0.35,"risk_tolerance":0.15}'::jsonb, '2025-09-01'::date, '13-1041', 3, 78420, 33.3, 'approximate', 'No FDA/biotech-specific regulatory affairs code; mapped to the general Compliance Officers category (13-1041).', 'Requires a Bachelor''s/Master''s in a life science field, with entry often via a related role first, such as quality assurance, clinical research, or technical writing, before moving into regulatory affairs specifically; RAC (Regulatory Affairs Certification) is a genuinely valued industry credential that can be pursued early career to signal seriousness about the specialty.', 'Regulatory Affairs Associate, then Regulatory Affairs Specialist, then Senior Specialist/Manager, then Director of Regulatory Affairs, then VP Regulatory Affairs, this path can also lead toward Chief Regulatory Officer roles or consulting for smaller biotechs that don''t have in-house regulatory teams.', ARRAY['Regulatory strategy and FDA/EMA submission process knowledge', 'Scientific/technical writing', 'Cross-functional coordination (working with R&D, clinical, legal)', 'Compliance and documentation discipline', 'RAC certification coursework']::text[], 'People think it''s a purely administrative paperwork role; regulatory affairs specialists actually have major strategic influence: the submission strategy can determine whether a drug reaches market years earlier or later, making it one of the highest-leverage non-scientist roles in a biotech company.', 'Interviews test knowledge of specific regulatory pathways (FDA 510(k) vs. PMA, IND/NDA processes) relevant to the company''s product type, and scenario questions on how you''d handle a regulatory setback or agency request for additional data.'),
  ('Biomedical Researcher', 'Conducts lab research to advance medical treatment, following rigorous experimental protocol.', 100890, 10, 'Ph.D.', ARRAY['Lab protocol', 'Statistical analysis', 'Experimental design', 'Scientific writing']::text[], '{"quadrant_a":0.92,"quadrant_b":0.5,"quadrant_c":0.1,"quadrant_d":0.3,"pace_preference":0.25,"risk_tolerance":0.25}'::jsonb, '2025-09-01'::date, '19-1042', 8.7, 100590, 9.6, 'close', 'Matches BLS Medical Scientists, Except Epidemiologists (19-1042).', 'Requires a Ph.D. in a biomedical science field; the dominant pipeline is graduate school lab rotations building toward a specific mentor/lab, then postdoctoral training, often required before an independent research position, with publication record in respected journals the primary currency throughout.', 'PhD student, then Postdoctoral Researcher for 3-6 years, then Research Scientist/Assistant Professor (academic) or Scientist role (industry), then Senior Scientist/Associate Professor, then Principal Investigator/Full Professor or Research Director, the academic track specifically requires securing independent grant funding to run your own lab, a genuinely difficult, competitive milestone.', ARRAY['Lab protocol and experimental design mastery', 'Statistical analysis', 'Scientific writing and grant-writing', 'Undergraduate research experience (start early)', 'Resilience for a long training pipeline with real uncertainty of outcome']::text[], 'People think a PhD guarantees a stable research career; the academic job market for principal investigator positions is notoriously competitive, and many PhDs spend years in postdoc positions with real uncertainty about ever landing a permanent research faculty role, pushing many toward industry instead.', 'Academic and industry research interviews both center on presenting and defending your research (a job talk or chalk talk), testing depth of technical knowledge and how you respond to skeptical questioning from other scientists.'),
  ('Pharmaceutical Scientist', 'Develops and tests new drug formulations, from early discovery through manufacturing readiness.', 115000, 9, 'Ph.D. (or Master''s + experience)', ARRAY['Drug formulation', 'Lab protocol', 'Chemistry', 'Experimental design']::text[], '{"quadrant_a":0.92,"quadrant_b":0.5,"quadrant_c":0.1,"quadrant_d":0.3,"pace_preference":0.3,"risk_tolerance":0.25}'::jsonb, '2025-09-01'::date, '19-1042', 8.7, 100590, 9.6, 'approximate', 'No dedicated pharma-scientist code; mapped to Medical Scientists, Except Epidemiologists (19-1042) as the closest PhD-level drug-development research category (Chemists, 19-2031, is a plausible alternative).', 'Requires a Ph.D. (or Master''s with substantial experience) in pharmaceutical sciences, chemistry, or a related field; graduate research specifically in drug formulation or delivery is the strongest differentiator, and internships at pharma companies during a PhD program are a valuable pipeline into full-time roles.', 'Scientist I/Formulation Scientist, then Scientist II, then Senior Scientist, then Principal Scientist or Group Leader, then Director of Pharmaceutical Sciences, the ladder forks between deep bench formulation science and managing a formulation/development team.', ARRAY['Drug formulation techniques', 'Lab protocol discipline', 'Chemistry depth (organic/analytical)', 'Experimental design', 'Graduate research experience in formulation or delivery science']::text[], 'People think it''s mostly discovering new drug molecules: that''s more medicinal chemistry/drug discovery; pharmaceutical scientists are actually often focused on the less glamorous but critical work of making an already-discovered drug stable, bioavailable, and manufacturable at scale.', 'Interviews, often including a research presentation, test formulation science depth and require defending experimental choices, with panels probing whether you understand the full journey from lab-scale formulation to manufacturing readiness.'),
  ('Clinical Trials / Drug Development Manager', 'Runs the process of testing new drugs in humans, coordinating science, regulation, and operations.', 135000, 10, 'Master''s degree (life sciences)', ARRAY['Clinical trial design', 'Project management', 'Regulatory knowledge', 'Cross-functional leadership']::text[], '{"quadrant_a":0.5,"quadrant_b":0.85,"quadrant_c":0.3,"quadrant_d":0.15,"pace_preference":0.5,"risk_tolerance":0.3}'::jsonb, '2025-09-01'::date, '11-9121', 3.7, 161180, 8.5, 'close', 'Matches BLS Natural Sciences Managers (11-9121), which covers directing life-science R&D activities.', 'Requires a Master''s degree in a life science field, or a Bachelor''s with significant clinical research experience, typically building up from a Clinical Research Associate or Coordinator role over several years before moving into a management position overseeing trial operations; project management certifications (PMP) are a genuine differentiator for this cross-functional coordination-heavy role.', 'CRA/Clinical Trial Coordinator, then Clinical Trial Manager, then Senior Clinical Trial Manager or Associate Director, then Director of Clinical Operations, then VP Clinical Development, progression ties closely to successfully managing increasingly large and complex trials.', ARRAY['Clinical trial design and GCP knowledge', 'Project management fundamentals (consider PMP)', 'Regulatory knowledge', 'Cross-functional leadership (managing sites, CROs, internal teams)', 'Budget/timeline management']::text[], 'People think it''s primarily a scientific role; the real job is heavily project management and vendor coordination: managing budgets, timelines, and dozens of external trial sites and contract research organizations, with scientific knowledge as necessary context rather than the daily focus.', 'Interviews test project management scenarios (a trial is behind schedule due to slow patient enrollment, what do you do) and cross-functional coordination examples, assessing whether you can keep a complex, multi-stakeholder process on track under regulatory constraints.'),
  ('Medical Science Liaison', 'Bridges pharmaceutical research and practicing physicians, communicating complex clinical data.', 155000, 8, 'Ph.D./Pharm.D./M.D. (or advanced life sciences degree)', ARRAY['Scientific communication', 'Relationship building', 'Clinical knowledge', 'Presentation skills']::text[], '{"quadrant_a":0.5,"quadrant_b":0.3,"quadrant_c":0.85,"quadrant_d":0.15,"pace_preference":0.5,"risk_tolerance":0.3}'::jsonb, '2025-09-01'::date, '19-1042', 8.7, 100590, 9.6, 'approximate', 'No dedicated MSL code; mapped to Medical Scientists, Except Epidemiologists (19-1042) as the closest scientific-subject-matter category, though MSL work (communicating with physicians) is more field-facing than typical research.', 'Requires an advanced life sciences degree: Pharm.D., PhD, or MD most common, though some companies accept a strong Master''s with clinical/research experience; this is very rarely an entry-level role: most MSLs have several years of clinical practice, research, or industry experience first, and demonstrated public speaking/scientific presentation ability is a real differentiator in interviews.', 'MSL, then Senior MSL, then MSL Team Lead/Manager, then Director of Medical Affairs, then VP Medical Affairs, this role sits at the intersection of science and commercial strategy, and strong performers often move toward broader medical affairs leadership.', ARRAY['Advanced scientific/clinical training (the credential prerequisite)', 'Scientific communication and presentation skills', 'Relationship-building with physicians/researchers', 'Clinical data literacy', 'Comfort with extensive travel: visiting physicians/institutions is core to the role']::text[], 'People confuse this with pharmaceutical sales; MSLs are explicitly barred from discussing off-label uses in a promotional way and are meant to serve as scientific/clinical peers to physicians, not salespeople, though the line can feel blurry to outsiders and even some MSLs early in the role.', 'Interviews heavily test scientific communication skill directly, often via a mock presentation of clinical data to a simulated physician audience, and assess your ability to build credibility as a genuine scientific peer rather than a sales rep.'),
  ('Pharmacologist', 'Studies how drugs interact with biological systems to inform safer, more effective treatments.', 112000, 8, 'Ph.D.', ARRAY['Pharmacology research', 'Experimental design', 'Statistical analysis', 'Scientific writing']::text[], '{"quadrant_a":0.94,"quadrant_b":0.5,"quadrant_c":0.08,"quadrant_d":0.25,"pace_preference":0.25,"risk_tolerance":0.25}'::jsonb, '2025-09-01'::date, '19-1042', 8.7, 100590, 9.6, 'close', 'Matches BLS Medical Scientists, Except Epidemiologists (19-1042), which covers drug/biological-system research.', 'Requires a Ph.D. in pharmacology or a closely related field; the dominant pipeline is graduate lab research culminating in a strong publication record, often followed by a postdoc before an industry research scientist role, similar to other PhD-level biomedical research careers.', 'PhD student, then Postdoctoral Researcher, then Research Scientist/Pharmacologist, then Senior Scientist, then Principal Scientist or Group Leader, then Director of Pharmacology, the ladder forks between deep bench research and managing a pharmacology research team within a pharma/biotech company.', ARRAY['Pharmacology research technique mastery', 'Experimental design', 'Statistical analysis', 'Scientific writing/publication', 'Graduate research experience specifically in drug-target interactions']::text[], 'People conflate this with being a pharmacist, a clinical, patient-facing role; pharmacologists are researchers studying how drugs interact with biological systems at a mechanistic level, working in labs rather than dispensing medication to patients.', 'Interviews, often a research presentation or chalk talk, test deep technical knowledge of your specific research and mechanistic understanding of drug-target interactions, with panels probing experimental design choices in detail.'),
  ('Management Consultant', 'Diagnoses ambiguous business problems for clients and proposes novel strategic solutions under time pressure.', 99410, 10, 'Bachelor''s/MBA', ARRAY['Structured problem-solving', 'Client communication', 'Strategic synthesis', 'Adaptability']::text[], '{"quadrant_a":0.3,"quadrant_b":0.15,"quadrant_c":0.5,"quadrant_d":0.85,"pace_preference":0.7,"risk_tolerance":0.5}'::jsonb, '2025-09-01'::date, '13-1111', 8.8, 101190, 98.1, 'exact', 'Direct match to BLS Management Analysts (13-1111).', 'Recruiting runs through campus channels at target undergrad and MBA programs into ''Business Analyst'' or ''Associate'' seats at firms ranging from MBB to Big Four advisory arms; the gate is a case interview (30-40 practice cases is typical prep) plus a strong GPA/resume screen, and cold networking with alumni matters most for candidates outside target schools trying to get a first look.', 'Business Analyst (2 yrs, many leave here for an MBA) -> Associate/Consultant -> Engagement Manager/Project Leader (~4-6 yrs) -> Principal/Associate Partner (~7-9 yrs) -> Partner (~10-12+ yrs) -> most consultants exit within 2-4 years into industry, PE, or startups rather than making partner.', ARRAY['Case interview practice (structuring, market sizing, mental math)', 'Excel/PowerPoint fluency', 'Informational-interview networking', 'Basic business frameworks (profitability, market entry)', 'GMAT/GPA if targeting MBA-required firms']::text[], 'People picture strategic genius work advising CEOs from day one; junior years are mostly building slide decks, running analyses senior staff assign, and scheduling calls, with heavy travel and 60-70 hour weeks the norm rather than the exception.', 'Multiple case interview rounds test live structuring of an ambiguous business problem, quantitative reasoning under time pressure, and business intuition, paired with a fit interview on leadership/teamwork stories: interviewers are watching your reasoning process out loud, not just your final answer.'),
  ('Strategy Consultant', 'Advises company leadership on major strategic decisions: market entry, growth, competitive positioning.', 145000, 10, 'MBA (or exceptional Bachelor''s)', ARRAY['Strategic frameworks', 'Executive communication', 'Market analysis', 'Structured problem-solving']::text[], '{"quadrant_a":0.3,"quadrant_b":0.15,"quadrant_c":0.5,"quadrant_d":0.85,"pace_preference":0.65,"risk_tolerance":0.55}'::jsonb, '2025-09-01'::date, '13-1111', 8.8, 101190, 98.1, 'close', 'Matches BLS Management Analysts (13-1111); BLS does not separate strategy from general management consulting.', 'Two real doors: direct MBA hire into a post-MBA Associate role at a strategy firm (McKinsey, Bain, BCG, or boutiques like LEK/OW), or promotion from an undergrad Business Analyst seat after 2-3 years plus a sponsored MBA; both paths gate on case interviews, and without an MBA you need standout undergrad credentials plus 2-3 years of banking or consulting experience to be competitive for direct entry.', 'Post-MBA Associate -> Engagement Manager/Project Leader (2-3 yrs) -> Principal (3-4 yrs) -> Partner/Director (10+ yrs total), the jump to Partner is the real bottleneck and depends heavily on your own client relationships and sold work, not just tenure.', ARRAY['Case interview frameworks (market entry, growth, profitability)', 'Executive-level written and verbal communication', 'Market/competitive analysis', 'MBA admissions prep if pursuing that route', 'Structured problem decomposition']::text[], 'People imagine strategy consultants deliver bold, original ideas that change a company''s direction; most engagements actually gather data and build a rigorous case for a direction leadership already leans toward, and the real skill being sold is structured analysis and stakeholder consensus-building, not raw creative insight.', 'Case interviews (market entry, growth strategy, competitive response) are scored on structuring, quantitative reasoning, and business judgment across multiple rounds, alongside a personal experience interview probing leadership under ambiguity: the case is a simulation of client work, not a puzzle with one right answer.'),
  ('Economic / Policy Consultant', 'Applies economic analysis to advise governments, corporations, or law firms on policy and litigation matters.', 118000, 8, 'Master''s degree', ARRAY['Econometrics', 'Policy analysis', 'Report writing', 'Client communication']::text[], '{"quadrant_a":0.88,"quadrant_b":0.3,"quadrant_c":0.45,"quadrant_d":0.25,"pace_preference":0.4,"risk_tolerance":0.25}'::jsonb, '2025-09-01'::date, '19-3011', 1.2, 115440, 0.9, 'close', 'Matches BLS Economists (19-3011), which covers applied economic analysis for policy/litigation clients.', 'Firms like Cornerstone Research, Analysis Group, NERA, and Compass Lexecon recruit Analysts directly from economics/quantitative undergrad and Master''s programs through on-campus recruiting; strong grades in econometrics and statistics courses are screened closely, and a pre-doctoral research assistant year with an academic economist is a common, well-regarded credential for competitive candidates.', 'Analyst -> Senior Analyst/Associate (2-3 yrs, a common exit point for an economics PhD or MBA) -> Manager/Senior Associate -> Principal/Vice President -> Partner/Managing Director, the track splits between litigation-support work (supporting testifying experts) and, for some, eventually becoming a testifying expert themselves after a PhD.', ARRAY['Econometrics and statistical inference fundamentals', 'STATA, R, or Python for regression analysis', 'Technical/legal writing under deadline', 'Reading and summarizing academic economics papers', 'GRE prep if considering a later econ PhD']::text[], 'People picture abstract policy debate or big-picture economic theorizing; day-to-day work is dominated by painstaking data cleaning and regression analysis supporting a testifying expert''s litigation report, produced under the same unforgiving, defensible-under-cross-examination scrutiny as an audit.', 'Technical screens test econometrics and statistics fundamentals (interpreting a regression, explaining causal inference concepts) plus a writing sample or case exercise; fit interviews probe attention to detail and comfort working backward from a legal deadline rather than an open-ended research timeline.'),
  ('Innovation Consultant', 'Helps established companies invent and prototype new business models and products from scratch.', 128000, 11, 'Bachelor''s/MBA', ARRAY['Design thinking', 'Ideation facilitation', 'Prototyping', 'Ambiguity tolerance']::text[], '{"quadrant_a":0.25,"quadrant_b":0.1,"quadrant_c":0.48,"quadrant_d":0.93,"pace_preference":0.6,"risk_tolerance":0.7}'::jsonb, '2025-09-01'::date, '13-1111', 8.8, 101190, 98.1, 'approximate', 'No dedicated innovation-consulting code; mapped to the general Management Analysts category (13-1111).', 'Entry doors vary by seat: design-focused hires (portfolio matters as much as resume) join firms like IDEO or frog as design researchers, while MBA hires join through more traditional recruiting into innovation practices at strategy firms; cross-disciplinary project teams mean designers, engineers, and business generalists all recruit differently for the same team.', 'Design Researcher/Associate Consultant -> Senior Consultant/Design Lead -> Engagement or Studio Lead -> Principal/Partner or Innovation Practice Head, many eventually move client-side into a corporate innovation lab or leave to found their own studio.', ARRAY['Design thinking facilitation technique', 'Rapid prototyping (paper, digital, or physical)', 'Workshop/brainstorm facilitation', 'A portfolio of applied, not just conceptual, projects', 'Presenting unproven ideas persuasively to skeptical executives']::text[], 'People picture unconstrained creative brainstorming; the real work is mostly herding risk-averse corporate stakeholders toward a decision and defending a prototype against ''but how do we scale this'' pushback: the large majority of concepts generated never ship.', 'A portfolio/case walkthrough of a past ideation-to-prototype project is central, paired with a live facilitation or brainstorming exercise that tests how you structure ambiguity and build on others'' ideas in real time, not just your personal creative flair.'),
  ('Chief Executive Officer', 'Sets organizational strategy and culture, resolves cross-functional conflict, and represents the company to stakeholders.', 206680, 6, 'Bachelor''s/MBA (varies widely)', ARRAY['Strategic vision', 'People leadership', 'Conflict mediation', 'Communication']::text[], '{"quadrant_a":0.25,"quadrant_b":0.2,"quadrant_c":0.88,"quadrant_d":0.5,"pace_preference":0.6,"risk_tolerance":0.6}'::jsonb, '2025-09-01'::date, '11-1011', 4.3, 206420, 22.2, 'exact', 'Direct match to BLS Chief Executives (11-1011).', 'There''s no entry-level door: CEO is reached after 15-25+ years of progressively larger P&L or leadership roles, most commonly through a COO, division president, or CFO seat, or by founding/co-founding a company; internal board-groomed succession and external executive search (Spencer Stuart, Korn Ferry, Russell Reynolds) are the two dominant paths for established companies.', 'Individual contributor -> manager -> director -> VP -> SVP/division president -> COO or other C-suite role -> CEO, public-company CEOs average around two decades of career progression, usually across two or three companies, with board and P&L visibility as the real gatekeeper at each step.', ARRAY['Direct P&L ownership experience at any scale', 'Board and investor communication', 'Decisive judgment with incomplete information', 'Public speaking and media presence', 'A visible professional network (board seats, industry groups)']::text[], 'People imagine CEOs run daily operations personally; in practice most time goes to external stakeholders (board, investors, press) and a small number of high-leverage people and culture decisions, with operational detail delegated: the job is often described by CEOs themselves as the loneliest one in the building.', 'Public-company CEO selection is really a board vetting process: decades of reference checks, working sessions with the board on vision and strategy, and often a listening tour with key executives and investors. The real test is whether the board trusts your judgment in a crisis they haven''t yet imagined, not a single interview performance.'),
  ('Chief Operating Officer', 'Owns the operational execution of a company''s strategy, keeping teams and processes running at scale.', 195000, 6, 'Bachelor''s/MBA + extensive experience', ARRAY['Operations leadership', 'Cross-functional coordination', 'Process design', 'Executive communication']::text[], '{"quadrant_a":0.3,"quadrant_b":0.85,"quadrant_c":0.5,"quadrant_d":0.2,"pace_preference":0.55,"risk_tolerance":0.4}'::jsonb, '2025-09-01'::date, '11-1021', 4.4, 102950, 308.7, 'close', 'Mapped to BLS General and Operations Managers (11-1021), the conventional crosswalk for COO roles (vs. Chief Executives, reserved for top-of-org policy-setting roles).', 'Reached through years of operational leadership (VP Operations, GM, or division head) that prove you can run complex, multi-function execution at scale; some COOs pivot from finance or consulting backgrounds, but the credential that matters most is a track record of hitting operational targets across at least one full P&L cycle, not a specific prior title.', 'Operations Manager -> Director of Operations -> VP Operations/General Manager -> COO, many COOs are hired directly from another company''s SVP/GM seat rather than promoted internally, and the path is measured by scale of P&L or headcount owned rather than a fixed title sequence.', ARRAY['Cross-functional project management experience', 'Financial/P&L literacy', 'Process design (Lean/Six Sigma exposure)', 'Direct people-management of a real team, even a small one, early on', 'Comfort being accountable when execution slips']::text[], 'People think COO means doing the fun strategy work as a second CEO; the actual job is unglamorous: fixing whatever part of the business is broken, sitting in the meetings the CEO avoids, and absorbing accountability when execution fails.', 'Executive interviews center on walking through specific operational turnarounds or scaling challenges you''ve owned, with real revenue/cost/headcount numbers expected, plus reference checks with former direct reports and a working session testing whether your operating style complements the CEO''s.'),
  ('Human Resources / People Director', 'Leads hiring strategy, employee relations, and organizational culture across a growing company.', 145000, 6, 'Bachelor''s degree', ARRAY['Conflict resolution', 'Empathetic listening', 'Policy design', 'Negotiation']::text[], '{"quadrant_a":0.15,"quadrant_b":0.48,"quadrant_c":0.9,"quadrant_d":0.25,"pace_preference":0.45,"risk_tolerance":0.25}'::jsonb, '2025-09-01'::date, '11-3121', 5, 140030, 17.9, 'exact', 'Direct match to BLS Human Resources Managers (11-3121).', 'The standard path is HR generalist or HR Business Partner roles out of undergrad, often via a large company''s rotational leadership program, building up through progressively senior HRBP or center-of-excellence (comp, talent, L&D) roles; SHRM-CP or PHR certification helps early credibility but internal mobility from recruiting or operations into HR is also common.', 'HR Coordinator/Generalist -> HR Business Partner -> Senior HRBP -> HR Manager -> Director of HR/People -> VP People -> CHRO, the path often forks between staying a generalist HRBP close to business leaders or specializing before converging back into a director-level generalist role.', ARRAY['Employment law fundamentals', 'Conflict mediation practice', 'Comp/attrition data literacy', 'Executive presence and coaching ability', 'SHRM-CP or HRCI certification']::text[], 'People think HR is mostly paperwork or the ''fun events team''; the real job is constant high-stakes conflict resolution, such as terminations, harassment investigations, and executive disputes, where you''re often the person legally and ethically on the hook when a people decision goes wrong.', 'Behavioral interviews probe specific conflict-resolution and difficult-conversation scenarios (walk me through a termination or investigation you handled) and judgment questions on when to escalate or document: legal and compliance awareness is assessed throughout, not in a separate round.'),
  ('Sales Director', 'Leads a company''s revenue-generating sales team, resolving client and internal team conflict.', 140000, 5, 'Bachelor''s degree', ARRAY['Relationship building', 'Negotiation', 'Team leadership', 'Persuasion']::text[], '{"quadrant_a":0.2,"quadrant_b":0.25,"quadrant_c":0.88,"quadrant_d":0.45,"pace_preference":0.65,"risk_tolerance":0.5}'::jsonb, '2025-09-01'::date, '11-2022', 4.7, 138060, 49, 'close', 'Matches BLS Sales Managers (11-2022).', 'Almost always promoted from individual-contributor sales (Account Executive) after repeatedly hitting quota over several years, then a Sales Manager role leading a small team, before Director; lateral hires from a competitor''s sales leadership happen too, but a director with no personal quota-carrying track record is rare and viewed skeptically.', 'SDR/BDR -> Account Executive -> Senior AE -> Sales Manager (first people-leadership step, ~3-5 yrs in) -> Director of Sales -> VP Sales -> CRO, your quota attainment history follows you at every step, and directors without specific number-beating years struggle in external interviews.', ARRAY['Full sales-cycle experience as an individual contributor first', 'Forecasting and pipeline math', 'CRM fluency (Salesforce)', 'Coaching and 1:1 skills', 'Comfort being measured on a number every quarter']::text[], 'People think sales leadership means never selling again; directors stay deeply in deals: forecast calls, ride-alongs, exec sponsorship on big accounts, and are judged just as harshly on the team''s number as an individual contributor is on their own.', 'Interviews include presenting a mock sales plan or pipeline review, walking through coaching an underperforming rep, and a track-record deep dive with specific quota numbers and deal examples: vague ''people person'' answers get filtered out quickly.'),
  ('Product Marketing Manager', 'Positions and launches products, translating what''s built into a story customers actually want.', 128000, 8, 'Bachelor''s degree', ARRAY['Positioning strategy', 'Cross-functional collaboration', 'Storytelling', 'Market research']::text[], '{"quadrant_a":0.3,"quadrant_b":0.2,"quadrant_c":0.5,"quadrant_d":0.85,"pace_preference":0.55,"risk_tolerance":0.5}'::jsonb, '2025-09-01'::date, '11-2021', 6.6, 161030, 34.3, 'close', 'Matches BLS Marketing Managers (11-2021); product marketing isn''t broken out separately.', 'Common entry points are an MBA internship converting to a full-time PMM role, an internal move from sales, customer success, or consulting bringing customer-facing fluency, or a marketing generalist role at a smaller company that included positioning work; a portfolio of launch narratives and messaging documents matters more in interviews than any specific degree.', 'Associate PMM -> PMM -> Senior PMM -> Group PMM/Lead -> Director of Product Marketing -> VP Product Marketing, the ladder forks between staying close to specific products as a deep individual contributor or managing a PMM team across a full portfolio.', ARRAY['Positioning and messaging writing practice', 'Cross-functional influence without direct authority', 'Basic competitive/market research', 'Presenting to sales teams', 'Customer interview technique']::text[], 'People think it''s ''marketing for products'' in a generic sense; the actual job is the translation layer between engineering''s feature list and a story a sales rep or customer will care about, and most of the work is influence and alignment meetings rather than creative copywriting.', 'A common exercise is a live or take-home positioning challenge (position this feature for this customer segment) plus cross-functional scenario questions (sales wants X, engineering says Y: what do you do), testing influence-without-authority directly.'),
  ('Brand Manager', 'Owns the strategy and identity of a product or company brand, balancing creative vision with market data.', 118000, 6, 'Bachelor''s degree', ARRAY['Brand strategy', 'Creative direction', 'Market analysis', 'Cross-team leadership']::text[], '{"quadrant_a":0.25,"quadrant_b":0.2,"quadrant_c":0.48,"quadrant_d":0.85,"pace_preference":0.5,"risk_tolerance":0.5}'::jsonb, '2025-09-01'::date, '11-2021', 6.6, 161030, 34.3, 'close', 'Matches BLS Marketing Managers (11-2021); brand management isn''t broken out separately.', 'The classic door is a CPG brand-management associate program (P&G, Unilever, PepsiCo, Kraft-Heinz) recruiting directly from undergrad or MBA through structured, highly competitive rotational programs; these firms train brand managers rigorously and other companies hire away their alumni, so ''trained at P&G'' functions as its own credential.', 'Assistant Brand Manager -> Brand Manager -> Senior Brand Manager -> Marketing Director/Group Brand Director -> VP Marketing/CMO, CPG brand management is explicitly designed as a general-management feeder, so many brand managers eventually move into broader P&L or GM roles rather than staying in marketing.', ARRAY['Quantitative marketing analysis (share, pricing, promo ROI)', 'P&L literacy', 'Writing crisp creative briefs', 'Cross-functional coordination with sales/R&D/finance', 'Case-competition-style problem structuring']::text[], 'People think brand management is mostly picking ad concepts and attending photoshoots; it''s actually closer to running a small P&L, where pricing, forecasting, trade spend, and defending budget in finance reviews take up more time than creative work.', 'CPG brand programs run structured case interviews (analyze this brand''s declining share, what would you do) alongside ''led without authority'' behavioral rounds: quantitative rigor applied to a marketing lens is explicitly tested, not just creative instinct.'),
  ('Creative Director (Advertising)', 'Leads the creative vision for ad campaigns and brand work, making bold calls with no formula for what will land.', 145000, 6, 'Bachelor''s degree', ARRAY['Creative vision', 'Team leadership', 'Client presentation', 'Original thinking']::text[], '{"quadrant_a":0.15,"quadrant_b":0.1,"quadrant_c":0.5,"quadrant_d":0.95,"pace_preference":0.55,"risk_tolerance":0.7}'::jsonb, '2025-09-01'::date, '27-1011', 4.2, 111040, 12.3, 'close', 'Matches BLS Art Directors (27-1011), the standard crosswalk for advertising creative-direction roles.', 'The near-universal path starts as a junior copywriter or art director hired into an agency creative team (usually hired in pairs), building a portfolio (''book'') of concepts across real or spec briefs; a strong book, not a specific degree, is the entry credential, and portfolio schools (VCU Brandcenter, Miami Ad School, Creative Circus) exist specifically to build that book.', 'Junior Copywriter/Art Director -> Copywriter/Art Director -> Senior CW/AD (usually paired as a creative team) -> Associate Creative Director -> Creative Director -> Executive/Group Creative Director -> Chief Creative Officer, creative teams are almost always promoted and evaluated as writer-art-director pairs, not individually.', ARRAY['Building a portfolio/book of original concepts (spec ads are acceptable early on)', 'Presenting and defending creative ideas out loud to skeptics', 'Collaborating tightly with a creative partner', 'Understanding brand strategy and briefs', 'Craft recognized by industry awards (Cannes Lions, One Show) as reputation currency']::text[], 'People picture unconstrained artistic freedom; the job is mostly negotiation: defending a concept against client fear, legal review, and budget cuts, and a good creative director is judged as much on political survival skill as on raw creativity.', 'The portfolio review is the interview: you present and defend your book''s thinking, not just the visuals, followed by a scenario question (the client hates the concept two days before the shoot, what do you do) testing composure and problem-solving under real constraints.'),
  ('Chief Marketing Officer', 'Sets a company''s entire brand and growth strategy at the executive level, betting on unproven creative and market directions.', 225000, 7, 'Bachelor''s/MBA + extensive experience', ARRAY['Brand strategy', 'Executive leadership', 'Market intuition', 'Risk-taking']::text[], '{"quadrant_a":0.25,"quadrant_b":0.15,"quadrant_c":0.5,"quadrant_d":0.92,"pace_preference":0.55,"risk_tolerance":0.7}'::jsonb, '2025-09-01'::date, '11-2021', 6.6, 161030, 34.3, 'close', 'CMO is a listed example job title under BLS Marketing Managers (11-2021); no separate C-suite marketing code exists.', 'Reached after 15+ years climbing marketing leadership through Brand/Product Marketing Director and VP Marketing roles, or occasionally brought in from an agency or consulting leadership background; executive search firms recruit CMOs much like CEOs, so network visibility and a portfolio of demonstrable revenue or brand impact matter more than any single credential.', 'Marketing Manager -> Senior Manager/Director -> VP Marketing -> SVP Marketing -> CMO, CMO tenure is notoriously short (historically under four years on average), so many CMOs move company to company more often than up within one.', ARRAY['P&L/budget ownership experience', 'Board-level data storytelling', 'Brand strategy judgment', 'Managing specialist teams (performance marketing, brand, PMM, comms) you may not have personally done', 'Comfort being blamed first when growth slows']::text[], 'People think CMO is the ''creative'' seat in the C-suite; in practice it''s one of the most quantitatively scrutinized roles in the building, with CAC/LTV, pipeline contribution, and marketing ROI dashboards dominating board conversations far more than campaign concepts.', 'Executive interviews focus on a portfolio of quantifiable outcomes you''ve driven, a working session presenting a point of view on the company''s specific growth challenge, and reference checks on your ability to partner with sales and product leadership without territorial conflict.'),
  ('Emerging Technology / Innovation Analyst', 'Scouts and evaluates frontier technologies for a company to bet on, with no established playbook to follow.', 118000, 14, 'Bachelor''s degree', ARRAY['Technology scouting', 'Trend analysis', 'Strategic synthesis', 'Comfort with ambiguity']::text[], '{"quadrant_a":0.45,"quadrant_b":0.2,"quadrant_c":0.25,"quadrant_d":0.9,"pace_preference":0.55,"risk_tolerance":0.75}'::jsonb, '2025-09-01'::date, '13-1111', 8.8, 101190, 98.1, 'approximate', 'No dedicated tech-scouting/innovation-analyst code; mapped to the general Management Analysts category (13-1111).', 'Typically an internal move from a strategy, R&D, or corporate development role after 2-4 years, or a direct hire with a technical (engineering/science) background plus an MBA into a corporate venture arm or innovation office; comfort reading technical papers and patents and translating them for business leaders is the real screening filter, not a specific degree.', 'Analyst -> Senior Analyst/Innovation Manager -> Director of Emerging Tech/Innovation -> Head of Corporate Venturing or Chief Innovation Officer, many eventually move into corporate venture capital, investing the company''s own money in startups, as a natural next step.', ARRAY['Technology trend research (papers, patents, startup funding data)', 'Building adoption/investment theses under incomplete information', 'Translating technical concepts for non-technical executives', 'Basic startup/VC literacy', 'Comfort being publicly wrong (most bets don''t pan out)']::text[], 'People picture constant futuristic exploration; the actual job is mostly convincing risk-averse internal stakeholders to fund a pilot for something unproven, and most recommended technologies get shelved regardless of merit due to internal politics or budget cycles.', 'Interviews often include presenting a point of view on a specific emerging technology''s business relevance, plus questions on how you''d prioritize scouting across dozens of possible technologies with limited time and budget.'),
  ('Biotech Startup Founder', 'Builds a biotech company from scratch, betting years of runway on an unproven scientific thesis.', 0, 0, 'Varies, often Ph.D. + business acumen', ARRAY['Scientific judgment', 'Fundraising', 'Resourcefulness', 'Risk tolerance']::text[], '{"quadrant_a":0.48,"quadrant_b":0.12,"quadrant_c":0.3,"quadrant_d":0.93,"pace_preference":0.65,"risk_tolerance":0.95}'::jsonb, '2025-09-01'::date, null, null, null, null, 'no_match', 'BLS has no startup-founder category. Founding a company isn''t an occupation BLS tracks (no employer, no wage data); Chief Executives (11-1011) is the closest formal-org proxy but doesn''t meaningfully represent pre-revenue founder economics, so this is left unmatched rather than forced.', 'Nearly all biotech founders come from a research lab, often the PhD or postdoc who discovered the core IP, or from a venture-creation model where a firm like Flagship Pioneering or Third Rock recruits a scientific founder and installs an experienced business co-founder/CEO alongside them; university tech-transfer offices and SBIR/STTR grants are common first real-world funding sources before institutional VC.', 'Postdoc/scientist with an idea -> founding scientist paired with a business co-founder -> seed/Series A funded company, with the founder stepping back from bench work into strategy and fundraising -> as the company matures, many scientist-founders move into a CSO role while a professional CEO is brought in, or stay CEO if they''ve built that muscle.', ARRAY['Deep domain scientific credibility (PhD/publication record) built before founding', 'Grant-writing and non-dilutive funding experience', 'Basic fundraising and pitch construction', 'Translating scientific risk into a business narrative investors can underwrite', 'Resilience for a 10+ year horizon with binary clinical/regulatory outcomes']::text[], 'People picture a scrappy garage startup like consumer tech; biotech founding is far more capital-intensive and slow, with years to any revenue and clinical trials measured in years not sprints, and a scientist-founder''s time shifts almost entirely away from the lab into fundraising, hiring, and regulatory strategy within the first year or two.', 'There''s no traditional hiring interview: the real test is pitching to venture investors, articulating why your science, team, and IP position can survive years of R&D risk, and vetting a business co-founder/CEO for genuine trust and complementary skills, since a mismatched founding team is one of the top reasons biotech startups fail.'),
  ('Venture Studio Partner', 'Builds and launches multiple new companies in parallel from within a venture studio, with no fixed formula for any of them.', 165000, 9, 'Bachelor''s/MBA', ARRAY['Idea generation', 'Rapid prototyping', 'Fundraising', 'Pattern recognition']::text[], '{"quadrant_a":0.25,"quadrant_b":0.1,"quadrant_c":0.48,"quadrant_d":0.95,"pace_preference":0.65,"risk_tolerance":0.9}'::jsonb, '2025-09-01'::date, '11-1011', 4.3, 206420, 22.2, 'approximate', 'No BLS category for venture-studio partners (a hybrid founder/operator role); loosely mapped to Chief Executives (11-1011) as the closest formal-org proxy, but this is a genuinely weak fit, flagged for review.', 'Almost never an entry-level hire: studios recruit partners from operating backgrounds (founders/execs who''ve scaled something) or from venture capital, and joining as an ''entrepreneur in residence'' is a common on-ramp that can convert into a partner role or into becoming the founding CEO of a studio-built company.', 'Operator/founder background -> Entrepreneur in Residence or Venture Partner (proving out idea generation and execution across a few projects) -> Partner (owns a portfolio of studio companies simultaneously) -> Managing Partner/General Partner running the studio''s overall strategy and fundraising.', ARRAY['A personal track record of building something 0-to-1 (even a failed startup counts)', 'Rapid prototyping and customer validation technique', 'Fundraising fluency (studios raise their own fund, and each company raises separately)', 'Pattern recognition across multiple business models at once', 'Ability to recruit strong founding CEOs to run companies you conceived']::text[], 'People think it''s ''start a bunch of startups with none of the risk''; the actual job juggles several simultaneous 0-to-1 efforts, most of which get killed within months, and the hardest part is emotionally detaching from ideas fast and recruiting outside CEOs to take over the ones that work.', 'This isn''t a standard job interview but a track-record and reference-heavy vetting process: partners assess your prior building experience, how you reason through a business model live via a real-time idea-generation exercise, and whether founders or investors from your past ventures vouch for you.'),
  ('Chief Innovation Officer', 'Leads a company''s search for new growth, such as new products, markets, or business models, at the executive level.', 210000, 8, 'Bachelor''s/MBA + extensive experience', ARRAY['Strategic vision', 'Organizational change', 'Ideation leadership', 'Risk assessment']::text[], '{"quadrant_a":0.25,"quadrant_b":0.2,"quadrant_c":0.5,"quadrant_d":0.9,"pace_preference":0.55,"risk_tolerance":0.75}'::jsonb, '2025-09-01'::date, '11-1011', 4.3, 206420, 22.2, 'approximate', 'No dedicated "chief innovation officer" code; loosely mapped to Chief Executives (11-1011) as the general C-suite proxy, flagged for review.', 'Reached after a long track record in R&D leadership, corporate strategy, or as a serial intrapreneur who''s shipped new products or business lines inside a large company; unlike CEO or COO, there''s no single expected prior title: companies hire for this role from strategy consulting, product leadership, or internal R&D depending on what ''innovation'' means for that specific business.', 'Product/R&D lead or Strategy Director -> Head of Innovation/New Ventures -> VP Innovation -> Chief Innovation Officer, many also come in laterally from running a corporate venture or incubation unit rather than climbing a single fixed ladder.', ARRAY['A demonstrated track record shipping at least one genuinely new product or business line', 'Organizational-change management (killing sacred cows, reallocating budget from legacy lines)', 'Executive storytelling to justify unproven bets to a board', 'Basic venture/startup literacy', 'Political navigation within a large organization']::text[], 'People think the role is about generating cool ideas; the real job is almost entirely organizational politics, securing budget and protection for risky bets against business units that see innovation spending as a threat to their own resources.', 'Executive interviews center on a portfolio of specific innovation initiatives you''ve shipped and their business outcomes, a working session on how you''d structure an innovation function for this specific company, and pointed questions on handling internal resistance from threatened business units.'),
  ('Marketing Manager', 'Develops brand and campaign strategy, balancing creative direction with data-driven decision-making.', 156580, 6, 'Bachelor''s degree', ARRAY['Campaign strategy', 'Data analysis', 'Creative direction', 'Cross-team leadership']::text[], '{"quadrant_a":0.3,"quadrant_b":0.2,"quadrant_c":0.48,"quadrant_d":0.85,"pace_preference":0.6,"risk_tolerance":0.5}'::jsonb, '2025-09-01'::date, '11-2021', 6.6, 161030, 34.3, 'exact', 'Direct match to BLS Marketing Managers (11-2021).', 'Typical entry is a marketing coordinator or specialist role out of undergrad, building 2-4 years of campaign execution experience before earning the ''manager'' title, or an internal promotion from a specialist function (content, demand gen, social); an MBA can accelerate the jump but demonstrated campaign results matter more than credentials.', 'Marketing Coordinator/Specialist -> Marketing Manager -> Senior Marketing Manager -> Director of Marketing -> VP Marketing/CMO, the path often specializes in one channel before generalizing back into a director role managing a full function.', ARRAY['Campaign execution experience in at least one channel (paid, content, email, social)', 'Basic analytics/attribution literacy', 'Budget management', 'Cross-functional briefing and writing', 'A portfolio of measurable campaign results']::text[], 'People think marketing managers spend their time being creative; day to day is dominated by campaign logistics, vendor/agency management, and defending budget with performance data, with ''big idea'' moments being rare relative to the operational grind.', 'Interviews typically include a campaign case study (here''s a budget and goal, build a plan) and a metrics-defense conversation walking through a campaign''s results, including one that underperformed: data fluency is weighted as heavily as creative instinct.'),
  ('Business Development Manager', 'Identifies and closes new partnerships and revenue opportunities under real market uncertainty.', 112000, 8, 'Bachelor''s degree', ARRAY['Relationship building', 'Negotiation', 'Market opportunity analysis', 'Persistence']::text[], '{"quadrant_a":0.2,"quadrant_b":0.25,"quadrant_c":0.85,"quadrant_d":0.48,"pace_preference":0.6,"risk_tolerance":0.6}'::jsonb, '2025-09-01'::date, '11-2022', 4.7, 138060, 49, 'approximate', 'No dedicated business-development code; mapped to Sales Managers (11-2022) as the closest revenue-function proxy.', 'Common entry paths are a sales or account management role that pivots into partnerships, or an analyst/consulting background hired directly into BD for its structured deal-evaluation skills; hiring weights relationship-building and negotiation examples heavily since the role is judged on deals closed, not calls made.', 'BD Associate/Analyst -> BD Manager -> Senior BD Manager -> Director of Business Development -> VP Partnerships/BD, many BD professionals eventually move into corporate development (M&A) or general management given the deal-structuring overlap.', ARRAY['Negotiation practice, even in low-stakes settings', 'Basic deal/contract literacy', 'Market and competitive research', 'Relationship-building and follow-through over long deal cycles', 'Comfort with deals that take months to close and often fall through']::text[], 'People think BD is glamorous ''make deals happen'' work; most of the job is slow relationship maintenance and internal alignment across legal, product, and finance before a deal ever becomes real, and most pursued partnerships never close.', 'Interviews often include a negotiation role-play and questions walking through a real deal you sourced and closed end-to-end, testing both persistence and judgment about which opportunities are actually worth pursuing.'),
  ('Operations Manager', 'Keeps a company''s day-to-day processes running efficiently, solving structural bottlenecks as they arise.', 100930, 6, 'Bachelor''s degree', ARRAY['Process optimization', 'Team coordination', 'Problem-solving', 'Data analysis']::text[], '{"quadrant_a":0.3,"quadrant_b":0.85,"quadrant_c":0.45,"quadrant_d":0.15,"pace_preference":0.55,"risk_tolerance":0.3}'::jsonb, '2025-09-01'::date, '11-1021', 4.4, 102950, 308.7, 'close', 'Matches BLS General and Operations Managers (11-1021).', 'Common entry is an operations analyst or associate role out of undergrad, often via a rotational program, or promotion from a frontline supervisor role after demonstrating process-improvement wins; Lean/Six Sigma Green Belt certification helps credibility, especially in manufacturing or logistics-heavy settings.', 'Operations Analyst/Coordinator -> Operations Manager -> Senior Operations Manager -> Director of Operations -> VP Operations/COO, progression is measured by the scale of process, team, and budget you''re accountable for rather than a fixed title timeline.', ARRAY['Process mapping and root-cause analysis (Lean/Six Sigma exposure)', 'Dashboard/KPI data literacy', 'Direct people-management of even a small team', 'Vendor and cross-team coordination', 'Comfort being the person blamed when something breaks']::text[], 'People think it''s mostly logistics and scheduling; the real job is constant firefighting and tradeoff-making under incomplete information: a smoothly running operation looks boring from outside precisely because of the invisible problem-solving happening underneath.', 'Interviews include a process case (here''s a bottleneck, walk through diagnosing and fixing it) and behavioral questions on handling a crisis or conflict between teams: structured problem-solving under time pressure is the core thing being tested.'),
  ('Logistics / Supply Chain Manager', 'Coordinates the structured flow of goods through a supply chain, optimizing for cost and reliability.', 98100, 18, 'Bachelor''s degree', ARRAY['Process optimization', 'Forecasting', 'Vendor coordination', 'Systems thinking']::text[], '{"quadrant_a":0.48,"quadrant_b":0.88,"quadrant_c":0.3,"quadrant_d":0.12,"pace_preference":0.55,"risk_tolerance":0.3}'::jsonb, '2025-09-01'::date, '11-3071', 6.1, 102010, 18.5, 'close', 'Matches BLS Transportation, Storage, and Distribution Managers (11-3071).', 'Common entry is a supply chain analyst role out of a business or industrial engineering undergrad, often through a large retailer, manufacturer, or 3PL''s rotational supply chain program; APICS/ASCM certification (CPIM or CSCP) is a recognized credential for mid-career advancement though not required for entry.', 'Supply Chain Analyst/Coordinator -> Supply Chain/Logistics Manager -> Senior Manager -> Director of Supply Chain -> VP Supply Chain/Chief Supply Chain Officer, progression tracks with network scope (single warehouse to global) more than fixed years.', ARRAY['Forecasting and demand-planning fundamentals', 'ERP/systems literacy (SAP, Oracle)', 'Vendor negotiation', 'Data analysis (Excel/SQL for inventory and logistics metrics)', 'Crisis-management practice, since disruptions are constant']::text[], 'People think it''s a steady, predictable planning job; the real work is dominated by constant disruption management, where a single port delay, weather event, or supplier failure cascades into daily firefighting that planning models never fully anticipate.', 'Interviews typically include a forecasting or network-design case balancing cost against service level under constraints, plus scenario questions on managing a supply disruption in real time, testing quantitative tradeoff reasoning under pressure.'),
  ('Executive Coach', 'Advises senior leaders on decision-making, communication, and organizational effectiveness through one-on-one work.', 120000, 9, 'Bachelor''s/Master''s degree + coaching certification', ARRAY['Active listening', 'Organizational psychology', 'Feedback delivery', 'Relationship building']::text[], '{"quadrant_a":0.2,"quadrant_b":0.25,"quadrant_c":0.93,"quadrant_d":0.4,"pace_preference":0.4,"risk_tolerance":0.35}'::jsonb, '2025-09-01'::date, '13-1151', 10.8, 65850, 43.9, 'approximate', 'No dedicated executive-coaching code; mapped to Training and Development Specialists (13-1151) as the closest people-development category, though 1:1 senior-leader coaching is more individualized than the org-wide programs BLS describes.', 'Almost always a second career: coaches typically spend 15-20+ years in senior corporate leadership or HR before transitioning, since credibility with C-suite clients depends heavily on having sat in a comparable seat; an ICF-accredited coaching certification is close to mandatory for corporate/HR-sponsored engagements, and first clients usually come through a former employer''s network, not cold marketing.', 'Senior operator/HR leader -> certified coach building a client base through referrals -> established independent practice or affiliation with a coaching firm (BetterUp, Marshall Goldsmith network) -> senior/master coach working with C-suite and board-level clients, often combined with speaking or writing to build a personal brand.', ARRAY['ICF-accredited coaching certification', 'Deep listening and questioning technique, distinct from advice-giving', 'Organizational psychology fundamentals', 'A referral network within corporate HR and executive circles', 'Your own prior leadership credibility to draw on']::text[], 'People think coaching is supportive conversation or cheerleading; the real skill is disciplined, structured questioning that gets a defensive executive to see their own blind spot without being told directly: advice-giving is what bad coaching looks like, and experienced clients reject it quickly.', 'There''s no single interview: coaches are vetted by HR sponsors and the executive client through a chemistry or trial session, where what''s really being assessed is whether you can hold a senior leader accountable without being sycophantic or confrontational.'),
  ('Private Wealth Relationship Director', 'Manages high-net-worth client relationships for a bank or wealth firm, blending finance expertise with deep trust-building.', 165000, 10, 'Bachelor''s degree', ARRAY['Relationship management', 'Financial advising', 'Trust-building', 'Discretion']::text[], '{"quadrant_a":0.48,"quadrant_b":0.3,"quadrant_c":0.9,"quadrant_d":0.2,"pace_preference":0.4,"risk_tolerance":0.35}'::jsonb, '2025-09-01'::date, '13-2052', 9.6, 102140, 24.1, 'close', 'Matches BLS Personal Financial Advisors (13-2052), which covers advising high-net-worth individuals.', 'Common entry is a few years in a bank''s wealth management analyst/associate or private banking training program after finance-adjacent undergrad, building technical credibility before being given client relationships; a Series 7/66 license and often a CFP are expected credentials, and lateral hires who bring a portable book of high-net-worth clients from a competitor are highly prized.', 'Wealth Management Analyst/Associate -> Relationship Associate/Associate Director -> Relationship Director/Senior Private Banker -> Market Executive/Managing Director, seniority is measured heavily by assets under management and client book size, not just tenure.', ARRAY['Financial planning and investment fundamentals', 'Series 7/66 licensing (and CFP track)', 'Discretion and long-horizon relationship-building', 'Comfort with high-stakes, emotionally charged conversations (inheritance, divorce, business sale)', 'A portable professional network in a specific affluent community or industry']::text[], 'People picture mostly sophisticated investment strategy work; the actual job is dominated by relationship maintenance and life-event management, such as a client''s business sale, estate planning, or a difficult heir, far more than picking investments, which a separate investment team often handles.', 'Interviews test technical planning knowledge through a client scenario involving tax or estate tradeoffs, alongside relationship-building fit, and lateral hires are evaluated heavily on the size and portability of their existing client book.'),
  ('Executive Recruiter', 'Identifies and persuades senior leadership candidates to join client companies, working entirely through relationships.', 115000, 8, 'Bachelor''s degree', ARRAY['Relationship building', 'Persuasion', 'Networking', 'Judgment of fit']::text[], '{"quadrant_a":0.15,"quadrant_b":0.25,"quadrant_c":0.92,"quadrant_d":0.45,"pace_preference":0.55,"risk_tolerance":0.5}'::jsonb, '2025-09-01'::date, '13-1071', 6.2, 72910, 81.8, 'close', 'Matches BLS Human Resources Specialists (13-1071), which includes recruiting; "executive recruiter" is a listed O*NET sample title.', 'Common entry paths are a research associate/analyst role at a search firm (Spencer Stuart, Korn Ferry, Russell Reynolds, Heidrick & Struggles) doing candidate sourcing and market mapping, or a lateral move from HR/talent acquisition or an industry role with a strong personal network; there''s no required credential, but the research associate seat is the standard training ground before being given your own client relationships.', 'Research Associate -> Associate/Junior Consultant -> Principal/Consultant (owns client relationships and searches) -> Partner -> Senior Partner/Managing Director, compensation and status track closely with the client relationships and search fees you personally generate, similar to a sales structure.', ARRAY['Building and maintaining a personal professional network', 'Cold outreach and persuasion technique', 'Judgment about candidate fit beyond the resume, including reference-checking skill', 'Discretion with sensitive information', 'Deep expertise in at least one industry sector']::text[], 'People think it''s just ''job matching'' or reading LinkedIn profiles; the real work is convincing successful, often-reluctant senior people to consider leaving a good job, then managing a months-long, emotionally fraught process with both the client company and the candidate at once.', 'Interviews test networking and persuasion ability directly, often via a role-play cold call or pitch, plus your ability to reason about candidate fit for a specific mandate: for senior hires, expect probing into your own network depth as a proxy for future billings.'),
  ('Chief of Staff', 'Operates as an executive''s right hand, translating leadership priorities into action across the whole organization.', 152000, 9, 'Bachelor''s/MBA', ARRAY['Cross-functional coordination', 'Executive communication', 'Prioritization', 'Discretion']::text[], '{"quadrant_a":0.3,"quadrant_b":0.5,"quadrant_c":0.85,"quadrant_d":0.25,"pace_preference":0.65,"risk_tolerance":0.4}'::jsonb, '2025-09-01'::date, '11-1021', 4.4, 102950, 308.7, 'approximate', 'No dedicated chief-of-staff code; loosely mapped to General and Operations Managers (11-1021), flagged for review since the COS role (executive support/coordination) differs meaningfully from general operations management.', 'Common entry paths are a few years in strategy consulting, banking, or a strategy/ops role inside the same company before being tapped directly by an executive who trusts your judgment; there''s no formal credentialing path: it''s almost always a hand-picked role based on a prior working relationship, not an open competitive hire.', 'Chief of Staff is often a 2-3 year rotational role rather than a ladder rung itself: many use it as a launchpad into a VP/GM operating role, a business unit leadership position, or founding their own company, leveraging the cross-functional exposure and executive trust built in the seat.', ARRAY['Cross-functional project management experience', 'Executive-level writing (briefing memos, board decks)', 'Discretion with highly sensitive information', 'Judgment on what to escalate versus handle yourself', 'An existing trusted relationship with a senior leader']::text[], 'People think it''s a glamorous ''shadow the CEO'' role; the actual job is often thankless: running the meetings nobody wants to run, delivering unpopular messages on the executive''s behalf, and absorbing whatever unowned work falls through organizational cracks.', 'Because it''s relationship-based, the real vetting is a working trial period or a series of conversations testing judgment on hypothetical scenarios (the CEO is needed in two places at once, what do you prioritize), chemistry with the specific executive matters more than a standardized rubric.'),
  ('Startup Founder / Entrepreneur', 'Builds a company from scratch under deep uncertainty, allocating scarce resources with no playbook to follow.', 0, 0, 'Varies widely, no formal requirement', ARRAY['Resourcefulness', 'Risk tolerance', 'Big-picture synthesis', 'Resilience']::text[], '{"quadrant_a":0.2,"quadrant_b":0.08,"quadrant_c":0.5,"quadrant_d":0.97,"pace_preference":0.7,"risk_tolerance":0.95}'::jsonb, '2025-09-01'::date, null, null, null, null, 'no_match', 'BLS has no startup-founder/entrepreneur occupation category: founding a company under uncertainty with no fixed employer or wage isn''t something the Employment Projections survey tracks. Left unmatched rather than forcing a weak proxy.', 'There''s no hiring gate: you start by building something, a side project or MVP, and either bootstrap with personal savings/revenue or raise a pre-seed/seed round from angels or an accelerator like Y Combinator or Techstars, which also provides credibility and a network; a track record of shipping something, even small, matters far more than pedigree for early fundraising.', 'Idea/side project -> MVP with early users -> pre-seed/seed funded or bootstrapped to revenue -> Series A once you have product-market signal -> scaling through subsequent rounds or reaching profitability/exit via acquisition or IPO, most founders'' companies don''t reach later stages, and shutting down or a small acquihire is the modal outcome.', ARRAY['Shipping a real MVP fast (learn to build or find a technical co-founder)', 'Basic sales and customer-discovery skills (talking to users before and after building)', 'Fundraising and pitch narrative construction', 'Financial literacy (runway, burn rate, cap tables)', 'Personal resilience and stress management for sustained uncertainty']::text[], 'People picture visionary strategy and pitching; the actual daily grind is repetitive execution, such as sales calls, customer support, debugging, and payroll, and the ''founder'' romance is a small fraction of hours versus unglamorous operational survival tasks.', 'There''s no hiring interview: the equivalent is the investor pitch meeting, which tests whether you can articulate a large market opportunity crisply, defend your traction under skeptical questioning, and demonstrate founder-market fit, plus early customer conversations testing whether someone will actually say yes to an unproven product.'),
  ('Venture Capitalist', 'Evaluates early-stage companies for investment under high uncertainty, betting on ambiguous, unproven ideas.', 150000, 8, 'Bachelor''s/MBA', ARRAY['Pattern recognition', 'Risk assessment', 'Networking', 'Big-picture thinking']::text[], '{"quadrant_a":0.3,"quadrant_b":0.12,"quadrant_c":0.5,"quadrant_d":0.88,"pace_preference":0.55,"risk_tolerance":0.85}'::jsonb, '2025-09-01'::date, '13-2051', 5.7, 101350, 25.1, 'close', 'Matches BLS Financial and Investment Analysts (13-2051), which covers evaluating investment opportunities; no VC-specific code exists.', 'Common entry doors are an analyst/associate program at a VC firm, often recruited from banking, consulting, or a notable startup operating role, or a scout arrangement where an operator makes introductions or small investments informally before being brought on; unlike most finance careers, there''s no fixed recruiting pipeline, and warm introductions from founders or existing VCs matter enormously since firms are small and headcount is scarce.', 'Analyst/Associate (sourcing deals, running diligence, no investment authority) -> Senior Associate/Principal (leads diligence, sits on boards as observer) -> Partner (makes investment decisions, sits on boards) -> General Partner/Managing Partner (raises the fund itself), the jump from Principal to Partner is the hardest step and usually requires a strong personal deal track record or network.', ARRAY['Genuine relationship-building with founders, starting before you need anything from them', 'Pattern recognition from studying many companies and markets', 'Financial modeling and cap table literacy', 'Judgment under extreme uncertainty, since a few outliers drive all returns', 'A specific area of deep expertise or network that gives you unique deal access']::text[], 'People picture picking winning companies through analytical brilliance; in reality, access to the best deals (being invited into a competitive round) matters as much as picking correctly, and most junior VCs spend the bulk of their time sourcing and being rejected far more than analyzing.', 'Interviews include a deal memo exercise, evaluating a real or hypothetical startup and making the investment case, plus deep questions about your personal network and sourcing edge: firms are explicitly testing whether you can get access to good deals, not just analyze them once they''re in front of you.'),
  ('Physicist', 'Conducts research into the fundamental laws governing matter and energy, often via experiment and modeling.', 155680, 7, 'Ph.D.', ARRAY['Mathematical modeling', 'Experimental design', 'Analytical reasoning', 'Research']::text[], '{"quadrant_a":0.97,"quadrant_b":0.25,"quadrant_c":0.08,"quadrant_d":0.42,"pace_preference":0.2,"risk_tolerance":0.25}'::jsonb, '2025-09-01'::date, '19-2012', 4, 166290, 1.7, 'exact', 'Direct match to BLS Physicists (19-2012).', 'The required path is a PhD (5-6 years) following a strong physics undergrad, since research-track physicist roles in academia, national labs, or industry R&D essentially all require a doctorate; undergraduate research experience and strong quantitative/programming skills are what get you into a competitive PhD program, which is the real first gate.', 'PhD student -> postdoctoral researcher (often 2 back-to-back postdocs, 4-6 years total) -> research scientist or tenure-track assistant professor (a very competitive step) -> associate/tenured professor or senior scientist at a national lab or industry lab, many physicists also pivot into quant finance, data science, or semiconductor/tech R&D at various points given the transferable quantitative skill set.', ARRAY['Advanced mathematics well beyond a standard major (real/complex analysis, linear algebra, differential equations)', 'Programming (Python, C++, or MATLAB for simulation and data analysis)', 'Undergraduate research experience, which is what makes a PhD application competitive', 'Scientific writing', 'Comfort with a long, delayed-gratification career timeline']::text[], 'People picture solitary genius theorizing at a chalkboard; most working physicists spend the bulk of their time writing code, running simulations, and doing painstaking data analysis, and career security is a real concern since permanent research positions are scarce relative to the number of PhDs produced.', 'Academic and research interviews center on a research talk presenting your work to the department and fielding tough technical questions, plus one-on-one meetings testing depth of technical knowledge and research vision; industry R&D roles add a technical problem-solving component closer to an engineering interview.'),
  ('Astrophysicist', 'Studies celestial bodies and the physics of the universe through observation, theory, and computation.', 148000, 8, 'Ph.D.', ARRAY['Mathematical modeling', 'Data analysis', 'Research methodology', 'Programming']::text[], '{"quadrant_a":0.96,"quadrant_b":0.25,"quadrant_c":0.08,"quadrant_d":0.45,"pace_preference":0.2,"risk_tolerance":0.3}'::jsonb, '2025-09-01'::date, '19-2011', 2.2, 132170, 0.1, 'close', 'O*NET lists "Astrophysicist" as a sample job title under BLS Astronomers (19-2011); no separate astrophysicist code exists.', 'Same PhD-gated path as physics generally, but through astronomy/astrophysics-specific graduate programs; undergraduate research at an observatory or with a research group, often via NSF REU summer programs, is the standard way to build the application and letters of recommendation needed for a competitive PhD program.', 'PhD student -> postdoctoral researcher, commonly 2-3 postdocs across different institutions in a notoriously itinerant 6-9 year stretch -> tenure-track faculty position or staff scientist at an observatory/institution (NASA centers, national observatories) -> tenured professor or senior staff scientist, this track has one of the tightest faculty-job bottlenecks in academic science, so many astrophysics PhDs move into data science, quant finance, or software given directly transferable computational skills.', ARRAY['Advanced math/physics coursework', 'Observational or computational astronomy research experience as an undergrad', 'Programming, especially Python, which is near-universal in the field now', 'Statistics for handling noisy telescope/survey data', 'Willingness to relocate repeatedly across postdoc positions']::text[], 'People imagine looking through telescopes; almost all modern astrophysics is computational: writing code to process massive datasets from telescopes and surveys, running simulations, and statistical inference. Direct telescope observing time is a small, competitively-awarded fraction of the job.', 'Faculty and postdoc interviews center on a research seminar presenting your work to the department followed by rigorous technical Q&A, plus individual meetings assessing research fit and independence; the entire process is really testing whether you can secure your own future grant funding, since that''s what sustains the position.'),
  ('University Professor', 'Conducts original research and teaches at the postsecondary level, balancing structured teaching with open-ended inquiry.', 84380, 6, 'Ph.D.', ARRAY['Research design', 'Subject expertise', 'Teaching', 'Academic writing']::text[], '{"quadrant_a":0.85,"quadrant_b":0.2,"quadrant_c":0.5,"quadrant_d":0.3,"pace_preference":0.25,"risk_tolerance":0.3}'::jsonb, '2025-09-01'::date, '25-1199', 1.8, 78490, 13.5, 'approximate', 'BLS breaks postsecondary teachers into dozens of subject-specific codes (Business Teachers, Computer Science Teachers, Physics Teachers, etc.) rather than one generic "professor" code; mapped to the catch-all Postsecondary Teachers, All Other (25-1199), which is not a true representative average, flagged for review.', 'Requires a PhD (5-7 years) plus, in most competitive fields, one or more postdoctoral positions before landing a tenure-track assistant professor role; the academic job market is brutally competitive and largely driven by your publication record and the strength of recommendation letters from your PhD advisor''s network, not just credentials on paper.', 'PhD student -> postdoc(s) -> Assistant Professor on a roughly six-year tenure clock -> tenure review, a high-stakes up-or-out decision -> Associate Professor (tenured) -> Full Professor -> some move into administration (Department Chair, Dean) later in their career.', ARRAY['Sustained research productivity and publishing in peer-reviewed venues starting in grad school', 'Grant-writing, increasingly essential for both getting hired and getting tenure in most fields', 'Teaching experience (TA-ing, guest lecturing) built up during the PhD', 'Conference presentation and networking within your subfield', 'Extreme patience for a career timeline that can run 10+ years before job security']::text[], 'People picture a comfortable life of teaching and reading; the tenure-track reality is an unrelenting publish-or-perish grind where research output, and grant dollars in many fields, matters far more for job security than teaching quality, and the academic job market has produced far more PhDs than available tenure-track positions for decades.', 'The campus ''flyout'' interview involves a research job talk presenting your work to the whole department and defending it under questioning, a teaching demonstration, and a full day of one-on-one meetings with faculty: search committees are explicitly assessing whether you''ll bring in grant funding and enhance the department''s research profile, not just whether you''re a good teacher.'),
  ('Environmental Scientist', 'Studies environmental conditions and impacts, often designing novel field studies under ambiguity.', 78980, 6, 'Bachelor''s/Master''s degree', ARRAY['Field research', 'Data analysis', 'Report writing', 'Regulatory knowledge']::text[], '{"quadrant_a":0.85,"quadrant_b":0.3,"quadrant_c":0.2,"quadrant_d":0.45,"pace_preference":0.3,"risk_tolerance":0.3}'::jsonb, '2025-09-01'::date, '19-2041', 4.4, 80060, 8.5, 'exact', 'Direct match to BLS Environmental Scientists and Specialists, Including Health (19-2041).', 'Entry-level roles are open to Bachelor''s degree holders, especially with field research experience or an internship at a consulting firm, government agency (EPA, state environmental agency), or research lab; a Master''s degree significantly widens options and is close to required for more analytical or regulatory-facing roles, and certifications like OSHA 40-hour HAZWOPER matter for fieldwork-heavy jobs.', 'Field Technician/Junior Scientist -> Environmental Scientist -> Senior Scientist/Project Manager -> Principal Scientist or Program Manager -> Director of Environmental Programs, many specialize in water quality, air quality, contaminated site remediation, or environmental impact review, and growth often means owning larger regulatory projects or client accounts rather than a fixed title ladder.', ARRAY['Field research/sampling methodology', 'Statistical data analysis (R or similar)', 'Regulatory framework knowledge (Clean Water Act, NEPA, state-specific regulations)', 'Technical report writing for regulators or clients', 'GIS software familiarity']::text[], 'People picture mostly outdoor fieldwork; the job is actually dominated by desk work: writing regulatory compliance reports, environmental impact statements, and permit applications, with fieldwork often a smaller, seasonal slice of total time.', 'Interviews test knowledge of relevant environmental regulations for the specific role, since a water utility and a consulting firm doing impact assessments ask very different questions, plus a technical writing sample and scenario questions on handling a client or regulator pushing back on your findings.'),
  ('Architect', 'Designs buildings balancing creative vision, client constraints, and structural feasibility under real ambiguity.', 93310, 4, 'Bachelor''s/Master''s degree + licensure', ARRAY['Spatial design', 'Creative problem-solving', 'Client communication', 'Technical drafting']::text[], '{"quadrant_a":0.45,"quadrant_b":0.25,"quadrant_c":0.3,"quadrant_d":0.85,"pace_preference":0.35,"risk_tolerance":0.45}'::jsonb, '2025-09-01'::date, '17-1011', 3.9, 96690, 7.8, 'exact', 'Direct match to BLS Architects, Except Landscape and Naval (17-1011).', 'Requires a professional degree (B.Arch or M.Arch, depending on undergrad path), then a multi-year Architectural Experience Program (AXP) of supervised work hours at a licensed firm, followed by passing the Architect Registration Examination (six divisions), licensure typically takes 3-5+ years after graduating even for a strong candidate, and unlicensed ''architectural designers'' often do the bulk of design work at firms in the meantime.', 'Intern Architect/Architectural Designer, unlicensed, doing drafting and documentation -> licensed Architect after passing the ARE -> Project Architect owning a project''s technical execution -> Senior Architect/Associate -> Associate Principal -> Principal/Partner owning client relationships and firm equity, many architects also specialize in healthcare, high-rise, or historic preservation as they advance.', ARRAY['CAD/BIM software fluency (Revit, AutoCAD) built during school', 'A portfolio demonstrating both design concept and technical detailing', 'Internship experience at a firm before or during the AXP hours requirement', 'Building codes and construction-method literacy', 'Client presentation skills']::text[], 'People picture mostly creative concept design, sketching bold new buildings; the actual day-to-day for most architects, especially early career, is technical construction documentation, code compliance checking, and coordinating with engineers and contractors: pure conceptual design is a small fraction of billable hours.', 'Firm interviews center on a portfolio review presenting your design process and technical detailing, not just final renderings, plus questions on construction administration experience; the ARE licensure exam itself functions as a second, ongoing test with the profession that many architects fail sections of on the first attempt.'),
  ('Urban Planner', 'Designs land-use and development plans for communities, balancing regulation with creative long-term vision.', 82160, 4, 'Master''s degree', ARRAY['Zoning/regulatory knowledge', 'Long-term visioning', 'Stakeholder communication', 'Data analysis']::text[], '{"quadrant_a":0.25,"quadrant_b":0.85,"quadrant_c":0.3,"quadrant_d":0.48,"pace_preference":0.3,"risk_tolerance":0.35}'::jsonb, '2025-09-01'::date, '19-3051', 3.4, 83720, 3.4, 'exact', 'Direct match to BLS Urban and Regional Planners (19-3051).', 'A Master''s in Urban Planning accredited by the Planning Accreditation Board is close to standard for professional planner roles, especially in the public sector, though some entry-level municipal roles accept a Bachelor''s with relevant coursework; internships with a city planning department or regional planning agency during grad school are the typical door into a first full-time role, and AICP certification after a few years of experience matters for advancement.', 'Planning Assistant/Associate Planner -> Planner II/Senior Planner -> Principal Planner -> Planning Manager -> Planning Director, many planners also move between public sector government roles and private consulting firms across their career, since both paths develop overlapping skills.', ARRAY['GIS software proficiency, close to non-negotiable now', 'Public speaking and public-meeting facilitation, a huge and underestimated part of the job', 'Zoning and land-use law literacy', 'Technical report and staff-report writing', 'Patience for slow, politically contentious processes']::text[], 'People picture designing beautiful, forward-thinking city visions; the actual job is dominated by navigating public hearings, community pushback, and political compromise, where a technically excellent plan regularly gets watered down or killed by neighborhood opposition or city council politics.', 'Public-sector interviews, often panel-style, test knowledge of zoning and land-use regulation plus scenario questions on handling a contentious public hearing or angry resident, since managing conflict in public meetings is as core to the job as the technical planning work itself.'),
  ('Diplomat / Foreign Service Officer', 'Represents national interests abroad, negotiates between parties, and manages sensitive interpersonal relationships.', 108000, 3, 'Bachelor''s/Master''s degree + Foreign Service exam', ARRAY['Negotiation', 'Cross-cultural communication', 'Conflict mediation', 'Political judgment']::text[], '{"quadrant_a":0.15,"quadrant_b":0.3,"quadrant_c":0.9,"quadrant_d":0.45,"pace_preference":0.4,"risk_tolerance":0.4}'::jsonb, '2025-09-01'::date, null, null, null, null, 'no_match', 'BLS''s Employment Projections detailed occupation list has no Foreign Service / diplomat category (federal Foreign Service positions sit outside the standard SOC occupational breakdown used in this table). No reasonable proxy exists among the 832 line items, so left unmatched.', 'Requires passing the Foreign Service Officer Test, then a Qualifications Evaluation Panel review of personal narrative essays, and finally the Foreign Service Oral Assessment, a full day of structured exercises: the whole process takes a year or more with a low pass rate at each stage, and there''s no networking shortcut around this formal, standardized process, though language proficiency and overseas or policy experience strengthen an application.', 'Entry-level Foreign Service Officer, with first tours typically consular or entry-level rotational assignments including at least one ''hardship'' post -> Mid-level Officer specializing in a ''cone'' (political, economic, consular, management, or public diplomacy) -> Senior Foreign Service (Counselor, then Minister-Counselor) -> Ambassador, a small number of career appointments since many ambassadorships go to political appointees instead, officers rotate to a new post, often a new country, every 2-3 years throughout their career.', ARRAY['Foreign language proficiency, tested and required, with harder/rarer languages more valuable', 'Foreign Service Officer Test preparation (job knowledge, English expression, situational judgment)', 'Study of U.S. foreign policy and current international affairs', 'Cross-cultural adaptability demonstrated through study abroad, Peace Corps, or overseas work', 'Formal writing practiced against the Oral Assessment''s specific rubric']::text[], 'People picture glamorous high-level diplomacy and international intrigue; entry-level tours are heavily consular work, processing visas and assisting citizens abroad, rather than policy negotiation, and officers have little control over where in the world they''re posted for years at a time.', 'The Foreign Service Oral Assessment is a full-day, highly structured group exercise plus a case management simulation and a structured interview scored against specific dimensions like leadership, communication, and judgment: one of the most standardized, rubric-driven ''interviews'' in any career field, explicitly designed to be resistant to charisma alone.'),
  ('Airline Pilot', 'Operates aircraft following strict procedural checklists and regulatory protocol; high responsibility, low error tolerance.', 219140, 5, 'Bachelor''s degree + flight certification', ARRAY['Procedural discipline', 'Situational awareness', 'Checklist execution', 'Composure under pressure']::text[], '{"quadrant_a":0.4,"quadrant_b":0.97,"quadrant_c":0.2,"quadrant_d":0.08,"pace_preference":0.6,"risk_tolerance":0.15}'::jsonb, '2025-09-01'::date, '53-2011', 3.9, 226600, 11.7, 'exact', 'Direct match to BLS Airline Pilots, Copilots, and Flight Engineers (53-2011).', 'Requires accumulating flight hours, typically 1,500 total for an Airline Transport Pilot certificate, through a collegiate aviation program, military flight training, or paying out-of-pocket for private/instrument/commercial ratings at a flight school, then building hours as a flight instructor or in a lower-paying flying job before a regional airline will hire you; regional airlines are the near-universal first airline job, not a major carrier directly.', 'Flight instructor/hour-building job -> Regional airline First Officer -> Regional airline Captain after building seniority -> Major/legacy airline First Officer, often flowing through from a regional partner -> Major airline Captain -> Check Airman/Training Captain roles for senior pilots, seniority, not merit review, governs pay, schedule, and upgrade timing at every airline, so time-in-seat matters enormously.', ARRAY['Flight hour accumulation, the real bottleneck: plan for the cost and time early', 'Instrument and multi-engine ratings', 'FAA written exam preparation', 'Simulator training performance', 'Discipline with checklists and standard operating procedures built from day one of training']::text[], 'People picture glamorous world travel and constant new experiences; the reality, especially during the regional airline years, involves rigid schedules, reserve/on-call duty, and a strict seniority system that dictates quality of life for years regardless of skill, with the least senior pilots getting the worst routes and least schedule control.', 'Airline interviews combine a technical/simulator evaluation testing checklist discipline, procedural knowledge, and crew resource management under a simulated failure, with a structured behavioral interview assessing judgment and teamwork: technical skill alone doesn''t pass, since airlines are explicitly screening for pilots who won''t deviate from procedure under pressure.'),
  ('Veterinarian', 'Diagnoses and treats animals, balancing clinical protocol with client (owner) communication.', 125510, 19, 'Doctorate (DVM)', ARRAY['Clinical diagnosis', 'Procedural skill', 'Client communication', 'Composure under pressure']::text[], '{"quadrant_a":0.3,"quadrant_b":0.85,"quadrant_c":0.48,"quadrant_d":0.12,"pace_preference":0.6,"risk_tolerance":0.25}'::jsonb, '2025-09-01'::date, '29-1131', 9.6, 125510, 3, 'exact', 'Direct match to BLS Veterinarians (29-1131).', 'Requires a Doctor of Veterinary Medicine degree, four years after a Bachelor''s with heavy science prerequisites; vet school admission is notoriously competitive, requiring extensive hands-on animal and clinical experience hours logged before applying, then passing the North American Veterinary Licensing Examination, many new vets also do a one-year rotating internship, especially those aiming for specialty practice.', 'Associate Veterinarian for the first several years at an established practice -> Senior Associate -> Practice Owner/Partner or Medical Director, since many vets buy into or start their own practice -> some pursue board certification in a specialty (surgery, cardiology, oncology) via a competitive residency, becoming specialists who take referred cases from general practice vets.', ARRAY['Extensive animal-handling and clinical hours before applying to vet school, a hard admissions requirement', 'Strong science coursework (organic chemistry, biology, physiology)', 'Client communication skills for translating diagnoses to worried, non-expert owners', 'Business/financial literacy if aiming toward practice ownership', 'Emotional resilience, since euthanasia and grieving owners are routine']::text[], 'People picture mostly playing with animals; the emotional weight of the job, including euthanasia decisions and angry owners over cost, combined with vet school debt that''s high relative to typical starting salary, make it a much harder career financially and emotionally than the ''loves animals'' stereotype suggests.', 'Vet school admissions interviews often use a multiple mini-interview format testing ethical reasoning and communication through scenario stations, not just academic knowledge; job interviews at practices focus on caseload comfort, client communication style, and cultural fit with the practice''s specific client base and pace.'),
  ('Electrician', 'Installs and repairs electrical systems following strict safety code and structured diagnostic procedure.', 63310, 11, 'Apprenticeship + license', ARRAY['Code compliance', 'Diagnostic troubleshooting', 'Manual skill', 'Safety protocol']::text[], '{"quadrant_a":0.45,"quadrant_b":0.88,"quadrant_c":0.2,"quadrant_d":0.12,"pace_preference":0.5,"risk_tolerance":0.2}'::jsonb, '2025-09-01'::date, '47-2111', 9.5, 62350, 81, 'exact', 'Direct match to BLS Electricians (47-2111).', 'The standard path is a registered apprenticeship through a union (IBEW/NECA) or a non-union contractor, typically 4-5 years combining paid on-the-job training with classroom instruction, after which you sit for a state journeyman electrician licensing exam; trade school or community college pre-apprenticeship programs help you get selected into a good apprenticeship but don''t replace the apprenticeship hours themselves.', 'Apprentice, 4-5 years with increasing pay each year -> Journeyman Electrician, licensed to work unsupervised -> Master Electrician after several more years plus a master''s exam, needed to pull permits and run your own business -> many master electricians start their own contracting business or move into an estimator, project manager, or electrical inspector role.', ARRAY['Basic math (algebra, geometry for conduit bending and load calculations)', 'Physical stamina and comfort in tight or high spaces', 'Getting into a registered apprenticeship early by applying directly to IBEW locals or contractors, since it''s competitive', 'Safety training (OSHA 10/30)', 'Reading blueprints and schematics']::text[], 'People underestimate how much code knowledge and troubleshooting logic the job requires; it''s not just physical wiring work, it''s diagnosing electrical problems methodically and knowing the National Electrical Code in enough depth to pass inspections, which requires real ongoing study.', 'Apprenticeship program admission involves an aptitude test covering math and mechanical reasoning plus an interview assessing reliability and physical readiness; once licensed, job interviews with contractors focus heavily on specific past project experience and whether you can be trusted to work safely and independently on a job site.'),
  ('Plumber', 'Diagnoses and repairs plumbing systems following code and structured troubleshooting steps.', 62970, 6, 'Apprenticeship + license', ARRAY['Diagnostic troubleshooting', 'Code compliance', 'Manual skill', 'Customer communication']::text[], '{"quadrant_a":0.42,"quadrant_b":0.85,"quadrant_c":0.28,"quadrant_d":0.12,"pace_preference":0.5,"risk_tolerance":0.2}'::jsonb, '2025-09-01'::date, '47-2152', 4.5, 62970, 44, 'close', 'Matches BLS Plumbers, Pipefitters, and Steamfitters (47-2152), which combines plumbers with two related trades.', 'Same apprenticeship-based structure as electrical work: typically 4-5 years through a union (UA) or non-union contractor apprenticeship combining paid on-the-job hours with classroom instruction, followed by a state journeyman licensing exam; a trade or vocational school program can help you get selected for a good apprenticeship slot but doesn''t substitute for the required apprenticeship hours.', 'Apprentice, 4-5 years -> Journeyman Plumber, licensed to work unsupervised -> Master Plumber after additional years plus an exam, required to pull permits and own a business -> many master plumbers start their own plumbing business or move into estimating or project management for a larger contractor.', ARRAY['Physical stamina for crawl spaces, heavy lifting, and uncomfortable positions', 'Basic math for pipe sizing and slope calculations', 'Getting into a registered apprenticeship early through union locals or direct contractor applications', 'Plumbing code knowledge', 'Customer communication, since many plumbers work directly in customers'' homes']::text[], 'People picture simple pipe-fitting; a lot of the real skill is diagnostic, figuring out where an unseen leak or blockage actually is before you can fix anything, plus increasingly understanding modern systems like tankless water heaters and complex venting that go well beyond traditional ''wrench work.''', 'Apprenticeship admission involves an aptitude test plus an interview on reliability and physical readiness; once licensed, contractor job interviews weight specific past troubleshooting experience and, especially for residential or service plumbers, customer-facing communication skills, since you''re often alone in someone''s home explaining an expensive problem.'),
  ('Firefighter', 'Responds to emergencies following strict operational protocol, with sequencing decisions made in seconds.', 57120, 4, 'High school + fire academy', ARRAY['Protocol adherence', 'Physical readiness', 'Rapid decision-making', 'Teamwork under pressure']::text[], '{"quadrant_a":0.2,"quadrant_b":0.92,"quadrant_c":0.45,"quadrant_d":0.15,"pace_preference":0.9,"risk_tolerance":0.5}'::jsonb, '2025-09-01'::date, '33-2011', 3.4, 59530, 27.1, 'exact', 'Direct match to BLS Firefighters (33-2011).', 'Requires passing a Civil Service written exam and a Candidate Physical Ability Test, then completing fire academy training, often several months and live-in for many departments, before being hired as a probationary firefighter; EMT certification, sometimes paramedic, is required or heavily preferred by most departments now since the majority of calls are medical, not fire, and competition for open positions in desirable departments can be intense with hundreds of applicants per opening.', 'Probationary Firefighter, one year probation -> Firefighter -> Driver/Engineer operating apparatus -> Lieutenant -> Captain -> Battalion Chief -> Assistant/Deputy Chief -> Fire Chief, promotions above firefighter typically require passing competitive written and oral promotional exams, not just tenure, and many career firefighters also become paramedics or specialize in hazmat, technical rescue, or arson investigation.', ARRAY['Physical fitness training well before applying, since the CPAT is a real physical bar', 'EMT certification, ideally before or during the hiring process', 'The civil service written exam, which study guides exist for and matter', 'CPR/basic medical knowledge', 'Comfort with a highly regimented, hierarchical team culture']::text[], 'People picture constant dramatic fire rescues; the large majority of calls for most departments are EMS/medical responses, not fires, and a lot of on-duty time is spent on equipment checks, physical training, and station chores between calls: the job is as much about disciplined routine as adrenaline.', 'The hiring process includes an oral board interview, a panel assessing judgment, teamwork, and communication through scenario questions, alongside the written and physical tests: departments are explicitly screening for whether you''ll follow protocol and work well within a rigid chain of command under stress, not just physical capability.'),
  ('Police Officer', 'Enforces law and responds to incidents following departmental protocol and legal procedure.', 74910, 3, 'High school/Associate degree + academy', ARRAY['Protocol adherence', 'Situational judgment', 'Conflict de-escalation', 'Report writing']::text[], '{"quadrant_a":0.2,"quadrant_b":0.88,"quadrant_c":0.48,"quadrant_d":0.12,"pace_preference":0.75,"risk_tolerance":0.45}'::jsonb, '2025-09-01'::date, '33-3051', 3.1, 76290, 53.7, 'exact', 'Direct match to BLS Police and Sheriff''s Patrol Officers (33-3051).', 'Requires passing a civil service written exam, physical fitness test, an extensive background investigation covering credit, criminal history, and past employment (sometimes a polygraph), a psychological evaluation, and an interview panel, then attending a police academy that''s often several months long and run by the hiring department or a regional academy; a college degree isn''t required by most departments though it helps for career advancement, but a clean background is an absolute, non-negotiable filter that disqualifies many applicants.', 'Police Academy recruit -> Probationary Officer, often paired with a Field Training Officer -> Patrol Officer -> Detective/Corporal, usually requiring a competitive exam or application -> Sergeant -> Lieutenant -> Captain -> Chief, promotions above patrol typically require passing written and oral promotional exams and are competitive, not automatic with tenure, and many officers also specialize in K9, SWAT, or the detective bureau as an alternate track from command promotion.', ARRAY['Physical fitness, since the academy and job have real physical standards', 'The civil service exam, for which practice materials exist and matter', 'A clean personal, legal, and financial background maintained well before applying', 'Report writing, a large and underrated part of the job since everything is documented', 'De-escalation and communication training']::text[], 'People picture constant high-action law enforcement; the actual daily reality for most patrol officers is dominated by routine calls, paperwork, and community interactions, with genuinely dangerous, high-stakes incidents being a small though real fraction of time, and the job''s public scrutiny and stress load is often heavier than the physical danger itself.', 'The oral board interview panel tests judgment through scenario questions, such as how you''d handle a domestic dispute or a use-of-force situation, and communication style, alongside the separate background investigation and psych evaluation: departments are explicitly screening for judgment and integrity as much as any tactical skill, since most academy tactical training happens after hiring.'),
  ('Chef / Executive Chef', 'Runs kitchen operations under nightly time pressure, balancing structured prep with creative menu development.', 58920, 6, 'Varies, often culinary school', ARRAY['Kitchen management', 'Creative menu design', 'Speed under pressure', 'Team leadership']::text[], '{"quadrant_a":0.15,"quadrant_b":0.85,"quadrant_c":0.3,"quadrant_d":0.48,"pace_preference":0.85,"risk_tolerance":0.45}'::jsonb, '2025-09-01'::date, '35-1011', 7.1, 60990, 24.4, 'exact', 'Direct match to BLS Chefs and Head Cooks (35-1011).', 'Two real paths: culinary school (CIA, Johnson & Wales, or a local program), which compresses fundamentals and networking into roughly one to two years, or the ''stage''/line cook path of working through unpaid or low-paid kitchen trial shifts and line cook jobs without formal schooling, which is common and respected in the industry; either way, real progression depends on getting hired onto a serious kitchen''s line and proving yourself station by station, not credentials alone.', 'Line Cook at a specific station (garde manger, saute, grill) -> Station Chef/Chef de Partie -> Sous Chef -> Executive Sous Chef -> Executive Chef/Head Chef -> some go on to open their own restaurant or become a Corporate Chef/Culinary Director overseeing multiple locations, moving up usually means changing restaurants to a more demanding kitchen, not just tenure at one place.', ARRAY['Knife skills and station fundamentals built through culinary school or grinding line cook shifts', 'Physical stamina for standing and moving fast during a 10-12 hour service', 'Working a stage (trial shift) at a kitchen you want to break into, which is literally how many chefs get hired', 'Food cost and menu math if aiming toward executive chef', 'Team leadership under nightly time pressure']::text[], 'People picture creative recipe development as the daily job; the actual day-to-day, especially for line cooks and even many executive chefs, is dominated by repetitive prep, tight cost control, and managing a chaotic service under real time pressure: menu creativity is a small, often after-hours slice of the job, and the hours, nights, weekends, and holidays, are genuinely brutal.', 'The real ''interview'' for line and kitchen roles is a working stage, a trial shift on the line where you''re evaluated on speed, cleanliness, and how you handle service pressure in real time, far more than a conversation; executive chef hiring adds a formal interview and often a tasting or menu presentation testing culinary point of view and cost sense.'),
  ('Barista / Cafe Manager', 'Runs day-to-day cafe operations, balancing consistent product quality with fast-paced customer service.', 38000, 5, 'High school', ARRAY['Customer service', 'Speed under pressure', 'Multitasking', 'Product consistency']::text[], '{"quadrant_a":0.15,"quadrant_b":0.48,"quadrant_c":0.85,"quadrant_d":0.3,"pace_preference":0.8,"risk_tolerance":0.3}'::jsonb, '2025-09-01'::date, '11-9051', 6.4, 65310, 42, 'approximate', 'No dedicated barista code; mapped to Food Service Managers (11-9051) since the Vocateur description emphasizes running day-to-day cafe operations (the "manager" half of the dual title) rather than the counter-service "barista" half.', 'Entry-level barista roles require no formal credential: hiring is based on availability, basic customer service demeanor, and willingness to learn on the job, with most training happening in the first weeks on shift; moving into cafe management usually comes from being promoted internally after proving reliability and skill on bar, sometimes helped by an independent barista certification like SCA courses for those pursuing specialty coffee seriously.', 'Barista -> Shift Lead/Keyholder -> Assistant Manager -> Cafe/Store Manager -> Multi-unit/District Manager for chains, or Owner, since many baristas eventually open their own independent cafe. Specialty coffee also has a parallel prestige track (competitive latte art, barista championships, roasting) that isn''t about management titles at all.', ARRAY['Speed and consistency under rush pressure, which is what separates good baristas from great ones', 'Basic cash handling and POS systems', 'Customer service under pressure, including de-escalating unhappy customers', 'Basic scheduling, inventory, and P&L literacy if pursuing management', 'Espresso and brewing technical knowledge (SCA courses) if pursuing specialty coffee']::text[], 'People picture a relaxed, artisanal job of making pretty latte art; the actual job, especially at busy locations, is high-speed, repetitive, physically tiring work on your feet, with rush hours demanding sub-minute drink times, where consistency under pressure matters far more than creative flair.', 'Entry-level interviews are brief and mostly assess availability, reliability, and basic customer-facing demeanor; management-track interviews add scenario questions about handling an understaffed rush or a conflict with a difficult customer or employee, testing composure and practical problem-solving rather than technical coffee knowledge.'),
  ('Commercial Pilot (Charter/Cargo)', 'Operates aircraft on variable routes following the same rigorous procedural checklists as commercial aviation.', 106000, 5, 'Flight certification', ARRAY['Procedural discipline', 'Situational awareness', 'Navigation', 'Composure under pressure']::text[], '{"quadrant_a":0.42,"quadrant_b":0.92,"quadrant_c":0.22,"quadrant_d":0.15,"pace_preference":0.6,"risk_tolerance":0.3}'::jsonb, '2025-09-01'::date, '53-2012', 5.1, 122670, 6.6, 'exact', 'Direct match to BLS Commercial Pilots (53-2012).', 'Same fundamental hour-building path as airline pilots: flight school ratings through a Commercial Pilot certificate, then building hours as a flight instructor or in entry-level flying jobs, but charter/cargo operators often accept somewhat lower total hours than regional airlines and value specific experience like night flying, single-pilot IFR, or mountain/backcountry flying that airlines don''t prioritize as heavily; Part 135 charter or on-demand operators are the common first real commercial flying job after instructing.', 'Flight instructor/hour-building -> Part 135 charter or cargo First Officer/single-pilot role -> Captain at a charter/cargo operator -> larger cargo carrier, such as regional freight feeders flying for major carriers'' feeder contracts -> some eventually flow into passenger airlines once they have enough hours, others build a career staying in charter/cargo for its different lifestyle, which can mean less rigid scheduling and more varied flying.', ARRAY['Flight hour accumulation, the same bottleneck as airline pilots: budget time and money for this early', 'Instrument rating and real instrument flying experience, since charter/cargo flies in weather airlines might avoid', 'Multi-engine rating', 'Comfort flying solo/single-pilot with full decision-making responsibility and no co-pilot backup', 'Night flying experience, since cargo is disproportionately overnight']::text[], 'People assume it''s a lesser version of airline flying; charter and cargo pilots often fly more demanding, hands-on missions with short runways, less air traffic control support, single-pilot decision-making, and night and weather flying, with far less standardization and support than a major airline crew gets: it can be more operationally challenging, not less.', 'Interviews test flight hours and specific experience relevant to the operation, such as night, mountain, or unimproved runway flying and single-pilot IFR, plus a check ride or sim evaluation of procedural knowledge, with less emphasis on airline-style standardized crew-resource-management scoring and more on raw individual pilot judgment and adaptability.'),
  ('Real Estate Agent', 'Guides clients through property transactions, negotiating deals and managing relationships under variable pace.', 54300, 3, 'High school + real estate license', ARRAY['Negotiation', 'Relationship building', 'Local market knowledge', 'Persistence']::text[], '{"quadrant_a":0.2,"quadrant_b":0.25,"quadrant_c":0.85,"quadrant_d":0.45,"pace_preference":0.55,"risk_tolerance":0.6}'::jsonb, '2025-09-01'::date, '41-9022', 3.1, 56320, 36.6, 'exact', 'Direct match to BLS Real Estate Sales Agents (41-9022).', 'Requires completing state-mandated pre-licensing coursework and passing the state real estate licensing exam, then affiliating with a sponsoring brokerage, required in nearly every state to practice: there''s no employer ''hiring'' you in the traditional sense; new agents are essentially independent contractors who must generate their own client leads from day one, which is why most new agents earn very little in their first year.', 'New Agent, building a client base often through a team or mentor at a larger brokerage -> Established Agent with a self-sustaining referral/repeat-client pipeline -> Team Lead, recruiting and splitting commission with junior agents working under your brand -> Broker, after passing the separate broker''s license exam, able to open and run your own brokerage, many successful agents plateau as high-earning independents rather than climbing to broker/owner, since individual production can be more lucrative than managing a team.', ARRAY['Local market knowledge, built by studying comps and neighborhoods relentlessly before you have clients', 'Cold-calling, prospecting, and lead generation, the actual bottleneck for new agents', 'Negotiation practice', 'Building a personal brand and network, since most business comes from your existing sphere of influence', 'A financial cushion to survive commission-only income for the first year or more']::text[], 'People picture a glamorous job of showing beautiful homes; the actual day-to-day for most agents, especially new ones, is dominated by prospecting and lead generation, cold calls, open houses, social media, and following up on expired listings, with showings and closings being the reward for a much larger volume of unpaid marketing effort. Most new agents quit within the first two years due to income instability.', 'Brokerages ''interview'' new agents mostly to assess motivation, coachability, and financial runway to survive the ramp-up period rather than technical real estate knowledge, since that''s what the licensing exam and required training cover; the exam itself functions as the real technical gate, testing property law, contracts, and disclosure requirements.'),
  ('Dental Hygienist', 'Provides preventive dental care following clinical protocol in a structured, appointment-based setting.', 87530, 9, 'Associate degree + license', ARRAY['Clinical protocol', 'Patient care', 'Attention to detail', 'Manual dexterity']::text[], '{"quadrant_a":0.25,"quadrant_b":0.88,"quadrant_c":0.45,"quadrant_d":0.05,"pace_preference":0.45,"risk_tolerance":0.1}'::jsonb, '2025-09-01'::date, '29-1292', 7, 94260, 15.3, 'exact', 'Direct match to BLS Dental Hygienists (29-1292).', 'Requires an Associate''s degree, most common, or Bachelor''s from an accredited dental hygiene program, including substantial supervised clinical hours, then passing the National Board Dental Hygiene Examination and a state or regional clinical licensing exam; dental hygiene programs are competitive to get into, with limited seats and prerequisite science coursework, plus often required dental office observation hours before applying.', 'Dental Hygienist, with most hygienists staying in direct clinical practice, often working across a few days or offices -> Lead Hygienist/Clinical Coordinator in a larger practice -> some move into dental hygiene education, sales or clinical education roles with dental product companies, or public health dental hygiene roles, unlike many healthcare fields, there isn''t a strong manager ladder since most of the job''s value is the direct clinical hours themselves, and many hygienists intentionally work part-time across multiple offices for flexibility.', ARRAY['Strong performance in science prerequisites (anatomy, physiology, chemistry) to get into a hygiene program', 'Securing dental office observation/shadowing hours before applying, often required by programs', 'Manual dexterity practice', 'Patient communication skills, since you spend the most one-on-one time with patients at a dental visit', 'Radiography certification']::text[], 'People think it''s a simpler or lesser version of being a dentist; hygienists carry real independent clinical judgment, assessing periodontal disease, taking and reading X-rays, and educating patients, and repetitive strain injury risk from the physical posture demands of the job is a serious, underdiscussed occupational hazard.', 'Program admission interviews assess manual dexterity aptitude and communication skills alongside science grades; job interviews at a practice focus on clinical technique comfort, bedside manner with anxious patients, and fit with the specific office''s pace and patient volume expectations.'),
  ('Graphic Designer', 'Creates visual concepts and layouts for brands and media, often working within client constraints.', 60510, 3, 'Bachelor''s degree', ARRAY['Visual design', 'Software tools (Adobe suite)', 'Creative concepting', 'Client feedback iteration']::text[], '{"quadrant_a":0.2,"quadrant_b":0.25,"quadrant_c":0.42,"quadrant_d":0.88,"pace_preference":0.45,"risk_tolerance":0.4}'::jsonb, '2025-09-01'::date, '27-1024', 2.1, 61300, 20, 'exact', 'Direct match to BLS Graphic Designers (27-1024).', 'A strong portfolio is the dominant credential: a design degree helps build that portfolio and network but plenty of working designers are self-taught or bootcamp-trained; internships and freelance or spec work that gets real client feedback, not just personal projects, is what typically converts into a first full-time junior designer role, since employers hire based on demonstrated client-ready work.', 'Junior/Associate Designer -> Graphic Designer -> Senior Designer -> Art Director -> Creative Director, with some moving agency-side and others staying in-house at a single brand, many graphic designers also go independent or freelance at some point since the skill set supports solo client work well, which has its own separate progression of building a recurring client base.', ARRAY['Adobe Creative Suite fluency (Photoshop, Illustrator, InDesign), a near-universal baseline', 'Building a portfolio with real or realistic client briefs, not just personal art', 'Typography and layout fundamentals', 'Giving and receiving critique gracefully, a huge part of daily agency or in-house life', 'Basic client communication for freelance work']::text[], 'People picture pure creative self-expression; the actual job is heavily constrained by brand guidelines, client feedback rounds that are often frustrating and subjective, and tight deadlines: creative freedom is often a small fraction of the actual work, especially early career or in-house at a single brand.', 'The portfolio review is the core of the interview, presenting and defending design decisions and process rather than just showing final polished work, often paired with a design exercise or take-home brief testing how you handle real creative constraints and feedback within a deadline.'),
  ('Elementary School Teacher', 'Plans and delivers structured lessons daily, balancing curriculum requirements with individual student needs.', 63670, 1, 'Bachelor''s degree + certification', ARRAY['Lesson planning', 'Classroom management', 'Patience', 'Communication']::text[], '{"quadrant_a":0.2,"quadrant_b":0.5,"quadrant_c":0.88,"quadrant_d":0.25,"pace_preference":0.4,"risk_tolerance":0.2}'::jsonb, '2025-09-01'::date, '25-2021', -2, 62340, 91, 'exact', 'Direct match to BLS Elementary School Teachers, Except Special Education (25-2021).', 'Requires a Bachelor''s degree in education, or a related field plus a certification/credentialing program, including supervised student teaching, then passing state-required licensing exams; alternative certification paths like Teach For America or district-run alternative licensure programs let people with non-education degrees teach while completing certification requirements concurrently, a common non-traditional entry route especially in high-need districts.', 'Student Teacher -> First-year Teacher, often with a mentor teacher assigned -> Tenured/Experienced Classroom Teacher -> some move into Lead Teacher, Instructional Coach, or grade-level team lead roles, others pursue a Master''s and move into Curriculum Specialist, Instructional Coach, or school Administrator (Assistant Principal, Principal) roles, many teachers stay in the classroom their whole career since the pay/title ladder for staying a classroom teacher is relatively flat compared to moving into administration.', ARRAY['Student teaching performance, the real proving ground before your first job', 'Classroom management technique, which makes or breaks new teachers far more than content knowledge', 'Lesson planning aligned to state standards', 'Basic behavioral/developmental knowledge for the specific age group', 'Patience and emotional regulation under constant, low-level demands']::text[], 'People picture mostly the classroom hours; the real time commitment includes substantial unpaid hours grading, planning lessons, and communicating with parents outside contracted hours, and classroom management, not subject knowledge, is what overwhelms most new teachers in their first year or two.', 'Interviews typically include a sample lesson demonstration or teaching a mock lesson to the hiring committee, plus behavioral questions about classroom management scenarios like a disruptive student or an upset parent: districts are explicitly testing whether you can control a room and handle real behavioral situations, not just whether you know the material.'),
  ('Event Planner', 'Coordinates complex logistics for events, blending tight sequencing with creative problem-solving on the fly.', 56770, 7, 'Bachelor''s degree', ARRAY['Vendor coordination', 'Sequencing under pressure', 'Creative troubleshooting', 'Client communication']::text[], '{"quadrant_a":0.15,"quadrant_b":0.85,"quadrant_c":0.28,"quadrant_d":0.45,"pace_preference":0.75,"risk_tolerance":0.4}'::jsonb, '2025-09-01'::date, '13-1121', 4.8, 59440, 15.5, 'exact', 'Direct match to BLS Meeting, Convention, and Event Planners (13-1121).', 'No universal licensing requirement: entry is typically through an internship or junior coordinator role at a venue, catering company, event agency, or hotel, or by planning smaller events like weddings or parties independently to build a portfolio and referral network; a hospitality/event management degree or a certification like Certified Meeting Professional for corporate/conference planners helps credibility but isn''t strictly required, especially on the wedding and social event side of the industry.', 'Event Coordinator/Assistant -> Event Planner -> Senior Planner/Account Manager -> Director of Events at a venue, agency, or corporation''s internal events team -> many experienced planners go independent, building their own client roster, particularly in weddings and high-end social events where personal brand matters more than firm affiliation.', ARRAY['Vendor relationship-building with caterers, venues, and rental companies, a real asset that takes years to build', 'Meticulous logistics and checklist management', 'Calm real-time problem-solving, since something always goes wrong day-of', 'Budget management', 'Portfolio-building by planning any real event you can, even small or unpaid ones early on']::text[], 'People picture the creative, glamorous parts like design boards and tastings; the actual job is dominated by spreadsheets, contracts, vendor logistics, and stressful day-of troubleshooting like a late vendor, a weather change, or a guest medical issue. The fun creative planning is front-loaded weeks or months out, while the actual event day is high-stress crisis management.', 'Interviews and client pitch meetings, which function similarly, focus on a portfolio of past events and specific stories of how you handled something going wrong in real time, since composure under last-minute chaos is the trait clients and employers are actually screening for, not just aesthetic taste.'),
  ('Film / TV Director', 'Shapes creative vision for a production, making high-stakes artistic calls with no single right answer.', 85320, 7, 'Varies, often no formal requirement', ARRAY['Creative vision', 'Improvisation', 'Risk-taking', 'Collaborative leadership']::text[], '{"quadrant_a":0.1,"quadrant_b":0.15,"quadrant_c":0.5,"quadrant_d":0.95,"pace_preference":0.5,"risk_tolerance":0.75}'::jsonb, '2025-09-01'::date, '27-2012', 4.9, 83480, 12.8, 'close', 'Matches BLS Producers and Directors (27-2012), which combines the two roles; no film/TV-specific split exists.', 'No standard credential: common doors are film school, which builds a portfolio/thesis film and an industry network, or working up through production roles (PA, then assistant director) on real sets to learn the process hands-on, plus building a body of short films, music videos, or commercials that demonstrates a visual voice; increasingly, a viral short film, web series, or strong social media presence, especially for commercial/branded content directors, can also open doors that used to require formal industry connections.', 'Short films/PA-AD track -> music videos, commercials, or indie features building a reel -> first low-budget feature or TV episode, your ''first credit'' -> episodic TV directing, since many directors build a career directing episodes of established shows rather than only features -> established feature director or showrunner-adjacent TV director with real financing power, the path is notoriously non-linear and depends heavily on one project''s reception opening the next door, more than tenure.', ARRAY['Building a reel/portfolio of directed work, starting with anything, shorts or spec commercials', 'On-set experience in any role to learn production logistics and what''s actually feasible to direct', 'Visual storytelling fundamentals (shot composition, editing rhythm)', 'Collaborative leadership, since directing means managing dozens of specialists'' work toward one vision', 'Resilience for a career with long gaps between paid work']::text[], 'People picture directors as solitary visionaries dictating every creative choice; the real job is intensely collaborative and managerial, coordinating cinematographers, actors, editors, and producers, constantly making fast decisions under budget and schedule pressure, and defending your vision against financiers'' notes far more than working in creative isolation.', 'There''s no standard job interview: directors are hired based on their reel and prior work and a general meeting or pitch, such as a TV directing pitch on how you''d approach a specific episode or a feature director''s take on the script, where producers and financiers assess your specific creative vision and whether you can execute it within their budget and schedule constraints.');
